SCHEMA = "stellar-forge.sf100.duckdb-workspace.v1"
_HEX = re.compile(r"^[0-9a-f]{64}$")
_NAME = re.compile(r"^[A-Za-z][A-Za-z0-9_]{0,119}$")
_DECIMAL = re.compile(r"^DECIMAL\(([1-9][0-9]?),([0-9]{1,2})\)$")
_TYPES = {"VARCHAR", "BOOLEAN", "BIGINT", "HUGEINT", "DOUBLE", "DATE", "TIMESTAMP", "TIMESTAMPTZ", "JSON"}
_FILES = ("manifest.json", "dataset.jsonl", "dataset.csv", "review.html")
_LINE = 2_097_152
_CHUNK = 1_048_576
_FORMAT = "stellar-forge.sf88.dataset-delivery.v1"


def _now():
    return datetime.now(timezone.utc).isoformat()


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, sort_keys=True, separators=(",", ":"))


def _wire(value):
    if isinstance(value, Decimal):
        return str(value)
    if type(value) is int and abs(value) > 9_007_199_254_740_991:
        return str(value)
    if isinstance(value, (date, datetime)):
        return value.isoformat()
    if isinstance(value, bytes):
        return {"encoding": "hex", "value": value.hex()}
    if isinstance(value, (tuple, list)):
        return [_wire(item) for item in value]
    if isinstance(value, dict):
        return {str(key): _wire(item) for key, item in value.items()}
    if isinstance(value, float) and not math.isfinite(value):
        return {"number": str(value)}
    return value


def _qid(value):
    if not isinstance(value, str) or not value or len(value.encode()) > 240 or "\x00" in value:
        raise StateError("DUCKDB_COLUMN_NAME_INVALID")
    return '"' + value.replace('"', '""') + '"'


def _name(value):
    if not isinstance(value, str) or not _NAME.fullmatch(value) or value.lower().startswith(("sf_", "duckdb_", "sqlite_")):
        raise StateError("DUCKDB_NAME_INVALID")
    return value


def _hex(value):
    if not isinstance(value, str) or not _HEX.fullmatch(value):
        raise StateError("DUCKDB_ID_INVALID")
    return value


def _type(value):
    if not isinstance(value, str):
        raise StateError("DUCKDB_TYPE_INVALID")
    value = value.upper().replace(" ", "")
    match = _DECIMAL.fullmatch(value)
    if value not in _TYPES and not match:
        raise StateError("DUCKDB_TYPE_INVALID")
    if match and not 0 <= int(match[2]) <= int(match[1]) <= 38:
        raise StateError("DUCKDB_DECIMAL_RANGE_INVALID")
    return value


def _kind(value):
    if value is None:
        return "null"
    if type(value) is bool:
        return "boolean"
    if type(value) is int:
        return "integer"
    if isinstance(value, (float, Decimal)):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, list):
        return "array"
    if isinstance(value, dict):
        return "object"
    raise StateError("DUCKDB_JSON_TYPE_INVALID")


def _exact_json(value):
    """Serialize Decimal JSON numbers without converting their value to float."""
    if isinstance(value, Decimal):
        if not value.is_finite():
            raise StateError("DUCKDB_NONFINITE_JSON_NUMBER")
        return str(value)
    if isinstance(value, dict):
        return "{" + ",".join(json.dumps(key, ensure_ascii=False) + ":" + _exact_json(item) for key, item in value.items()) + "}"
    if isinstance(value, list):
        return "[" + ",".join(_exact_json(item) for item in value) + "]"
    return json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":"))


def _row(raw):
    try:
        value = json.loads(raw.decode("utf-8"), object_pairs_hook=unique_object,
                           parse_float=Decimal,
                           parse_constant=lambda _: (_ for _ in ()).throw(ValueError()))
    except (ValueError, UnicodeError):
        raise StateError("DUCKDB_ORIGINAL_ROW_INVALID") from None
    if not isinstance(value, dict):
        raise StateError("DUCKDB_ORIGINAL_ROW_INVALID")
    return value


def _convert(value, column):
    kind = column["type"]
    if value is None:
        if not column["nullable"]:
            raise StateError("DUCKDB_NULL_IN_REQUIRED_COLUMN")
        return None
    if kind == "JSON":
        return _exact_json(value)
    if kind == "VARCHAR":
        if not isinstance(value, str):
            raise StateError("DUCKDB_STRING_MAPPING_REQUIRES_STRING")
        return value
    if kind == "BOOLEAN":
        if type(value) is not bool:
            raise StateError("DUCKDB_BOOLEAN_MAPPING_REQUIRES_BOOLEAN")
        return value
    if kind in {"BIGINT", "HUGEINT"}:
        if type(value) is bool or not (type(value) is int or isinstance(value, str) and re.fullmatch(r"-?(0|[1-9][0-9]*)", value)):
            raise StateError("DUCKDB_INTEGER_MAPPING_INVALID")
        number = int(value)
        bits = 64 if kind == "BIGINT" else 128
        if not -(2 ** (bits - 1)) <= number < 2 ** (bits - 1):
            raise StateError("DUCKDB_INTEGER_OVERFLOW")
        return number
    match = _DECIMAL.fullmatch(kind)
    if match:
        if type(value) is bool or not isinstance(value, (str, int, Decimal)):
            raise StateError("DUCKDB_DECIMAL_REQUIRES_EXACT_VALUE")
        try:
            number = Decimal(value)
            width, scale = int(match[1]), int(match[2])
            if not number.is_finite():
                raise ValueError()
            with localcontext() as context:
                context.prec = 80  # Enough for every supported DECIMAL(1..38,s).
                quantum = Decimal(1).scaleb(-scale)
                quantized = number.quantize(quantum)
                if quantized != number or abs(number) >= Decimal(10) ** (width - scale):
                    raise ValueError()
            return quantized
        except (InvalidOperation, ValueError, OverflowError):
            raise StateError("DUCKDB_DECIMAL_SCALE_OR_WIDTH_LOSS") from None
    if kind == "DOUBLE":
        if type(value) is bool or not isinstance(value, (int, float, Decimal, str)):
            raise StateError("DUCKDB_DOUBLE_MAPPING_INVALID")
        try:
            number = float(value)
            if not math.isfinite(number):
                raise ValueError()
            return number
        except (ValueError, OverflowError):
            raise StateError("DUCKDB_DOUBLE_MAPPING_INVALID") from None
    if not isinstance(value, str):
        raise StateError("DUCKDB_TEMPORAL_MAPPING_REQUIRES_ISO_STRING")
    try:
        if kind == "DATE":
            if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
                raise ValueError()
            return date.fromisoformat(value)
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
        if kind == "TIMESTAMP" and parsed.tzinfo is not None:
            raise ValueError()
        if kind == "TIMESTAMPTZ" and (parsed.tzinfo is None or parsed.utcoffset() is None):
            raise ValueError()
        return parsed
    except ValueError:
        raise StateError("DUCKDB_TEMPORAL_MAPPING_INVALID") from None


def _descriptor(path, name=None):
    checksum = hashlib.sha256()
    size = 0
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
    with os.fdopen(fd, "rb") as stream:
        info = os.fstat(stream.fileno())
        if not stat.S_ISREG(info.st_mode):
            raise StateError("DUCKDB_EXPORT_FILE_INVALID")
        while chunk := stream.read(_CHUNK):
            size += len(chunk)
            checksum.update(chunk)
    suffix = Path(name or path).suffix
    return {"name": name or Path(path).name, "path": str(path), "bytes": size,
            "sha256": checksum.hexdigest(), "mime": {".csv": "text/csv", ".json": "application/json",
            ".parquet": "application/vnd.apache.parquet", ".duckdb": "application/octet-stream"}.get(suffix, "application/octet-stream")}


def _new_destination(value, root):
    path = Path(os.path.abspath(Path(value).expanduser()))
    if path == root or root in path.parents:
        raise StateError("DUCKDB_DESTINATION_MUST_BE_OUTSIDE_WORKSPACE")
    private_directory(path.parent)
    if path.exists():
        private_directory(path, create=False)
    else:
        path.mkdir(mode=0o700)
        sync_directory(path.parent)
    return path



def _parquet_result(db):
    """Choose explicit lossless representations before native Parquet writes."""
    description = list(db.execute("SELECT * FROM sf_export_result LIMIT 0").description)
    query_columns = [{"name": item[0], "type": str(item[1])} for item in description]
    if len({column["name"].casefold() for column in query_columns}) != len(query_columns):
        raise StateError("DUCKDB_EXPORT_UNIQUE_COLUMN_NAMES_REQUIRED")
    wide = [column for column in query_columns if column["type"] in {"HUGEINT", "UHUGEINT"}]
    overflow = {}
    if wide:
        checks = [
            "bool_or(" + _qid(column["name"]) + " IS NOT NULL AND try_cast("
            + _qid(column["name"]) + " AS DECIMAL(38,0)) IS NULL)"
            for column in wide
        ]
        values = db.execute("SELECT " + ",".join(checks) + " FROM sf_export_result").fetchone()
        overflow = {column["name"]: bool(value) for column, value in zip(wide, values)}
    projection, encodings = [], []
    for column in query_columns:
        name, native_type = column["name"], column["type"]
        quoted = _qid(name)
        expression, encoding = quoted, "native"
        if native_type in {"HUGEINT", "UHUGEINT"}:
            target_type = "VARCHAR" if overflow[name] else "DECIMAL(38,0)"
            expression = "CAST(" + quoted + " AS " + target_type + ")"
            encoding = "duckdb_text" if target_type == "VARCHAR" else "decimal128"
        else:
            # Quoted member names are labels, not type tokens. Nested wide
            # integers also pass through DuckDB's DOUBLE Parquet writer.
            type_tokens = re.sub(r'"(?:[^"]|"")*"', '""', native_type)
            if re.search(r"\b(?:U?HUGEINT|BIGNUM|VARINT|INTERVAL)\b|\bTIME WITH TIME ZONE\b", type_tokens):
                expression = "CAST(" + quoted + " AS VARCHAR)"
                # Only accept a text representation that the same native type
                # can read back exactly, including nulls and nested values.
                restored = "CAST(" + expression + " AS " + native_type + ")"
                if db.execute("SELECT 1 FROM sf_export_result WHERE " + quoted
                              + " IS DISTINCT FROM " + restored + " LIMIT 1").fetchone():
                    raise StateError("DUCKDB_EXPORT_LOSSLESS_REPRESENTATION_REQUIRED")
                encoding = "duckdb_text"
        projection.append(expression + " AS " + quoted)
        encodings.append({"name": name, "query_type": native_type, "encoding": encoding})
    selected = ",".join(projection)
    result = db.execute("SELECT " + selected + " FROM sf_export_result LIMIT 0")
    columns = [{"name": item[0], "type": str(item[1])} for item in result.description]
    for encoding, column in zip(encodings, columns):
        encoding["parquet_type"] = column["type"]
    return selected, columns, query_columns, encodings


class DuckDBWorkspace:
    """One private native database, reopened per operation under the existing lock."""

    def __init__(self, directory, *, memory_limit="128MB", threads=1):
        try:
            import duckdb
        except ImportError:
            raise StateError("DUCKDB_OPTIONAL_DEPENDENCY_REQUIRED") from None
        self.duckdb = duckdb
        self.directory = private_directory(Path(directory))
        self.path = self.directory / "warehouse.duckdb"
        self.memory_limit = memory_limit
        if type(threads) is not int or not 1 <= threads <= 16:
            raise StateError("DUCKDB_THREADS_INVALID")
        self.threads = threads
        self._mutex = threading.RLock()
        with self._guard(), self._connection(writeable=True) as db:
            db.execute("BEGIN")
            try:
                db.execute("CREATE TABLE IF NOT EXISTS sf_workspace(key VARCHAR PRIMARY KEY,value VARCHAR NOT NULL)")
                existing = db.execute("SELECT value FROM sf_workspace WHERE key='schema'").fetchone()
                if existing and existing[0] != SCHEMA:
                    raise StateError("DUCKDB_WORKSPACE_SCHEMA_MISMATCH")
                db.execute("INSERT INTO sf_workspace VALUES('schema',?) ON CONFLICT DO NOTHING", [SCHEMA])
                initialize_identity(db)
                db.execute("CREATE TABLE IF NOT EXISTS sf_reviews(id VARCHAR PRIMARY KEY,created_at VARCHAR NOT NULL,record VARCHAR NOT NULL)")
                db.execute("CREATE TABLE IF NOT EXISTS sf_editions(id VARCHAR PRIMARY KEY,sequence BIGINT UNIQUE NOT NULL,record VARCHAR NOT NULL)")
                db.execute("CREATE TABLE IF NOT EXISTS sf_files(edition_id VARCHAR,name VARCHAR,bytes BIGINT,sha256 VARCHAR,PRIMARY KEY(edition_id,name))")
                db.execute("CREATE TABLE IF NOT EXISTS sf_file_chunks(edition_id VARCHAR,name VARCHAR,part BIGINT,content BLOB,PRIMARY KEY(edition_id,name,part))")
                db.execute("CREATE TABLE IF NOT EXISTS sf_views(name VARCHAR PRIMARY KEY,edition_id VARCHAR,revision BIGINT)")
                db.execute("CREATE TABLE IF NOT EXISTS sf_view_history(name VARCHAR,revision BIGINT,record VARCHAR,PRIMARY KEY(name,revision))")
                db.execute("CREATE TABLE IF NOT EXISTS sf_queries(id VARCHAR PRIMARY KEY,name VARCHAR UNIQUE,revision BIGINT,record VARCHAR)")
                db.execute("CREATE TABLE IF NOT EXISTS sf_query_history(id VARCHAR,revision BIGINT,record VARCHAR,PRIMARY KEY(id,revision))")
                db.execute("CREATE TABLE IF NOT EXISTS sf_exports(id VARCHAR PRIMARY KEY,record VARCHAR)")
                db.commit()
            except BaseException:
                db.rollback()
                raise
        os.chmod(self.path, 0o600)

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()

    def close(self):
        """Every method has already closed its own native connection."""

    def identity(self):
        """Stable original warehouse identity, retained by portable backups."""
        with self._guard(), self._connection() as db:
            return {"schema": SCHEMA, "workspace_id": read_identity(db)}

    @contextmanager
    def _guard(self):
        with self._mutex, lock(self.directory):
            yield

    @contextmanager
    def _connection(self, *, writeable=False, allowed_paths=(), spatial_extension=None):
        if self.path.exists():
            info = self.path.lstat()
            if not stat.S_ISREG(info.st_mode) or info.st_mode & 0o077 or info.st_nlink != 1:
                raise StateError("DUCKDB_PRIVATE_DATABASE_REQUIRED")
        # DuckDB requires the exact file allowance before external access is
        # disabled. The connection is not yielded until both settings are locked.
        config = {"enable_external_access": "true" if allowed_paths or spatial_extension else "false",
                  "autoinstall_known_extensions": "false",
                  "autoload_known_extensions": "false", "allow_unsigned_extensions": "false",
                  "threads": str(self.threads), "memory_limit": self.memory_limit}
        db = self.duckdb.connect(str(self.path), read_only=not writeable, config=config)
        try:
            if spatial_extension:
                if spatial_extension != "spatial":
                    extension = Path(spatial_extension)
                    info = extension.lstat()
                    if not stat.S_ISREG(info.st_mode) or extension.is_symlink():
                        raise StateError("DUCKDB_SPATIAL_EXTENSION_FILE_INVALID")
                db.execute("LOAD '" + str(spatial_extension).replace("'", "''") + "'")
                db.execute("SET geometry_always_xy=true")
            if allowed_paths:
                literal = "[" + ",".join("'" + str(path).replace("'", "''") + "'" for path in allowed_paths) + "]"
                db.execute("SET allowed_paths=" + literal)
            if allowed_paths or spatial_extension:
                db.execute("SET enable_external_access=false")
            db.execute("SET lock_configuration=true")
            yield db
        finally:
            db.close()

    @staticmethod
    def _record(db, table, identity):
        row = db.execute("SELECT record FROM " + table + " WHERE id=?", [identity]).fetchone()
        if row is None:
            raise StateError("DUCKDB_RECORD_NOT_FOUND")
        return parse(row[0].encode())

    @staticmethod
    def _views(db):
        return [{"name": name, "edition_id": edition, "revision": revision}
                for name, edition, revision in db.execute("SELECT name,edition_id,revision FROM sf_views ORDER BY name").fetchall()]

    def _delivery(self, report_path):
        report_path = Path(os.path.abspath(Path(report_path).expanduser()))
        raw = read(report_path, 8 * 1024 * 1024)
        report = parse(raw)
        # Accept the original bridge's whole output or its unchanged report.
        if isinstance(report, dict) and report.get("mode") == "ORIGINAL_PYTHON_DATASET":
            report = report.get("report")
        if isinstance(report, dict) and isinstance(report.get("session"), dict) and report["session"].get("schema") == "stellar-forge.buyer-delivery.v1":
            report = DatasetDelivery.from_finalized_scan(report).native
        if not isinstance(report, dict) or report.get("schema") not in {_FORMAT, "stellar-forge.sf100.dataset-delivery.v1"}:
            raise StateError("DUCKDB_ORIGINAL_DELIVERY_REPORT_REQUIRED")
        status = report.get("nativeStatus")
        if not isinstance(status, dict) or status.get("complete") is not True or status.get("finalized") is not True:
            raise StateError("DUCKDB_COMPLETE_FINALIZED_DELIVERY_REQUIRED")
        binding = _hex(report.get("sourceBindingSha256"))
        directory = private_directory(Path(report["directory"]), create=False)
        delivery = DatasetDelivery(report, directory)
        manifest_bytes = delivery.file("manifest.json").read_bytes(limit=4 * 1024 * 1024)
        manifest = parse(manifest_bytes)
        dataset = manifest.get("dataset") or {}
        fields, total = dataset.get("projectedFields"), dataset.get("rows")
        pages = manifest.get("sourcePages")
        if (manifest.get("schema") != "stellar-forge.buyer-delivery-manifest.v1"
            or not isinstance(fields, list) or not 1 <= len(fields) <= 1024
            or not all(isinstance(item, str) and item for item in fields)
            or len(set(fields)) != len(fields) or type(total) is not int or not 0 <= total <= 1_000_000
            or not isinstance(pages, list) or status.get("pages") != len(pages)
            or status.get("rows") != total or status.get("snapshot") != dataset.get("snapshot")
            or manifest.get("paymentStatus") != report.get("paymentStatus")):
            raise StateError("DUCKDB_ORIGINAL_MANIFEST_BINDING_INVALID")
        output = report["outputs"].get("dataset.jsonl") or {}
        if manifest.get("outputs", {}).get("dataset.jsonl") != {key: output.get(key) for key in ("bytes", "sha256")}:
            raise StateError("DUCKDB_ORIGINAL_ROWS_BINDING_INVALID")
        return delivery, manifest_bytes, {"report_path": str(report_path), "native": report,
            "manifest": manifest, "fields": fields, "row_count": total,
            "manifest_sha256": digest(manifest_bytes), "source_binding_sha256": binding,
            "input_report_sha256": digest(raw)}

    @staticmethod
    def _rows(delivery, fields, total):
        with delivery.file("dataset.jsonl").open() as stream:
            count = 0
            while raw := stream.readline(_LINE + 1):
                if len(raw) > _LINE or not raw.endswith(b"\n"):
                    raise StateError("DUCKDB_ORIGINAL_ROW_FORMAT_INVALID")
                row = _row(raw)
                if set(row) != set(fields):
                    raise StateError("DUCKDB_ORIGINAL_ROW_FIELDS_CHANGED")
                count += 1
                if count > total:
                    raise StateError("DUCKDB_ORIGINAL_ROW_COUNT_CHANGED")
                yield row
            if count != total:
                raise StateError("DUCKDB_ORIGINAL_ROW_COUNT_CHANGED")

    def inspect_delivery(self, report_path):
        delivery, _, result = self._delivery(report_path)
        types = {field: set() for field in result["fields"]}
        preview = []
        integer_overflow = set()
        for row in self._rows(delivery, result["fields"], result["row_count"]):
            if len(preview) < 20:
                preview.append(_wire(row))
            for field, value in row.items():
                types[field].add(_kind(value))
                if type(value) is int and not -(2**127) <= value < 2**127:
                    integer_overflow.add(field)
        columns = []
        used = {"sf_row"}
        for index, field in enumerate(result["fields"]):
            observed = types[field] - {"null"}
            kind = ({"string": "VARCHAR", "boolean": "BOOLEAN", "integer": "HUGEINT", "number": "JSON"}.get(next(iter(observed)))
                    if len(observed) == 1 else "JSON")
            if field in integer_overflow or not kind:
                kind = "JSON"
            name = field if field.casefold() not in used and "\x00" not in field and len(field.encode()) <= 240 else "column_" + str(index + 1)
            while name.casefold() in used:
                name += "_"
            used.add(name.casefold())
            columns.append({"source": field, "name": name, "type": kind, "nullable": "null" in types[field] or not observed})
        return {**result, "preview": preview, "observed_types": {field: sorted(value) for field, value in types.items()},
                "default_columns": columns,
                **_semantics.delivery_fields(delivery, result["manifest"], columns, document=True)}

    def review_import(self, report_path, columns=None, keys=None):
        inspected = self.inspect_delivery(report_path)
        columns = inspected["default_columns"] if columns is None else columns
        if not isinstance(columns, list) or len(columns) != len(inspected["fields"]):
            raise StateError("DUCKDB_COMPLETE_COLUMN_MAPPING_REQUIRED")
        mapped = []
        for item in columns:
            if not isinstance(item, dict) or set(item) - {"source", "name", "type", "nullable"}:
                raise StateError("DUCKDB_COLUMN_MAPPING_INVALID")
            nullable = item.get("nullable", True)
            if type(nullable) is not bool:
                raise StateError("DUCKDB_NULLABLE_FLAG_INVALID")
            _qid(item.get("name"))
            mapped.append({"source": item.get("source"), "name": item["name"], "type": _type(item.get("type")), "nullable": nullable})
        if set(item["source"] for item in mapped) != set(inspected["fields"]) or len(set(item["source"] for item in mapped)) != len(mapped):
            raise StateError("DUCKDB_SOURCE_COLUMN_MAPPING_INVALID")
        names = [item["name"].casefold() for item in mapped]
        if len(set(names)) != len(names) or "sf_row" in names:
            raise StateError("DUCKDB_COLUMN_NAME_COLLISION")
        keys = [] if keys is None else keys
        if not isinstance(keys, list) or len(set(keys)) != len(keys) or any(key not in [c["name"] for c in mapped] for key in keys):
            raise StateError("DUCKDB_KEY_MAPPING_INVALID")
        delivery, _, source = self._delivery(report_path)
        if source["manifest_sha256"] != inspected["manifest_sha256"] or source["source_binding_sha256"] != inspected["source_binding_sha256"]:
            raise StateError("DUCKDB_DELIVERY_CHANGED_DURING_REVIEW")
        for row in self._rows(delivery, inspected["fields"], inspected["row_count"]):
            for column in mapped:
                _convert(row[column["source"]], column)
        semantic_fields = _semantics.delivery_fields(delivery, source["manifest"], mapped)
        identity = {"schema": SCHEMA, "manifest_sha256": inspected["manifest_sha256"],
                    "source_binding_sha256": inspected["source_binding_sha256"], "columns": mapped, "keys": keys}
        review = {**identity, "review_id": digest(_json(identity).encode()), "report_path": inspected["report_path"],
                  "row_count": inspected["row_count"], "created_at": _now(), "preview": inspected["preview"],
                  "observed_types": inspected["observed_types"], **semantic_fields}
        with self._guard(), self._connection(writeable=True) as db:
            existing = db.execute("SELECT record FROM sf_reviews WHERE id=?", [review["review_id"]]).fetchone()
            if existing:
                return {**parse(existing[0].encode()), **semantic_fields}
            db.execute("INSERT INTO sf_reviews VALUES(?,?,?)", [review["review_id"], review["created_at"], _json(review)])
        return review

    def reviews(self):
        with self._guard(), self._connection() as db:
            return {"reviews": [parse(row[0].encode()) for row in db.execute("SELECT record FROM sf_reviews ORDER BY created_at DESC").fetchall()]}

    def import_review(self, review_id):
        review_id = _hex(review_id)
        with self._guard(), self._connection(writeable=True) as db:
            review = self._record(db, "sf_reviews", review_id)
            existing = db.execute("SELECT record FROM sf_editions WHERE id=?", [review_id]).fetchone()
            if existing:
                return {**_semantics.edition_fields(db, parse(existing[0].encode())),
                        "import_status": "UNCHANGED"}
            delivery, manifest_raw, source = self._delivery(review["report_path"])
            if source["manifest_sha256"] != review["manifest_sha256"] or source["source_binding_sha256"] != review["source_binding_sha256"]:
                raise StateError("DUCKDB_REVIEWED_DELIVERY_CHANGED")
            table = "sf_edition_" + review_id
            columns = review["columns"]
            semantic_fields = _semantics.delivery_fields(delivery, source["manifest"], columns)
            definitions = ["sf_row BIGINT PRIMARY KEY"] + [_qid(c["name"]) + " " + c["type"] + ("" if c["nullable"] else " NOT NULL") for c in columns]
            db.execute("BEGIN")
            try:
                db.execute("CREATE TABLE " + _qid(table) + "(" + ",".join(definitions) + ")")
                sql = "INSERT INTO " + _qid(table) + " VALUES(" + ",".join("?" for _ in range(len(columns) + 1)) + ")"
                count = 0
                batch = []
                for row in self._rows(delivery, source["fields"], source["row_count"]):
                    count += 1
                    batch.append([count] + [_convert(row[c["source"]], c) for c in columns])
                    if len(batch) == 256:
                        db.executemany(sql, batch)
                        batch.clear()
                if batch:
                    db.executemany(sql, batch)
                if review["keys"]:
                    keys_sql = ",".join(_qid(key) for key in review["keys"])
                    null_sql = " OR ".join(_qid(key) + " IS NULL" for key in review["keys"])
                    if db.execute("SELECT count(*) FROM " + _qid(table) + " WHERE " + null_sql).fetchone()[0]:
                        raise StateError("DUCKDB_NULL_KEY")
                    if db.execute("SELECT 1 FROM " + _qid(table) + " GROUP BY " + keys_sql + " HAVING count(*)>1 LIMIT 1").fetchone():
                        raise StateError("DUCKDB_DUPLICATE_KEY")
                files = []
                for name in delivery.file_names():
                    metadata = delivery.native["outputs"].get(name) or delivery.native["archives"][name]
                    checksum, length, part = hashlib.sha256(), 0, 0
                    with delivery.file(name).open() as stream:
                        while chunk := stream.read(_CHUNK):
                            checksum.update(chunk)
                            length += len(chunk)
                            db.execute("INSERT INTO sf_file_chunks VALUES(?,?,?,?)", [review_id, name, part, chunk])
                            part += 1
                    if length != metadata["bytes"] or checksum.hexdigest() != metadata["sha256"]:
                        raise StateError("DUCKDB_ORIGINAL_SOURCE_CHANGED")
                    db.execute("INSERT INTO sf_files VALUES(?,?,?,?)", [review_id, name, length, checksum.hexdigest()])
                    files.append({"name": name, "bytes": length, "sha256": checksum.hexdigest()})
                input_raw = read(Path(review["report_path"]), 8 * 1024 * 1024)
                if digest(input_raw) != source["input_report_sha256"]:
                    raise StateError("DUCKDB_ORIGINAL_REPORT_CHANGED")
                db.execute("INSERT INTO sf_files VALUES(?,?,?,?)", [review_id, "input-report.json", len(input_raw), digest(input_raw)])
                db.execute("INSERT INTO sf_file_chunks VALUES(?,?,0,?)", [review_id, "input-report.json", input_raw])
                report_raw = _json(delivery.native).encode()
                db.execute("INSERT INTO sf_files VALUES(?,?,?,?)", [review_id, "delivery-report.json", len(report_raw), digest(report_raw)])
                db.execute("INSERT INTO sf_file_chunks VALUES(?,?,0,?)", [review_id, "delivery-report.json", report_raw])
                sequence = db.execute("SELECT coalesce(max(sequence),0)+1 FROM sf_editions").fetchone()[0]
                record = {"schema": SCHEMA, "edition_id": review_id, "sequence": sequence, "table": table,
                          "created_at": _now(), "row_count": count, "columns": columns, "keys": review["keys"],
                          "row_order_column": "sf_row", "source": {**source, "files": files},
                          "review_id": review_id, "manifest_sha256": digest(manifest_raw), **semantic_fields}
                db.execute("INSERT INTO sf_editions VALUES(?,?,?)", [review_id, sequence, _json(record)])
                received = _semantics.edition_fields(db, record)
                db.commit()
                return {**received, "import_status": "IMPORTED"}
            except BaseException:
                db.rollback()
                raise

    def edition(self, edition_id):
        with self._guard(), self._connection() as db:
            return _semantics.edition_fields(db, self._record(db, "sf_editions", _hex(edition_id)))

    def semantics(self, edition_id):
        with self._guard(), self._connection() as db:
            return _semantics.edition_context(db, self._record(db, "sf_editions", _hex(edition_id)))

    def semantics_bytes(self, edition_id):
        with self._guard(), self._connection() as db:
            return _semantics.dictionary_bytes(db, self._record(db, "sf_editions", _hex(edition_id)))

    def compare_semantics(self, before_id, after_id):
        with self._guard(), self._connection() as db:
            before = self._record(db, "sf_editions", _hex(before_id))
            after = self._record(db, "sf_editions", _hex(after_id))
            return {"before_id": before_id, "after_id": after_id,
                    **_semantics.compare_contexts(_semantics.edition_context(db, before),
                        _semantics.edition_context(db, after), before["columns"], after["columns"])}

    def editions(self, limit=100, before=None):
        if type(limit) is not int or not 1 <= limit <= 1000 or before is not None and (type(before) is not int or before < 1):
            raise StateError("DUCKDB_HISTORY_PAGE_INVALID")
        with self._guard(), self._connection() as db:
            rows = db.execute("SELECT sequence,record FROM sf_editions WHERE (? IS NULL OR sequence<?) ORDER BY sequence DESC LIMIT ?", [before, before, limit + 1]).fetchall()
            return {"editions": [parse(row[1].encode()) for row in rows[:limit]],
                    "next_before": rows[limit - 1][0] if len(rows) > limit else None}

    def views(self):
        with self._guard(), self._connection() as db:
            return self._views(db)

    def activate(self, name, edition_id, expected_revision):
        name, edition_id = _name(name), _hex(edition_id)
        if type(expected_revision) is not int or expected_revision < 0:
            raise StateError("DUCKDB_VIEW_REVISION_REQUIRED")
        with self._guard(), self._connection(writeable=True) as db:
            db.execute("BEGIN")
            try:
                edition = self._record(db, "sf_editions", edition_id)
                current = db.execute("SELECT name,edition_id,revision FROM sf_views WHERE lower(name)=lower(?)", [name]).fetchone()
                revision = current[2] if current else 0
                if revision != expected_revision:
                    raise StateError("DUCKDB_VIEW_CHANGED")
                if current and current[1] == edition_id:
                    db.commit()
                    return {"name": current[0], "revision": revision, "edition": edition, "activation_status": "UNCHANGED"}
                if current:
                    name = current[0]
                    db.execute("DROP VIEW " + _qid(name))
                db.execute("CREATE VIEW " + _qid(name) + " AS SELECT * FROM " + _qid(edition["table"]))
                db.execute("INSERT INTO sf_views VALUES(?,?,?) ON CONFLICT(name) DO UPDATE SET edition_id=excluded.edition_id,revision=excluded.revision", [name, edition_id, revision + 1])
                result = {"name": name, "revision": revision + 1, "edition": edition, "activated_at": _now(), "previous_edition": current[1] if current else None}
                db.execute("INSERT INTO sf_view_history VALUES(?,?,?)", [name, revision + 1, _json(result)])
                db.commit()
                return result
            except BaseException:
                db.rollback()
                raise

    def _sql(self, sql, parameters):
        if not isinstance(sql, str) or not sql.strip() or len(sql.encode()) > 262144 or not isinstance(parameters, (list, tuple, dict)):
            raise StateError("DUCKDB_QUERY_INVALID")
        # Parse on an isolated native connection: parser preprocessing cannot
        # affect retained sequences or data in the customer's database.
        parser = self.duckdb.connect(":memory:", config={"enable_external_access": "false",
            "autoinstall_known_extensions": "false", "autoload_known_extensions": "false", "threads": "1", "memory_limit": "32MB"})
        try:
            parser.execute("SET lock_configuration=true")
            statements = parser.extract_statements(sql)
            if len(statements) != 1 or statements[0].type != self.duckdb.StatementType.SELECT:
                raise StateError("DUCKDB_SELECT_QUERY_REQUIRED")
        finally:
            parser.close()
        # The native engine accepts the reviewed SQL; strip a single terminal
        # delimiter only for its controlled subquery wrappers.
        return sql.strip().removesuffix(";").rstrip()

    def query(self, sql, parameters=None, max_rows=200, expected_views=None):
        parameters = [] if parameters is None else parameters
        sql = self._sql(sql, parameters)
        if type(max_rows) is not int or not 1 <= max_rows <= 100000:
            raise StateError("DUCKDB_QUERY_PREVIEW_LIMIT_INVALID")
        with self._guard(), self._connection() as db:
            db.execute("BEGIN")
            try:
                views = self._views(db)
                if expected_views is not None and expected_views != views:
                    raise StateError("DUCKDB_VIEW_CHANGED")
                result = db.execute(sql, parameters)
                columns = [{"name": c[0], "type": str(c[1])} for c in result.description]
                rows = result.fetchmany(max_rows + 1)
                meanings = _semantics.query_context(db, sql, views)
                db.commit()
                return {"columns": columns, "rows": _wire(rows[:max_rows]), "truncated": len(rows) > max_rows,
                        "views": views, "source_meanings": meanings}
            except BaseException:
                db.rollback()
                raise

    def save_query(self, name, sql, parameters=None, expected_revision=0):
        name = _name(name)
        parameters = [] if parameters is None else parameters
        sql = self._sql(sql, parameters)
        # Stored parameters use the original JSON caller representation.
        _json(parameters)
        if type(expected_revision) is not int or expected_revision < 0:
            raise StateError("DUCKDB_QUERY_REVISION_REQUIRED")
        query_id = digest(name.casefold().encode())
        with self._guard(), self._connection(writeable=True) as db:
            db.execute("BEGIN")
            try:
                current = db.execute("SELECT revision,record FROM sf_queries WHERE id=?", [query_id]).fetchone()
                revision = current[0] if current else 0
                if revision != expected_revision:
                    raise StateError("DUCKDB_SAVED_QUERY_CHANGED")
                if current:
                    prior = parse(current[1].encode())
                    if prior["sql"] == sql and prior["parameters"] == parameters:
                        db.commit()
                        return {**prior, "parameters_text": _json(prior["parameters"])}
                    name = prior["name"]
                record = {"query_id": query_id, "name": name, "revision": revision + 1, "sql": sql,
                          "parameters": parameters, "saved_at": _now()}
                db.execute("INSERT INTO sf_queries VALUES(?,?,?,?) ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,record=excluded.record", [query_id, name, revision + 1, _json(record)])
                db.execute("INSERT INTO sf_query_history VALUES(?,?,?)", [query_id, revision + 1, _json(record)])
                db.commit()
                return {**record, "parameters_text": _json(record["parameters"])}
            except BaseException:
                db.rollback()
                raise

    def queries(self):
        with self._guard(), self._connection() as db:
            records = [parse(row[0].encode()) for row in db.execute("SELECT record FROM sf_queries ORDER BY name").fetchall()]
            return {"queries": [{**record, "parameters_text": _json(record["parameters"])} for record in records]}

    def exports(self):
        with self._guard(), self._connection() as db:
            return {"exports": [parse(row[0].encode()) for row in db.execute("SELECT record FROM sf_exports ORDER BY id").fetchall()]}

    def export_query(self, query_id, destination, expected_revision, expected_views=None):
        query_id = _hex(query_id)
        if type(expected_revision) is not int or expected_revision < 1:
            raise StateError("DUCKDB_QUERY_REVISION_REQUIRED")
        with self._guard():
            target = _new_destination(destination, self.directory)
            request_file = target / "request.json"
            if request_file.exists():
                request = parse(read(request_file, 8 * 1024 * 1024))
                query = request.get("query", {})
                if (request.get("schema") != SCHEMA + ".query-export"
                    or request.get("workspace") != str(self.directory)
                    or query.get("query_id") != query_id or query.get("revision") != expected_revision
                    or request.get("directory") != str(target)):
                    raise StateError("DUCKDB_EXPORT_DESTINATION_CONFLICT")
                if expected_views is not None and expected_views != request["views"]:
                    raise StateError("DUCKDB_EXPORT_VIEW_CONFLICT")
                # The retained original revision owns this export even when
                # the operator has since saved a newer version of the recipe.
                views = request["views"]
            else:
                if any(target.iterdir()):
                    raise StateError("DUCKDB_EXPORT_DESTINATION_NOT_EMPTY")
                with self._connection() as db:
                    query = self._record(db, "sf_queries", query_id)
                    views = self._views(db)
                if query["revision"] != expected_revision:
                    raise StateError("DUCKDB_SAVED_QUERY_CHANGED")
                if expected_views is not None and expected_views != views:
                    raise StateError("DUCKDB_VIEW_CHANGED")
                identity = {"schema": SCHEMA + ".query-export", "workspace": str(self.directory),
                            "query": query, "views": views, "directory": str(target)}
                request = {**identity, "export_id": digest(_json(identity).encode()), "created_at": _now()}
                dump(request_file, request, exclusive=True)
            complete = target / "manifest.json"
            if complete.exists():
                record = parse(read(complete, 16 * 1024 * 1024))
                if record.get("export_id") != request["export_id"]:
                    raise StateError("DUCKDB_EXPORT_DESTINATION_CONFLICT")
                for item in record["files"]:
                    actual = _descriptor(target / item["name"], item["name"])
                    if actual["bytes"] != item["bytes"] or actual["sha256"] != item["sha256"]:
                        raise StateError("DUCKDB_EXPORT_CHANGED")
                record["files"].append(_descriptor(complete))
                with self._connection(writeable=True) as db:
                    db.execute("INSERT INTO sf_exports VALUES(?,?) ON CONFLICT(id) DO UPDATE SET record=excluded.record",
                               [record["export_id"], _json(record)])
                return record
            parquet, csv = target / "result.parquet", target / "result.csv"
            partial = target / "result.parquet.partial"
            execution_file = target / "execution.json"
            execution = parse(read(execution_file, 8 * 1024 * 1024)) if execution_file.exists() else None
            if execution is not None and execution.get("export_id") != request["export_id"]:
                raise StateError("DUCKDB_EXPORT_EXECUTION_CHANGED")

            def verify(path, expected, code):
                if not isinstance(expected, dict):
                    raise StateError(code)
                actual = _descriptor(path)
                if actual["bytes"] != expected.get("bytes") or actual["sha256"] != expected.get("sha256"):
                    raise StateError(code)

            def publish(part, final, expected):
                verify(part, expected, "DUCKDB_RETAINED_QUERY_RESULT_CHANGED")
                os.rename(part, final)
                sync_directory(target)

            if not parquet.exists():
                if execution is not None and execution.get("parquet"):
                    if not partial.exists():
                        raise StateError("DUCKDB_RETAINED_PARQUET_MISSING")
                    publish(partial, parquet, execution["parquet"])
                else:
                    if partial.exists():
                        partial.rename(target / ("interrupted-" + _descriptor(partial)["sha256"] + ".parquet"))
                    with self._connection(allowed_paths=[partial, parquet]) as db:
                        db.execute("BEGIN")
                        try:
                            if self._views(db) != views:
                                raise StateError("DUCKDB_VIEW_CHANGED")
                            sql = self._sql(query["sql"], query["parameters"])
                            # Do not wrap the SELECT: trailing comments and
                            # valid WITH/ORDER/LIMIT clauses retain their meaning.
                            db.execute("CREATE TEMP TABLE sf_export_result AS " + sql, query["parameters"])
                            rows = db.execute("SELECT count(*) FROM sf_export_result").fetchone()[0]
                            meanings = _semantics.query_context(db, sql, views)
                            projection, columns, query_columns, encodings = _parquet_result(db)
                            db.execute("COPY (SELECT " + projection
                                       + " FROM sf_export_result) TO ? (FORMAT PARQUET, COMPRESSION ZSTD)",
                                       [str(partial)])
                            with open(partial, "rb") as stream:
                                os.fsync(stream.fileno())
                            os.chmod(partial, 0o600)
                            execution = {"export_id": request["export_id"], "rows": rows, "columns": columns,
                                         "query_columns": query_columns, "column_encodings": encodings,
                                         "views": views, "parquet": _descriptor(partial, "result.parquet"),
                                         "source_meanings": meanings}
                            execution["parquet"]["path"] = str(parquet)
                            # Identity is durable before publication, so a
                            # reopened export accepts only these exact bytes.
                            dump(execution_file, execution)
                            publish(partial, parquet, execution["parquet"])
                            db.commit()
                        except BaseException:
                            db.rollback()
                            raise
            if execution is None:
                raise StateError("DUCKDB_EXPORT_EXECUTION_MISSING")
            verify(parquet, execution.get("parquet"), "DUCKDB_RETAINED_QUERY_RESULT_CHANGED")
            csv_partial = target / "result.csv.partial"
            with self._connection(allowed_paths=[parquet, csv_partial]) as db:
                result = db.execute("SELECT * FROM read_parquet(?) LIMIT 0", [str(parquet)])
                columns = [{"name": c[0], "type": str(c[1])} for c in result.description]
                rows = db.execute("SELECT count(*) FROM read_parquet(?)", [str(parquet)]).fetchone()[0]
                if rows != execution["rows"] or columns != execution["columns"]:
                    raise StateError("DUCKDB_RETAINED_QUERY_RESULT_CHANGED")
                if not csv.exists():
                    if execution.get("csv"):
                        if not csv_partial.exists():
                            raise StateError("DUCKDB_RETAINED_CSV_MISSING")
                        publish(csv_partial, csv, execution["csv"])
                    else:
                        if csv_partial.exists():
                            csv_partial.rename(target / ("interrupted-" + _descriptor(csv_partial)["sha256"] + ".csv"))
                        db.execute("COPY (SELECT * FROM read_parquet($parquet_source)) TO $csv_target (FORMAT CSV, HEADER TRUE, NULL '\\N', FORCE_QUOTE *)",
                                   {"parquet_source": str(parquet), "csv_target": str(csv_partial)})
                        with open(csv_partial, "rb") as stream:
                            os.fsync(stream.fileno())
                        os.chmod(csv_partial, 0o600)
                        execution["csv"] = _descriptor(csv_partial, "result.csv")
                        execution["csv"]["path"] = str(csv)
                        dump(execution_file, execution)
                        publish(csv_partial, csv, execution["csv"])
            verify(csv, execution.get("csv"), "DUCKDB_RETAINED_QUERY_RESULT_CHANGED")
            meanings, dictionary_files = None, []
            if "source_meanings" in execution:
                with self._connection() as db:
                    meanings, dictionary_files = _semantics.export_dictionaries(db, execution["source_meanings"], target)
            files = [_descriptor(path) for path in (parquet, csv, request_file, execution_file)] + dictionary_files
            record = {**request, "state": "COMPLETE", "completed_at": _now(), "rows": rows,
                      "columns": columns, "query_columns": execution.get("query_columns", columns),
                      "column_encodings": execution.get("column_encodings", []),
                      "files": files, "csv_null_marker": "\\N",
                      "source_editions": sorted({view["edition_id"] for view in views}),
                      **({"source_meanings": meanings} if meanings is not None else {})}
            dump(complete, record, exclusive=True)
            # The manifest describes members; its download record also includes
            # the manifest without creating a self-referential digest.
            record["files"].append(_descriptor(complete))
            with self._connection(writeable=True) as db:
                db.execute("INSERT INTO sf_exports VALUES(?,?) ON CONFLICT(id) DO UPDATE SET record=excluded.record",
                           [record["export_id"], _json(record)])
            return record

    def compare(self, before_id, after_id, keys=None, max_rows=200):
        before_id, after_id = _hex(before_id), _hex(after_id)
        if type(max_rows) is not int or not 1 <= max_rows <= 100000:
            raise StateError("DUCKDB_COMPARISON_PREVIEW_LIMIT_INVALID")
        with self._guard(), self._connection() as db:
            before, after = self._record(db, "sf_editions", before_id), self._record(db, "sf_editions", after_id)
            keys = before["keys"] if keys is None else keys
            a, b = {c["name"]: c for c in before["columns"]}, {c["name"]: c for c in after["columns"]}
            if not isinstance(keys, list) or not keys or len(set(keys)) != len(keys) or any(k not in a or k not in b or a[k]["type"] != b[k]["type"] for k in keys):
                raise StateError("DUCKDB_COMPARISON_COMPATIBLE_KEYS_REQUIRED")
            for edition in (before, after):
                table = _qid(edition["table"])
                nulls = " OR ".join(_qid(k) + " IS NULL" for k in keys)
                if db.execute("SELECT 1 FROM " + table + " WHERE " + nulls + " LIMIT 1").fetchone():
                    raise StateError("DUCKDB_COMPARISON_NULL_KEY")
                if db.execute("SELECT 1 FROM " + table + " GROUP BY " + ",".join(_qid(k) for k in keys) + " HAVING count(*)>1 LIMIT 1").fetchone():
                    raise StateError("DUCKDB_COMPARISON_NONUNIQUE_KEY")
            comparable = [name for name in a if name in b and a[name]["type"] == b[name]["type"]]
            schema = {"added": [name for name in b if name not in a], "removed": [name for name in a if name not in b],
                      "changed": [{"name": name, "before": a[name], "after": b[name]} for name in a if name in b and a[name] != b[name]]}
            join = " AND ".join("a." + _qid(k) + "=b." + _qid(k) for k in keys)
            diff = " OR ".join("a." + _qid(k) + " IS DISTINCT FROM b." + _qid(k) for k in comparable) or "FALSE"
            category = "CASE WHEN a.sf_row IS NULL THEN 'added' WHEN b.sf_row IS NULL THEN 'removed' WHEN " + diff + " THEN 'changed' ELSE 'unchanged' END"
            relation = " FROM " + _qid(before["table"]) + " a FULL OUTER JOIN " + _qid(after["table"]) + " b ON " + join
            totals = dict(db.execute("SELECT " + category + " AS kind,count(*)" + relation + " GROUP BY kind").fetchall())
            projected = ["coalesce(a." + _qid(k) + ",b." + _qid(k) + ") AS " + _qid("key_" + str(i)) for i, k in enumerate(keys)]
            projected += ["a." + _qid(k) for k in a] + ["b." + _qid(k) for k in b]
            sql = "SELECT " + category + " AS kind," + ",".join(projected) + relation + " WHERE a.sf_row IS NULL OR b.sf_row IS NULL OR " + diff + " ORDER BY " + ",".join(_qid("key_" + str(i)) for i in range(len(keys))) + " LIMIT ?"
            rows = db.execute(sql, [max_rows + 1]).fetchall()
            changes = []
            for row in rows[:max_rows]:
                offset = 1 + len(keys)
                changes.append({"kind": row[0], "key": _wire(dict(zip(keys, row[1:offset]))),
                                "before": None if row[0] == "added" else _wire(dict(zip(a, row[offset:offset + len(a)]))),
                                "after": None if row[0] == "removed" else _wire(dict(zip(b, row[offset + len(a):])))})
            return {"before": before_id, "after": after_id, "keys": keys, "columns": schema,
                    "summary": {kind: totals.get(kind, 0) for kind in ("added", "removed", "changed", "unchanged")},
                    "changes": changes, "truncated": len(rows) > max_rows,
                    "comparison_columns": comparable,
                    "comparison_basis": "Common columns with identical SQL types; structural changes are listed separately.",
                    "source_scope": {"before": before["source"]["manifest"]["dataset"],
                                     "after": after["source"]["manifest"]["dataset"]},
                    "source_meanings": _semantics.compare_contexts(_semantics.edition_context(db, before),
                        _semantics.edition_context(db, after), before["columns"], after["columns"])}

    def export_source(self, edition_id, destination):
        edition_id = _hex(edition_id)
        with self._guard(), self._connection() as db:
            edition = self._record(db, "sf_editions", edition_id)
            target = _new_destination(destination, self.directory)
            files = []
            for name, expected_bytes, expected_sha in db.execute("SELECT name,bytes,sha256 FROM sf_files WHERE edition_id=? ORDER BY name", [edition_id]).fetchall():
                output = target / name
                private_directory(output.parent)
                if output.exists():
                    descriptor = _descriptor(output, name)
                else:
                    fd, tmp = tempfile.mkstemp(prefix=".source-", dir=target)
                    try:
                        with os.fdopen(fd, "wb") as stream:
                            cursor = db.execute("SELECT content FROM sf_file_chunks WHERE edition_id=? AND name=? ORDER BY part", [edition_id, name])
                            while row := cursor.fetchone():
                                stream.write(row[0])
                            stream.flush()
                            os.fsync(stream.fileno())
                        descriptor = _descriptor(Path(tmp), name)
                        if descriptor["bytes"] != expected_bytes or descriptor["sha256"] != expected_sha:
                            raise StateError("DUCKDB_RETAINED_SOURCE_CHANGED")
                        os.link(tmp, output)
                        sync_directory(output.parent)
                        if output.parent != target:
                            sync_directory(target)
                    finally:
                        os.unlink(tmp)
                    descriptor["path"] = str(output)
                if descriptor["bytes"] != expected_bytes or descriptor["sha256"] != expected_sha:
                    raise StateError("DUCKDB_SOURCE_DESTINATION_CONFLICT")
                files.append(descriptor)
            return {"schema": SCHEMA + ".source", "directory": str(target), "edition_id": edition_id,
                    "files": files, "original_source": edition["source"]}

    def backup(self, destination):
        with self._guard():
            target = _new_destination(destination, self.directory)
            output = target / "warehouse.duckdb"
            partial = target / "warehouse.duckdb.partial"
            request_file = target / "handoff-request.json"
            manifest = target / "handoff.json"

            def verified_record(path):
                record = parse(read(path, 16 * 1024 * 1024))
                if (record.get("schema") != SCHEMA + ".handoff"
                    or record.get("source_directory") != str(self.directory)
                    or record.get("directory") != str(target)):
                    raise StateError("DUCKDB_HANDOFF_DESTINATION_CONFLICT")
                return record

            def verify(path, expected):
                actual = _descriptor(path)
                if actual["bytes"] != expected["bytes"] or actual["sha256"] != expected["sha256"]:
                    raise StateError("DUCKDB_HANDOFF_CHANGED")

            if manifest.exists():
                record = verified_record(manifest)
                for item in record["files"]:
                    verify(target / item["name"], item)
                record["files"].append(_descriptor(manifest))
                return record
            if request_file.exists():
                record = verified_record(request_file)
                expected = record["files"][0]
                if output.exists():
                    verify(output, expected)
                elif partial.exists():
                    verify(partial, expected)
                    os.rename(partial, output)
                    sync_directory(target)
                else:
                    raise StateError("DUCKDB_RETAINED_HANDOFF_MISSING")
            else:
                if output.exists() or any(path.name != partial.name and not path.name.startswith("interrupted-")
                                          for path in target.iterdir()):
                    raise StateError("DUCKDB_HANDOFF_DESTINATION_NOT_EMPTY")
                if partial.exists():
                    partial.rename(target / ("interrupted-" + _descriptor(partial)["sha256"] + ".duckdb"))
                with self._connection(writeable=True) as db:
                    db.execute("CHECKPOINT")
                    editions = [parse(row[0].encode()) for row in db.execute("SELECT record FROM sf_editions ORDER BY sequence").fetchall()]
                    views = self._views(db)
                    original_files = [row[0] for row in db.execute("SELECT DISTINCT name FROM sf_files ORDER BY name").fetchall()]
                # All native connections close before copying under the
                # workspace lock. A complete copy is retained before publishing.
                source_fd = os.open(self.path, os.O_RDONLY | os.O_NOFOLLOW)
                target_fd = os.open(partial, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
                with os.fdopen(source_fd, "rb") as source, os.fdopen(target_fd, "wb") as dest:
                    copy_sparse(source, dest, _CHUNK)
                    dest.flush()
                    os.fsync(dest.fileno())
                descriptor = _descriptor(partial, "warehouse.duckdb")
                descriptor["path"] = str(output)
                record = {"schema": SCHEMA + ".handoff", "directory": str(target),
                          "source_directory": str(self.directory), "created_at": _now(),
                          "files": [descriptor], "editions": editions, "views": views,
                          "reopen": "DuckDBWorkspace(directory)",
                          "embedded_original_files": original_files}
                dump(request_file, record, exclusive=True)
                os.rename(partial, output)
                sync_directory(target)
            record["files"].append(_descriptor(request_file))
            dump(manifest, record, exclusive=True)
            record["files"].append(_descriptor(manifest))
            return record

"""Private localhost HTTP operator for an original DuckDBWorkspace."""
from __future__ import annotations

from contextlib import contextmanager
from datetime import datetime, timezone
import fcntl
import hashlib
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import mimetypes
import os
from pathlib import Path, PurePosixPath
import re
import secrets
import stat
import threading
from urllib.parse import parse_qs, unquote, urlsplit

from . import _duckdb_ui, _spatial_ui, spatial_http
from .duckdb_agent import identity as agent_identity, catalog as agent_catalog, request_record, check_report
from ._analysis_export_http import send_export
from .errors import BuyerError, StateError
from .storage import dump, parse, private_directory, read

_MAX_BODY = 1024 * 1024
_MAX_RECORD = 16 * 1024 * 1024
_ID = re.compile(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,159}")
_MIMES = {
    ".gpkg": "application/geopackage+sqlite3",
    ".parquet": "application/vnd.apache.parquet",
    ".csv": "text/csv;charset=utf-8",
    ".json": "application/json",
    ".duckdb": "application/octet-stream",
    ".zip": "application/zip",
}


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":"))


def _rows(value, key):
    if isinstance(value, dict):
        return value.get(key, [])
    return value if isinstance(value, list) else []


def _identifier(value):
    if not isinstance(value, str) or not _ID.fullmatch(value):
        raise StateError("DUCKDB_OPERATOR_ID_INVALID")
    return value


def _fields(value, required=(), optional=()):
    if not isinstance(value, dict) or set(value) - set(required) - set(optional):
        raise StateError("DUCKDB_OPERATOR_FIELDS_INVALID")
    if any(name not in value for name in required):
        raise StateError("DUCKDB_OPERATOR_FIELDS_REQUIRED")
    return value


def _integer(value, name, minimum=0, maximum=1_000_000_000):
    if type(value) is not int or not minimum <= value <= maximum:
        raise StateError("DUCKDB_OPERATOR_" + name.upper() + "_INVALID")
    return value


def _file_entries(record):
    files = record.get("files", [])
    if isinstance(files, dict):
        files = [dict(value, name=key) if isinstance(value, dict) else {"name": key, "path": value}
                 for key, value in files.items()]
    directory = Path(record["directory"]).expanduser().resolve()
    selected, names = [], set()
    for source in files:
        if not isinstance(source, dict):
            raise StateError("DUCKDB_OPERATOR_DOWNLOAD_MANIFEST_INVALID")
        item = dict(source)
        path = Path(str(item.get("path") or item.get("name") or ""))
        if path.is_absolute():
            try:
                relative = path.relative_to(directory).as_posix()
            except ValueError:
                raise StateError("DUCKDB_OPERATOR_DOWNLOAD_OUTSIDE_EXPORT") from None
        else:
            relative = path.as_posix()
        name = item.get("name") or relative
        if (not isinstance(name, str) or not name or name.startswith("/")
                or "\\" in name or any(part in {"", ".", ".."} for part in name.split("/"))
                or name in names):
            raise StateError("DUCKDB_OPERATOR_DOWNLOAD_NAME_INVALID")
        item["name"] = name
        item["path"] = str(path)
        names.add(name)
        selected.append(item)
    return selected


class DuckDBOperator:
    """Serialize native operations and retain portable handoff records locally."""

    def __init__(self, workspace, *, export_root=None, handoff_root=None, spatial_extension=None):
        self.workspace = workspace
        self.spatial_extension = spatial_extension
        self.directory = private_directory(Path(workspace.directory))
        self.mutex = threading.RLock()
        self.export_root = Path(export_root or (str(self.directory) + ".exports"))
        self.handoff_root = Path(handoff_root or (str(self.directory) + ".handoffs"))
        self.handoffs = private_directory(self.directory / "operator-handoffs")
        self.requests = private_directory(self.directory / "operator-requests")
        self._owner = os.open(self.directory / "duckdb-http.lock",
                              os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW, 0o600)
        try:
            info = os.fstat(self._owner)
            if (not stat.S_ISREG(info.st_mode) or info.st_nlink != 1
                    or info.st_mode & 0o077):
                raise StateError("DUCKDB_OPERATOR_PRIVATE_LOCK_REQUIRED")
            fcntl.flock(self._owner, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BaseException:
            os.close(self._owner)
            self._owner = None
            raise StateError("DUCKDB_OPERATOR_ALREADY_OPEN") from None

    def close(self):
        if self._owner is not None:
            os.close(self._owner)
            self._owner = None

    def _handoff_rows(self):
        rows = []
        for path in sorted(self.handoffs.glob("handoff-*.json")):
            record = parse(read(path, _MAX_RECORD))
            if not isinstance(record, dict) or not _ID.fullmatch(str(record.get("export_id", ""))):
                raise StateError("DUCKDB_OPERATOR_HANDOFF_RECORD_INVALID")
            rows.append(record)
        return sorted(rows, key=lambda row: row.get("created_at", ""), reverse=True)

    def state(self):
        with self.mutex:
            editions = self.workspace.editions(limit=100)
            return {
                **self.workspace.identity(),
                "directory": str(self.directory),
                "engine": "DuckDB",
                "editions": _rows(editions, "editions"),
                "next_before": editions.get("next_before") if isinstance(editions, dict) else None,
                "views": _rows(self.workspace.views(), "views"),
                "queries": _rows(self.workspace.queries(), "queries"),
                "reviews": _rows(self.workspace.reviews(), "reviews"),
                "exports": _rows(self.workspace.exports(), "exports"),
                "handoffs": self._handoff_rows(),
                "operations": self.operation_records(),
                "spatial": spatial_http.spatial(self).status(),
            }

    def export_record(self, export_id):
        _identifier(export_id)
        with self.mutex:
            records = self._handoff_rows() if export_id.startswith("handoff-") else _rows(self.workspace.exports(), "exports")
            for record in records:
                if record.get("export_id") == export_id:
                    return dict(record, files=_file_entries(record))
        raise StateError("DUCKDB_OPERATOR_EXPORT_NOT_FOUND")

    def review_record(self, review_id):
        _identifier(review_id)
        with self.mutex:
            for record in _rows(self.workspace.reviews(), "reviews"):
                if record.get("review_id") == review_id:
                    return record
        raise StateError("DUCKDB_OPERATOR_REVIEW_NOT_FOUND")

    def query_record(self, query_id):
        _identifier(query_id)
        with self.mutex:
            for record in _rows(self.workspace.queries(), "queries"):
                if record.get("query_id") == query_id:
                    return record
        raise StateError("DUCKDB_OPERATOR_QUERY_NOT_FOUND")

    def _destination(self, root, request_id):
        parent = private_directory(root)
        return str(parent / request_id)

    @staticmethod
    def _request_id(value):
        if not isinstance(value, str) or not re.fullmatch(r"[0-9a-f]{32}", value):
            raise StateError("DUCKDB_OPERATOR_REQUEST_ID_REQUIRED")
        return value

    def operation_records(self):
        records = []
        for path in self.requests.glob("*.request.json"):
            original = parse(read(path, _MAX_BODY))
            request_id = self._request_id(original.get("request_id"))
            status_path = self.requests / (request_id + ".status.json")
            status = parse(read(status_path, _MAX_RECORD)) if status_path.exists() else {"state": "PREPARED"}
            records.append({**original, **status})
        return sorted(records, key=lambda row: row["created_at"], reverse=True)

    def resume(self, request_id):
        request_id = self._request_id(request_id)
        with self.mutex:
            original = parse(read(self.requests / (request_id + ".request.json"), _MAX_BODY))
            return self.perform(original["route"], original["body"])

    def _retained_action(self, route, body):
        if route == "/api/exports":
            _fields(body, ("query_id", "expected_revision", "request_id"), ("expected_views",))
            _identifier(body["query_id"])
            _integer(body["expected_revision"], "revision", 1)
        elif route == "/api/spatial/exports":
            spatial_http.validate_export(body)
        elif route == "/api/source-handoffs":
            _fields(body, ("edition_id", "request_id"))
            _identifier(body["edition_id"])
        else:
            _fields(body, ("request_id",))
        request_id = self._request_id(body["request_id"])
        path = self.requests / (request_id + ".request.json")
        status_path = self.requests / (request_id + ".status.json")
        if path.exists():
            original = parse(read(path, _MAX_BODY))
            if original.get("route") != route or original.get("body") != body:
                raise StateError("DUCKDB_OPERATOR_ORIGINAL_REQUEST_CHANGED")
        else:
            original = {"request_id": request_id, "route": route, "body": body,
                        "directory": self._destination(self.export_root if route in {"/api/exports", "/api/spatial/exports"} else self.handoff_root, request_id),
                        "created_at": datetime.now(timezone.utc).isoformat()}
            dump(path, original, exclusive=True)
        dump(status_path, {"state": "RUNNING", "updated_at": datetime.now(timezone.utc).isoformat()})
        try:
            if route == "/api/exports":
                result = self.workspace.export_query(body["query_id"], original["directory"],
                    expected_revision=body["expected_revision"], expected_views=body.get("expected_views"))
            elif route == "/api/spatial/exports":
                result = spatial_http.export(self, body, original["directory"])
            else:
                native = (self.workspace.export_source(body["edition_id"], original["directory"])
                          if route == "/api/source-handoffs" else self.workspace.backup(original["directory"]))
                # Keep a small receiving index. Native source and warehouse
                # metadata remain in their original exported files.
                result = {key: native[key] for key in ("schema", "directory", "files", "edition_id",
                          "embedded_original_files", "reopen") if key in native}
                result.update(export_id="handoff-" + request_id,
                    kind="edition-source" if route == "/api/source-handoffs" else "source-handoff",
                    created_at=original["created_at"])
                if "editions" in native:
                    result["edition_count"] = len(native["editions"])
                record_path = self.handoffs / (result["export_id"] + ".json")
                dump(record_path, result)
            dump(status_path, {"state": "COMPLETE", "export_id": result["export_id"],
                               "updated_at": datetime.now(timezone.utc).isoformat()})
            return result
        except Exception as exc:
            try:
                dump(status_path, {"state": "INTERRUPTED", "error": getattr(exc, "code", type(exc).__name__),
                                   "updated_at": datetime.now(timezone.utc).isoformat()})
            except OSError:
                pass
            raise

    def perform(self, route, body):
        with self.mutex:
            if route.startswith("/api/spatial/"):
                return spatial_http.perform(self, route, body)
            if route == "/api/inspect-delivery":
                _fields(body, ("report_path",))
                return self.workspace.inspect_delivery(body["report_path"])
            if route == "/api/reviews":
                _fields(body, ("report_path",), ("columns", "keys"))
                return self.workspace.review_import(body["report_path"],
                    columns=body.get("columns"), keys=body.get("keys", []))
            if route == "/api/import":
                _fields(body, ("review_id",))
                return self.workspace.import_review(_identifier(body["review_id"]))
            if route == "/api/activate":
                _fields(body, ("name", "edition_id", "expected_revision"))
                return self.workspace.activate(body["name"], _identifier(body["edition_id"]),
                    expected_revision=_integer(body["expected_revision"], "revision"))
            if route == "/api/query":
                _fields(body, ("sql",), ("parameters", "max_rows", "expected_views"))
                return self.workspace.query(body["sql"], parameters=body.get("parameters", []),
                    max_rows=_integer(body.get("max_rows", 200), "max_rows", 1, 10000),
                    expected_views=body.get("expected_views"))
            if route == "/api/queries":
                _fields(body, ("name", "sql"), ("parameters", "expected_revision"))
                return self.workspace.save_query(body["name"], body["sql"],
                    parameters=body.get("parameters", []),
                    expected_revision=_integer(body.get("expected_revision", 0), "revision"))
            if route in {"/api/exports", "/api/source-handoffs", "/api/handoffs"}:
                return self._retained_action(route, body)
            if route == "/api/compare-meanings":
                _fields(body, ("before_id", "after_id"))
                return self.workspace.compare_semantics(_identifier(body["before_id"]), _identifier(body["after_id"]))
            if route == "/api/compare":
                _fields(body, ("before_id", "after_id"), ("keys", "max_rows"))
                return self.workspace.compare(_identifier(body["before_id"]), _identifier(body["after_id"]),
                    keys=body.get("keys"),
                    max_rows=_integer(body.get("max_rows", 200), "max_rows", 1, 10000))
        raise StateError("DUCKDB_OPERATOR_ROUTE_NOT_FOUND")

    @contextmanager
    def download(self, export_id, filename):
        """Validate the saved manifest and stream its exact retained descriptor."""
        record = self.export_record(export_id)
        if (not isinstance(filename, str) or not filename or PurePosixPath(filename).is_absolute()
                or "\\" in filename or any(part in {"", ".", ".."} for part in filename.split("/"))):
            raise StateError("DUCKDB_OPERATOR_DOWNLOAD_NAME_INVALID")
        selected = next((item for item in record["files"] if item["name"] == filename), None)
        if selected is None:
            raise StateError("DUCKDB_OPERATOR_DOWNLOAD_NOT_FOUND")
        expected_hash = selected.get("sha256")
        expected_size = selected.get("bytes", selected.get("size"))
        if (not isinstance(expected_hash, str) or not re.fullmatch(r"[0-9a-f]{64}", expected_hash)
                or type(expected_size) is not int or expected_size < 0):
            raise StateError("DUCKDB_OPERATOR_DOWNLOAD_MANIFEST_INVALID")
        directory = Path(record["directory"]).expanduser().resolve(strict=True)
        relative = Path(selected.get("path") or filename)
        target = relative if relative.is_absolute() else directory / relative
        # Only exact manifest names resolve; every component stays within this export.
        if not target.parent.resolve(strict=True).is_relative_to(directory):
            raise StateError("DUCKDB_OPERATOR_DOWNLOAD_OUTSIDE_EXPORT")
        fd = os.open(target, os.O_RDONLY | os.O_NOFOLLOW)
        with os.fdopen(fd, "rb") as stream:
            before = os.fstat(stream.fileno())
            if (not stat.S_ISREG(before.st_mode) or before.st_nlink != 1
                    or before.st_mode & 0o077 or before.st_size != expected_size):
                raise StateError("DUCKDB_OPERATOR_DOWNLOAD_CHANGED")
            actual_hash = hashlib.file_digest(stream, "sha256").hexdigest()
            after = os.fstat(stream.fileno())
            if (actual_hash != expected_hash or
                    (before.st_size, before.st_mtime_ns, before.st_ctime_ns) !=
                    (after.st_size, after.st_mtime_ns, after.st_ctime_ns)):
                raise StateError("DUCKDB_OPERATOR_DOWNLOAD_CHANGED")
            stream.seek(0)
            mime = selected.get("mime") or _MIMES.get(target.suffix.lower()) or mimetypes.guess_type(filename)[0] or "application/octet-stream"
            yield stream, {"name": filename, "bytes": expected_size, "sha256": expected_hash, "mime": mime}


def serve(workspace, *, port=0, export_root=None, handoff_root=None,
          spatial_extension=None, vgi=False, vgi_export_locations=None):
    """Return server, private launch record and browser URL on IPv4 loopback."""
    _integer(port, "port", 0, 65535)
    operator = DuckDBOperator(workspace, export_root=export_root, handoff_root=handoff_root, spatial_extension=spatial_extension)
    token = secrets.token_urlsafe(32)
    vgi_operator = None
    try:
        if vgi:
            from .vgi_service.operator import VgiOperator
            vgi_operator = VgiOperator(operator, export_locations=vgi_export_locations)
    except BaseException:
        operator.close()
        raise

    class Handler(BaseHTTPRequestHandler):
        server_version = "StellarForgeDuckDB"
        sys_version = ""

        def setup(self):
            super().setup()
            self.connection.settimeout(30)

        def log_message(self, *args):
            pass

        def _headers(self, name=None):
            self.send_header("Cache-Control", "no-store")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.send_header("Referrer-Policy", "no-referrer")
            self.send_header("Content-Security-Policy",
                "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; "
                "base-uri 'none'; frame-ancestors 'none'; form-action 'none'")
            if name:
                safe = re.sub(r'[^A-Za-z0-9_.-]', "_", name)
                self.send_header("Content-Disposition", 'attachment; filename="' + safe + '"')

        def _reply(self, status, body, mime="application/json;charset=utf-8", *, filename=None):
            payload = body if isinstance(body, bytes) else _json(body).encode()
            self.send_response(status)
            self.send_header("Content-Type", mime)
            self.send_header("Content-Length", str(len(payload)))
            self._headers(filename)
            self.end_headers()
            if self.command != "HEAD":
                self.wfile.write(payload)

        def _dispatch(self):
            origin = "http://127.0.0.1:" + str(self.server.server_port)
            if (self.headers.get_all("Host") != [origin[7:]]
                    or self.headers.get("Origin", origin) != origin
                    or self.headers.get("Sec-Fetch-Site", "none") not in {"none", "same-origin"}):
                return self._reply(403, {"error": "DUCKDB_OPERATOR_LOCAL_ORIGIN_REQUIRED"})
            url = urlsplit(self.path)
            if url.scheme or url.netloc or url.fragment:
                return self._reply(400, {"error": "DUCKDB_OPERATOR_ROUTE_INVALID"})
            assets = {
                "/": (_duckdb_ui.HTML, "text/html;charset=utf-8"),
                "/app.js": (_duckdb_ui.JS, "text/javascript;charset=utf-8"),
                "/spatial.js": (_spatial_ui.JS, "text/javascript;charset=utf-8"),
                "/style.css": (_duckdb_ui.CSS, "text/css;charset=utf-8"),
            }
            if vgi_operator is not None:
                assets.update(vgi_operator.assets())
            if self.command in {"GET", "HEAD"} and url.path in assets and not url.query:
                value, mime = assets[url.path]
                return self._reply(200, value.encode(), mime)
            capabilities = self.headers.get_all("X-DuckDB-Capability", [])
            if len(capabilities) != 1 or not secrets.compare_digest(capabilities[0], token):
                return self._reply(403, {"error": "DUCKDB_OPERATOR_CAPABILITY_REQUIRED"})
            workspace_ids = self.headers.get_all("X-DuckDB-Workspace-ID", [])
            if workspace_ids and (len(workspace_ids) != 1 or not secrets.compare_digest(
                    workspace_ids[0], workspace.identity()["workspace_id"])):
                return self._reply(409, {"error": "DUCKDB_OPERATOR_WORKSPACE_ID_CHANGED"})
            parameters = parse_qs(url.query, strict_parsing=True)
            if any(len(values) != 1 for values in parameters.values()):
                raise StateError("DUCKDB_OPERATOR_PARAMETERS_INVALID")
            parts = [unquote(part) for part in url.path.strip("/").split("/")]
            if self.command in {"GET", "HEAD"}:
                if vgi_operator is not None and url.path.startswith("/api/vgi/"):
                    return self._reply(200, vgi_operator.read(url.path, parameters))
                if len(parts) == 4 and parts[:2] == ["api", "exports"] and parts[3] == "file":
                    if set(parameters) != {"name"}:
                        raise StateError("DUCKDB_OPERATOR_DOWNLOAD_NAME_REQUIRED")
                    with operator.download(parts[2], parameters["name"][0]) as (stream, record):
                        send_export(self, stream, record)
                    return
                if url.path == "/api/editions":
                    if set(parameters) - {"before", "limit"}:
                        raise StateError("DUCKDB_OPERATOR_PARAMETERS_INVALID")
                    before = int(parameters["before"][0]) if "before" in parameters else None
                    limit = _integer(int(parameters.get("limit", ["100"])[0]), "limit", 1, 100)
                    with operator.mutex:
                        return self._reply(200, workspace.editions(limit=limit, before=before))
                if len(parts) == 3 and parts[:2] == ["api", "catalog"]:
                    if set(parameters) - {"offset", "limit"}:
                        raise StateError("DUCKDB_OPERATOR_PARAMETERS_INVALID")
                    return self._reply(200, agent_catalog(operator, parts[2],
                        offset=int(parameters.get("offset", ["0"])[0]),
                        limit=int(parameters.get("limit", ["25"])[0])))
                if parameters:
                    raise StateError("DUCKDB_OPERATOR_PARAMETERS_INVALID")
                if url.path == "/api/identity":
                    return self._reply(200, agent_identity(operator))
                if len(parts) == 3 and parts[:2] == ["api", "requests"]:
                    return self._reply(200, request_record(operator, parts[2]))
                if url.path.startswith("/api/spatial/"):
                    with operator.mutex:
                        return self._reply(200, spatial_http.get(operator, url.path))
                if url.path == "/api/state":
                    return self._reply(200, operator.state())
                if len(parts) == 4 and parts[:2] == ["api", "editions"] and parts[3] in {"semantics", "semantics-file"}:
                    with operator.mutex:
                        edition_id = _identifier(parts[2])
                        if parts[3] == "semantics":
                            return self._reply(200, workspace.semantics(edition_id))
                        raw = workspace.semantics_bytes(edition_id)
                        if raw is None:
                            return self._reply(404, {"error": "DUCKDB_EDITION_NO_SEMANTICS"})
                        return self._reply(200, raw, filename="semantics.json")
                if len(parts) == 3 and parts[:2] == ["api", "editions"]:
                    with operator.mutex:
                        return self._reply(200, workspace.edition(_identifier(parts[2])))
                if len(parts) == 3 and parts[:2] == ["api", "reviews"]:
                    return self._reply(200, operator.review_record(parts[2]))
                if len(parts) == 3 and parts[:2] == ["api", "queries"]:
                    return self._reply(200, operator.query_record(parts[2]))
                if len(parts) == 3 and parts[:2] == ["api", "exports"]:
                    return self._reply(200, operator.export_record(parts[2]))
            elif self.command == "POST" and not url.query:
                if self.headers.get("Transfer-Encoding") or self.headers.get_content_type() != "application/json":
                    return self._reply(415, {"error": "DUCKDB_OPERATOR_JSON_REQUIRED"})
                sizes = self.headers.get_all("Content-Length", [])
                if len(sizes) != 1 or not sizes[0].isascii() or not sizes[0].isdigit():
                    return self._reply(411, {"error": "DUCKDB_OPERATOR_LENGTH_REQUIRED"})
                length = int(sizes[0])
                if not 0 < length <= _MAX_BODY:
                    return self._reply(413, {"error": "DUCKDB_OPERATOR_REQUEST_SIZE_INVALID"})
                raw = self.rfile.read(length)
                if len(raw) != length:
                    raise StateError("DUCKDB_OPERATOR_REQUEST_INCOMPLETE")
                body = parse(raw)
                if vgi_operator is not None and url.path.startswith("/api/vgi/"):
                    return self._reply(200, vgi_operator.perform(url.path, body))
                if len(parts) == 4 and parts[:2] == ["api", "requests"] and parts[3] == "resume":
                    _fields(body)
                    return self._reply(200, operator.resume(parts[2]))
                source_hashes = self.headers.get_all("X-DuckDB-Source-Sha256", [])
                if source_hashes:
                    if len(source_hashes) != 1 or url.path not in {"/api/inspect-delivery", "/api/reviews"}:
                        raise StateError("DUCKDB_OPERATOR_SOURCE_HEADER_INVALID")
                    with operator.mutex:
                        check_report(body, source_hashes[0])
                        result = operator.perform(url.path, body)
                        check_report(body, source_hashes[0])
                    return self._reply(200, result)
                return self._reply(200, operator.perform(url.path, body))
            return self._reply(404, {"error": "DUCKDB_OPERATOR_NOT_FOUND"})

        def _handle(self):
            try:
                self._dispatch()
            except (BrokenPipeError, ConnectionResetError, TimeoutError):
                self.close_connection = True
            except workspace.duckdb.Error as exc:
                self._reply(400, {"error": "DUCKDB_QUERY_ERROR", "detail": str(exc)[:4096]})
            except BuyerError as exc:
                code = exc.code
                status = 409 if any(word in code for word in ("REVISION", "CHANGED", "BUSY", "EXISTS", "OPEN")) else 400
                self._reply(status, {"error": code})
            except (ValueError, TypeError, KeyError, OverflowError):
                self._reply(400, {"error": "DUCKDB_OPERATOR_REQUEST_INVALID"})
            except OSError:
                self._reply(409, {"error": "DUCKDB_OPERATOR_LOCAL_FILE_UNAVAILABLE"})
            except Exception:
                self._reply(500, {"error": "DUCKDB_OPERATOR_OPERATION_FAILED"})

        do_GET = do_POST = do_HEAD = _handle

    class Server(ThreadingHTTPServer):
        daemon_threads = False

        def server_close(self):
            try:
                super().server_close()
            finally:
                try:
                    if vgi_operator is not None:
                        vgi_operator.close()
                finally:
                    operator.close()

    try:
        server = Server(("127.0.0.1", port), Handler)
        route = "/vgi/" if vgi_operator is not None else "/"
        url = "http://127.0.0.1:" + str(server.server_port) + route + "#" + token
        control = operator.directory / "duckdb-launch.json"
        dump(control, {"schema": "stellar-forge.duckdb-operator-launch.v1",
                       "workspace_id": workspace.identity()["workspace_id"],
                       "directory": str(operator.directory), "pid": os.getpid(), "url": url})
        return server, control, url
    except BaseException:
        if "server" in locals():
            server.server_close()
        else:
            try:
                if vgi_operator is not None:
                    vgi_operator.close()
            finally:
                operator.close()
        raise

"""Source meaning over the original retained DuckDB edition files.

All source verification and SQL mapping use the common dataset semantic reader.
The warehouse's existing file/chunk tables remain the retained byte store.
"""
from __future__ import annotations

import hashlib
import re

from .dataset_semantics import (
    MAX_BYTES, read_delivery_semantics, same_json, sql_context, sql_descriptor,
)
from .errors import StateError
from .storage import digest, parse, private_directory, read, write

CONTEXT_SCHEMA = "stellar-forge.duckdb-source-meanings.v1"
_HEX = re.compile(r"[a-f0-9]{64}")


def _require(value, code):
    if not value:
        raise StateError(code)


def _file_bytes(db, edition_id, name, limit):
    row = db.execute(
        "SELECT bytes,sha256 FROM sf_files WHERE edition_id=? AND name=?",
        [edition_id, name],
    ).fetchone()
    _require(row is not None, "DUCKDB_RETAINED_SEMANTIC_FILE_MISSING")
    size, sha = row
    _require(type(size) is int and 0 <= size <= limit and isinstance(sha, str)
             and _HEX.fullmatch(sha), "DUCKDB_RETAINED_SEMANTIC_FILE_INVALID")
    cursor = db.execute(
        "SELECT part,content FROM sf_file_chunks WHERE edition_id=? AND name=? ORDER BY part",
        [edition_id, name],
    )
    chunks, length, checksum = [], 0, hashlib.sha256()
    while item := cursor.fetchone():
        part, content = item
        _require(part == len(chunks) and isinstance(content, (bytes, bytearray, memoryview)),
                 "DUCKDB_RETAINED_SEMANTIC_CHUNKS_CHANGED")
        content = bytes(content)
        length += len(content)
        _require(length <= size, "DUCKDB_RETAINED_SEMANTIC_FILE_CHANGED")
        checksum.update(content)
        chunks.append(content)
    _require(length == size and checksum.hexdigest() == sha,
             "DUCKDB_RETAINED_SEMANTIC_FILE_CHANGED")
    return b"".join(chunks)


class _EditionFile:
    def __init__(self, db, edition_id, name):
        self.db, self.edition_id, self.name = db, edition_id, name

    def read_bytes(self, *, limit):
        return _file_bytes(self.db, self.edition_id, self.name, limit)


class _EditionFiles:
    """Supply the common reader with original bytes already in this warehouse."""

    def __init__(self, db, edition):
        self.db, self.edition_id = db, edition["edition_id"]
        self.native = edition["source"]["native"]

    def file(self, name):
        return _EditionFile(self.db, self.edition_id, name)


def _mapped(receiving, columns):
    if receiving is None:
        return None
    return sql_descriptor(receiving, [column["source"] for column in columns],
                          [column["name"] for column in columns])


def delivery_fields(delivery, manifest, columns, *, document=False):
    receiving = read_delivery_semantics(delivery, manifest=manifest)
    if receiving is None:
        return {}
    result = {"semantics": _mapped(receiving, columns)}
    if document:
        result["semantic_dictionary"] = receiving["document"]
    return result


def edition_context(db, edition):
    """Read the original checked document without reopening a source directory."""
    original = _file_bytes(db, edition["edition_id"], "manifest.json", 4 * 1024 * 1024)
    manifest = parse(original)
    _require(digest(original) == edition["manifest_sha256"]
             and same_json(manifest, edition["source"]["manifest"]),
             "DUCKDB_RETAINED_SEMANTIC_MANIFEST_CHANGED")
    receiving = read_delivery_semantics(_EditionFiles(db, edition), manifest=manifest)
    if receiving is None:
        _require(edition.get("semantics") is None, "DUCKDB_RETAINED_SEMANTICS_MISSING")
        return None
    descriptor = _mapped(receiving, edition["columns"])
    if edition.get("semantics") is not None:
        _require(same_json(edition["semantics"], descriptor),
                 "DUCKDB_RETAINED_SEMANTIC_MAPPING_CHANGED")
    return {**sql_context(receiving["bytes"], descriptor, edition["edition_id"]),
            "edition_id": edition["edition_id"]}


def edition_fields(db, edition):
    context = edition_context(db, edition)
    if context is None:
        return edition
    return {**edition,
            "semantics": {key: value for key, value in context.items()
                          if key not in {"document", "version_id", "edition_id"}},
            "semantic_dictionary": context["document"]}


def dictionary_bytes(db, edition):
    context = edition_context(db, edition)
    if context is None:
        return None
    return _file_bytes(db, edition["edition_id"], "semantics.json", MAX_BYTES)


def _record(db, edition_id):
    _require(isinstance(edition_id, str) and _HEX.fullmatch(edition_id),
             "DUCKDB_ID_INVALID")
    row = db.execute("SELECT record FROM sf_editions WHERE id=?", [edition_id]).fetchone()
    _require(row is not None, "DUCKDB_RECORD_NOT_FOUND")
    result = parse(row[0].encode())
    _require(result.get("edition_id") == edition_id, "DUCKDB_RETAINED_EDITION_CHANGED")
    return result


def query_context(db, sql, views):
    """Resolve imported relations with the native parser in the query transaction."""
    try:
        required = sorted(db.get_table_names(sql))
    except Exception as error:
        # Parameterized relation functions can require their actual execution.
        # They remain valid queries; do not substitute unrelated view definitions.
        if not type(error).__module__.startswith(("_duckdb", "duckdb")):
            raise
        return {"schema": CONTEXT_SCHEMA, "scope": "REFERENCED_SOURCE_EDITIONS",
                "resolved": False, "relations": [], "unmapped_relations": [], "editions": []}
    by_name = {view["name"].casefold(): view["edition_id"] for view in views}
    selected, unmapped = {}, []
    for name in required:
        folded = name.casefold()
        edition_id = by_name.get(folded)
        if edition_id is None and folded.startswith("sf_edition_"):
            suffix = folded[len("sf_edition_"):]
            if _HEX.fullmatch(suffix):
                edition_id = suffix
        if edition_id is None:
            unmapped.append(name)
        else:
            selected.setdefault(edition_id, []).append(name)
    editions = []
    for edition_id, names in sorted(selected.items()):
        edition = _record(db, edition_id)
        context = edition_context(db, edition)
        descriptor = ({key: value for key, value in context.items()
                       if key not in {"document", "version_id", "edition_id"}}
                      if context is not None else None)
        editions.append({"edition_id": edition_id, "relations": names,
                         "manifest_sha256": edition["manifest_sha256"],
                         "semantics": descriptor})
    return {"schema": CONTEXT_SCHEMA, "scope": "REFERENCED_SOURCE_EDITIONS",
            "resolved": True, "relations": required,
            "unmapped_relations": unmapped, "editions": editions}


def export_dictionaries(db, context, directory):
    """Receive exact dictionaries for the retained original query execution."""
    _require(isinstance(context, dict) and context.get("schema") == CONTEXT_SCHEMA
             and isinstance(context.get("editions"), list),
             "DUCKDB_QUERY_SEMANTIC_CONTEXT_INVALID")
    files, editions = [], []
    for source in context["editions"]:
        edition = _record(db, source.get("edition_id"))
        checked = edition_context(db, edition)
        descriptor = ({key: value for key, value in checked.items()
                       if key not in {"document", "version_id", "edition_id"}}
                      if checked is not None else None)
        _require(edition["manifest_sha256"] == source.get("manifest_sha256")
                 and same_json(descriptor, source.get("semantics")),
                 "DUCKDB_QUERY_SEMANTIC_SOURCE_CHANGED")
        if checked is None:
            editions.append(source)
            continue
        member = "source-meanings/" + edition["edition_id"] + ".json"
        target = directory / member
        private_directory(target.parent)
        raw = _file_bytes(db, edition["edition_id"], "semantics.json", MAX_BYTES)
        if target.exists():
            _require(read(target, MAX_BYTES) == raw, "DUCKDB_QUERY_DICTIONARY_CHANGED")
        else:
            write(target, raw, exclusive=True)
        file = {"name": member, "path": str(target), "bytes": len(raw),
                "sha256": digest(raw), "mime": "application/json"}
        files.append(file)
        editions.append({**source, "dictionary_file": member})
    return {**context, "editions": editions}, files


def compare_contexts(before, after, before_columns, after_columns):
    def fields(context, columns):
        if context is None:
            return {}
        definitions = {column["name"]: column for column in context["document"]["columns"]}
        return {column["source"]: {
                    "source": column["source"], "column": column["name"],
                    "type": column["type"], "nullable": column["nullable"],
                    "definition": definitions[column["source"]],
                } for column in columns}

    first, second = fields(before, before_columns), fields(after, after_columns)
    changed = [{"source": name, "before": first[name], "after": second[name]}
               for name in sorted(first.keys() & second.keys())
               if not same_json(first[name], second[name])]
    def compact(context):
        return ({key: value for key, value in context.items() if key != "document"}
                if context is not None else None)
    def value(context, key):
        return context["document"].get(key) if context is not None else None
    return {
        "schema": "stellar-forge.duckdb-meaning-comparison.v1",
        "before": compact(before), "after": compact(after),
        "definition_changed": (before or {}).get("definition_sha256") != (after or {}).get("definition_sha256"),
        "capture_changed": (before or {}).get("capture_manifest_sha256") != (after or {}).get("capture_manifest_sha256"),
        "mapping_changed": not same_json(before_columns, after_columns),
        "columns": {"added": [second[name] for name in sorted(second.keys() - first.keys())],
                    "removed": [first[name] for name in sorted(first.keys() - second.keys())],
                    "changed": changed},
        "primary_key_changed": not same_json(value(before, "primaryKey"), value(after, "primaryKey")),
        "observation_uri_changed": not same_json(value(before, "aboutUrl"), value(after, "aboutUrl")),
        "virtual_columns_changed": not same_json(value(before, "virtualColumns"), value(after, "virtualColumns")),
    }

"""Reviewed GIS layers and portable native GIS exports in a customer warehouse."""
from __future__ import annotations

from collections import Counter
from contextlib import contextmanager
import json
import math
import os
from pathlib import Path
import re
import sqlite3
import struct
import tempfile

from .duckdb_dataset import (_descriptor, _hex, _json, _name, _new_destination,
    _now, _parquet_result, _qid, _wire)
from .errors import StateError
from .storage import digest, dump, lock, parse, private_directory, read, sync_directory

SCHEMA = "stellar-forge.sf100.duckdb-spatial.v1"
_FORMATS = {"esri-json", "geojson", "wkt", "wkb-hex"}
_ESRI = {"esriGeometryPoint", "esriGeometryMultipoint", "esriGeometryPolyline", "esriGeometryPolygon"}
_MAX_JSON = 64 * 1024 * 1024


def _literal(value):
    return "'" + str(value).replace("'", "''") + "'"


def _geometry(value):
    if value is None:
        return None
    result = parse(value.encode()) if isinstance(value, str) else value
    if not isinstance(result, dict):
        raise StateError("DUCKDB_SPATIAL_GEOMETRY_OBJECT_REQUIRED")
    return result


def _points(value):
    """Read original XY coordinates without changing order, rings or precision."""
    if isinstance(value, dict):
        if any(key in value for key in ("curveRings", "curvePaths", "z", "m")):
            raise StateError("DUCKDB_SPATIAL_LINEAR_XY_SOURCE_REQUIRED")
        if "x" in value or "y" in value:
            if value.get("x") is None and value.get("y") is None:
                return []
            value = [value["x"], value["y"]]
        else:
            value = next((value[key] for key in ("rings", "paths", "points", "coordinates") if key in value), [])
    if not isinstance(value, (tuple, list)):
        raise StateError("DUCKDB_SPATIAL_COORDINATES_INVALID")
    if not value:
        return []
    if isinstance(value[0], (int, float)):
        if len(value) != 2 or any(type(x) not in (int, float) or not math.isfinite(x) for x in value):
            raise StateError("DUCKDB_SPATIAL_LINEAR_XY_SOURCE_REQUIRED")
        return [tuple(float(x) for x in value)]
    return [point for child in value for point in _points(child)]


def _wkb_points(value):
    """Independent WKB coordinate inventory, including polygon holes."""
    if value is None:
        return []
    data, offset, points = memoryview(value), 0, []
    def take(fmt):
        nonlocal offset
        size = struct.calcsize(fmt)
        if offset + size > len(data):
            raise StateError("DUCKDB_SPATIAL_WKB_INVALID")
        result = struct.unpack_from(fmt, data, offset)
        offset += size
        return result
    def geometry():
        order = take("B")[0]
        if order not in (0,1):
            raise StateError("DUCKDB_SPATIAL_WKB_INVALID")
        endian = "<" if order == 1 else ">"
        kind = take(endian + "I")[0]
        if kind & 0xE0000000 or kind >= 1000:
            raise StateError("DUCKDB_SPATIAL_LINEAR_XY_SOURCE_REQUIRED")
        def point():
            x, y = take(endian + "dd")
            if math.isnan(x) and math.isnan(y):
                return
            if not math.isfinite(x) or not math.isfinite(y):
                raise StateError("DUCKDB_SPATIAL_COORDINATES_INVALID")
            points.append((x, y))
        if kind == 1:
            point()
        elif kind == 2:
            for _ in range(take(endian + "I")[0]): point()
        elif kind == 3:
            for _ in range(take(endian + "I")[0]):
                for _ in range(take(endian + "I")[0]): point()
        elif kind in (4,5,6,7):
            for _ in range(take(endian + "I")[0]): geometry()
        else:
            raise StateError("DUCKDB_SPATIAL_WKB_INVALID")
    geometry()
    if offset != len(data):
        raise StateError("DUCKDB_SPATIAL_WKB_TRAILING_BYTES")
    return points


def _sync(path):
    os.chmod(path, 0o600)
    with open(path, "rb") as stream:
        os.fsync(stream.fileno())


def _verify_file(path, expected):
    actual = _descriptor(path)
    if (actual["bytes"], actual["sha256"]) != (expected.get("bytes"), expected.get("sha256")):
        raise StateError("DUCKDB_SPATIAL_RETAINED_FILE_CHANGED")


def _source_crs(reference):
    if reference is None:
        return None
    value = _geometry(reference)
    if "latestWkid" in value or "wkid" in value:
        code = value.get("latestWkid", value.get("wkid"))
        if type(code) is not int or code < 1:
            raise StateError("DUCKDB_SPATIAL_SOURCE_CRS_INVALID")
        return "EPSG:" + str(code)
    return value.get("wkt2") or value.get("wkt")


class DuckDBSpatial:
    """A GIS catalogue over immutable original editions; WKB remains in this DB."""

    def __init__(self, workspace, *, extension_path=None):
        self.workspace = workspace
        self.directory = workspace.directory
        configured = extension_path or os.environ.get("STARFORGE_DUCKDB_SPATIAL_EXTENSION")
        self.extension = str(Path(configured).expanduser().resolve(strict=True)) if configured else "spatial"
        with workspace._guard(), workspace._connection(writeable=True) as db:
            db.execute("BEGIN")
            try:
                db.execute("CREATE TABLE IF NOT EXISTS sf_spatial_reviews(id VARCHAR PRIMARY KEY,record VARCHAR NOT NULL)")
                db.execute("CREATE TABLE IF NOT EXISTS sf_spatial_features(review_id VARCHAR,sf_row BIGINT,wkb BLOB,raw_sha256 VARCHAR,PRIMARY KEY(review_id,sf_row))")
                db.execute("CREATE TABLE IF NOT EXISTS sf_spatial_layers(id VARCHAR PRIMARY KEY,record VARCHAR NOT NULL)")
                db.execute("CREATE TABLE IF NOT EXISTS sf_spatial_views(name VARCHAR PRIMARY KEY,layer_id VARCHAR,revision BIGINT)")
                db.execute("CREATE TABLE IF NOT EXISTS sf_spatial_view_history(name VARCHAR,revision BIGINT,record VARCHAR,PRIMARY KEY(name,revision))")
                db.execute("CREATE TABLE IF NOT EXISTS sf_spatial_queries(id VARCHAR PRIMARY KEY,name VARCHAR UNIQUE,revision BIGINT,record VARCHAR)")
                db.execute("CREATE TABLE IF NOT EXISTS sf_spatial_query_history(id VARCHAR,revision BIGINT,record VARCHAR,PRIMARY KEY(id,revision))")
                db.commit()
            except BaseException:
                db.rollback()
                raise

    @contextmanager
    def _connection(self, *, writeable=False, allowed_paths=(), bind=False):
        with self.workspace._connection(writeable=writeable, allowed_paths=allowed_paths,
                                         spatial_extension=self.extension) as db:
            if bind:
                self._bind(db)
            yield db

    def _bindings(self, db):
        return {"views": self.workspace._views(db),
                "layers": [{"name": n, "layer_id": i, "revision": r} for n,i,r in
                           db.execute("SELECT name,layer_id,revision FROM sf_spatial_views ORDER BY name").fetchall()],
                "available_layers": [row[0] for row in db.execute("SELECT id FROM sf_spatial_layers ORDER BY id").fetchall()]}

    def _bind(self, db):
        for raw, in db.execute("SELECT record FROM sf_spatial_layers ORDER BY id").fetchall():
            layer = parse(raw.encode())
            edition = self.workspace._record(db, "sf_editions", layer["edition_id"])
            sql = ("SELECT e.*, ST_SetCRS(ST_GeomFromWKB(f.wkb)," + _literal(layer["crs"])
                   + ") AS " + _qid(layer["geometry_name"]) + " FROM " + _qid(edition["table"])
                   + " e JOIN sf_spatial_features f ON e.sf_row=f.sf_row AND f.review_id="
                   + _literal(layer["review_id"]))
            db.execute("CREATE TEMP VIEW " + _qid(layer["table"]) + " AS " + sql)
        for name,identity in db.execute("SELECT name,layer_id FROM sf_spatial_views").fetchall():
            layer = self.workspace._record(db, "sf_spatial_layers", identity)
            db.execute("CREATE TEMP VIEW " + _qid(name) + " AS SELECT * FROM " + _qid(layer["table"]))

    def status(self):
        with self.workspace._guard(), self.workspace._connection() as db:
            records = lambda table: [parse(row[0].encode()) for row in db.execute("SELECT record FROM " + table + " ORDER BY id").fetchall()]
            return {"schema": SCHEMA, "runtime": {"extension": self.extension, "required_duckdb": "1.5.6"},
                    "reviews": records("sf_spatial_reviews"), "layers": records("sf_spatial_layers"),
                    "queries": records("sf_spatial_queries"), "bindings": self._bindings(db)}

    def runtime(self):
        with self.workspace._guard(), self._connection() as db:
            result = db.execute("SELECT * FROM ST_Drivers()")
            drivers = [dict(zip([d[0] for d in result.description], row)) for row in result.fetchall()]
            missing = {name for name in ("ESRIJSON","GPKG") if not any(d.get("short_name") == name for d in drivers)}
            if missing:
                raise StateError("DUCKDB_SPATIAL_GDAL_DRIVERS_REQUIRED")
            return {"schema": SCHEMA + ".runtime", "duckdb": self.workspace.duckdb.__version__,
                    "extension": self.extension, "geometry_always_xy": True, "drivers": drivers,
                    "extension_file": _descriptor(Path(self.extension)) if self.extension != "spatial" else None}

    @staticmethod
    def _check_crs(db, value):
        if not isinstance(value, str) or not value.strip() or len(value.encode()) > 32768:
            raise StateError("DUCKDB_SPATIAL_EXPLICIT_CRS_REQUIRED")
        value = value.strip()
        db.execute("SELECT ST_CRS(ST_SetCRS(ST_Point(0,0)," + _literal(value) + "))").fetchone()
        return value

    def review_layer(self, edition_id, *, geometry_column, source_format, crs,
                     spatial_reference_column=None, geometry_type=None, keys=None,
                     geometry_name="geometry"):
        edition_id = _hex(edition_id)
        if source_format not in _FORMATS:
            raise StateError("DUCKDB_SPATIAL_SOURCE_FORMAT_INVALID")
        _qid(geometry_column)
        _name(geometry_name)
        crs = crs.strip() if isinstance(crs, str) else crs
        if source_format == "esri-json" and geometry_type not in _ESRI:
            raise StateError("DUCKDB_SPATIAL_ESRI_GEOMETRY_TYPE_REQUIRED")
        with self.workspace._guard():
            with self.workspace._connection() as db:
                edition = self.workspace._record(db, "sf_editions", edition_id)
                names = [column["name"] for column in edition["columns"]]
                if geometry_column not in names or geometry_name.casefold() in {n.casefold() for n in names + ["sf_row"]}:
                    raise StateError("DUCKDB_SPATIAL_GEOMETRY_COLUMN_INVALID")
                if spatial_reference_column is not None and spatial_reference_column not in names:
                    raise StateError("DUCKDB_SPATIAL_SOURCE_CRS_COLUMN_INVALID")
                keys = edition["keys"] if keys is None else keys
                if not isinstance(keys,list) or not keys or len(set(keys)) != len(keys) or any(k not in names for k in keys):
                    raise StateError("DUCKDB_SPATIAL_REVIEWED_KEYS_REQUIRED")
                reference = _qid(spatial_reference_column) if spatial_reference_column else "NULL"
                source = db.execute("SELECT sf_row," + _qid(geometry_column) + "," + reference
                                    + " FROM " + _qid(edition["table"]) + " ORDER BY sf_row").fetchall()
                qkeys = ",".join(map(_qid,keys))
                if db.execute("SELECT 1 FROM " + _qid(edition["table"]) + " WHERE "
                              + " OR ".join(_qid(k) + " IS NULL" for k in keys) + " LIMIT 1").fetchone():
                    raise StateError("DUCKDB_SPATIAL_NULL_KEY")
                if db.execute("SELECT 1 FROM " + _qid(edition["table"]) + " GROUP BY " + qkeys + " HAVING count(*)>1 LIMIT 1").fetchone():
                    raise StateError("DUCKDB_SPATIAL_NONUNIQUE_KEY")
            reference_values = sorted({_json(_geometry(row[2])) for row in source if row[2] is not None})
            if len(reference_values) > 1:
                raise StateError("DUCKDB_SPATIAL_MIXED_SOURCE_CRS")
            source_reference = parse(reference_values[0].encode()) if reference_values else None
            derived_crs = _source_crs(source_reference)
            if derived_crs is not None and derived_crs != crs:
                raise StateError("DUCKDB_SPATIAL_REVIEW_CRS_DIFFERS_FROM_SOURCE")
            with tempfile.TemporaryDirectory(prefix="spatial-review-", dir=self.directory) as temporary:
                file = Path(temporary) / "source.esrijson"
                if source_format == "esri-json":
                    features = []
                    for rowid,raw,_ in source:
                        geometry = _geometry(raw)
                        if geometry is not None: _points(geometry)
                        features.append({"attributes":{"sf_row":rowid},"geometry":geometry})
                    feature_set = {"geometryType":geometry_type,"hasZ":False,"hasM":False,
                                   "fields":[{"name":"sf_row","type":"esriFieldTypeInteger"}],"features":features}
                    if source_reference is not None:
                        feature_set["spatialReference"] = source_reference
                    elif re.fullmatch(r"EPSG:[1-9][0-9]*",crs):
                        feature_set["spatialReference"] = {"wkid":int(crs[5:])}
                    else:
                        feature_set["spatialReference"] = {"wkt":crs}
                    dump(file,feature_set,exclusive=True)
                with self._connection(writeable=True,allowed_paths=[file] if file.exists() else []) as db:
                    crs = self._check_crs(db,crs)
                    if not source:
                        converted = {}
                    elif source_format == "esri-json":
                        converted = dict(db.execute(
                            "SELECT sf_row,CAST(wkb_geometry AS BLOB) FROM ST_Read(?,keep_wkb:=true,allowed_drivers:=['ESRIJSON'])",
                            [str(file)]).fetchall())
                    else:
                        function = {"geojson":"ST_GeomFromGeoJSON(?)","wkt":"ST_GeomFromText(?)",
                                    "wkb-hex":"ST_GeomFromWKB(from_hex(?))"}[source_format]
                        converted = {rowid:db.execute("SELECT ST_AsWKB(" + function + ")",[raw]).fetchone()[0]
                                     for rowid,raw,_ in source}
                    if set(converted) != {r[0] for r in source}:
                        raise StateError("DUCKDB_SPATIAL_SOURCE_ROW_SET_CHANGED")
                    features,states,coordinate_count = [],{"null":0,"empty":0,"valid":0,"invalid":0},0
                    extent,geometry_types = None,set()
                    for rowid,raw,_ in source:
                        wkb = converted[rowid]
                        source_points = _points(_geometry(raw)) if source_format in {"esri-json","geojson"} and raw is not None else None
                        native_points = _wkb_points(wkb)
                        if source_points is not None and Counter(source_points) != Counter(native_points):
                            raise StateError("DUCKDB_SPATIAL_SOURCE_COORDINATES_CHANGED")
                        if (raw is None) != (wkb is None):
                            raise StateError("DUCKDB_SPATIAL_SOURCE_NULL_STATE_CHANGED")
                        coordinate_count += len(native_points)
                        raw_bytes = raw.encode() if isinstance(raw,str) else _json(raw).encode()
                        features.append((rowid,wkb,digest(raw_bytes)))
                        if wkb is None:
                            states["null"] += 1
                            continue
                        empty,valid,kind = db.execute(
                            "SELECT ST_IsEmpty(g),ST_IsValid(g),CAST(ST_GeometryType(g) AS VARCHAR) FROM (SELECT ST_GeomFromWKB(?) g)",
                            [wkb]).fetchone()
                        states["empty" if empty else "valid" if valid else "invalid"] += 1
                        geometry_types.add(kind)
                        for x,y in native_points:
                            extent = [x,y,x,y] if extent is None else [min(extent[0],x),min(extent[1],y),max(extent[2],x),max(extent[3],y)]
                    coordinate_sha = digest(_json([{"sf_row":rowid,"raw_sha256":sha,
                                                   "wkb_sha256":digest(wkb) if wkb is not None else None}
                                                  for rowid,wkb,sha in features]).encode())
                    identity = {"schema":SCHEMA+".layer-review","edition_id":edition_id,
                                "source_manifest_sha256":edition.get("manifest_sha256"),
                                "geometry_column":geometry_column,"source_format":source_format,
                                "geometry_type":geometry_type,"spatial_reference_column":spatial_reference_column,
                                "source_spatial_reference":source_reference,"crs":crs,
                                "geometry_name":geometry_name,"keys":keys,"coordinate_binding_sha256":coordinate_sha}
                    review_id = digest(_json(identity).encode())
                    existing = db.execute("SELECT record FROM sf_spatial_reviews WHERE id=?",[review_id]).fetchone()
                    if existing: return parse(existing[0].encode())
                    record = {**identity,"review_id":review_id,"created_at":_now(),"row_count":len(source),
                              "coordinate_count":coordinate_count,"states":states,"geometry_types":sorted(geometry_types),
                              "extent":extent,"dimension":"XY","transformation":None}
                    db.execute("BEGIN")
                    try:
                        db.execute("INSERT INTO sf_spatial_reviews VALUES(?,?)",[review_id,_json(record)])
                        if features:
                            db.executemany("INSERT INTO sf_spatial_features VALUES(?,?,?,?)",[(review_id,*row) for row in features])
                        db.commit()
                    except BaseException:
                        db.rollback()
                        raise
                    return record

    def adopt_layer(self,review_id):
        review_id = _hex(review_id)
        with self.workspace._guard(),self.workspace._connection(writeable=True) as db:
            review = self.workspace._record(db,"sf_spatial_reviews",review_id)
            identity = digest((SCHEMA+".layer:"+review_id).encode())
            existing = db.execute("SELECT record FROM sf_spatial_layers WHERE id=?",[identity]).fetchone()
            if existing: return parse(existing[0].encode())
            record = {**review,"schema":SCHEMA+".layer","layer_id":identity,"table":"sf_layer_"+identity,"adopted_at":_now()}
            db.execute("INSERT INTO sf_spatial_layers VALUES(?,?)",[identity,_json(record)])
            return record

    def activate(self,name,layer_id,*,expected_revision):
        name,layer_id = _name(name),_hex(layer_id)
        if type(expected_revision) is not int or expected_revision < 0:
            raise StateError("DUCKDB_SPATIAL_REVISION_REQUIRED")
        with self.workspace._guard(),self.workspace._connection(writeable=True) as db:
            self.workspace._record(db,"sf_spatial_layers",layer_id)
            if db.execute("SELECT 1 FROM duckdb_tables() WHERE lower(table_name)=lower(?) UNION ALL "
                          "SELECT 1 FROM duckdb_views() WHERE lower(view_name)=lower(?)",[name,name]).fetchone():
                raise StateError("DUCKDB_SPATIAL_VIEW_NAME_ALREADY_USED")
            db.execute("BEGIN")
            try:
                current = db.execute("SELECT name,layer_id,revision FROM sf_spatial_views WHERE lower(name)=lower(?)",[name]).fetchone()
                if (current[2] if current else 0) != expected_revision:
                    raise StateError("DUCKDB_SPATIAL_ACTIVE_LAYER_CHANGED")
                if current and current[1] == layer_id:
                    db.commit()
                    return {"name":current[0],"layer_id":layer_id,"revision":current[2]}
                name = current[0] if current else name
                result = {"name":name,"layer_id":layer_id,"revision":expected_revision+1,"activated_at":_now()}
                db.execute("INSERT INTO sf_spatial_views VALUES(?,?,?) ON CONFLICT(name) DO UPDATE SET layer_id=excluded.layer_id,revision=excluded.revision",
                           [name,layer_id,result["revision"]])
                db.execute("INSERT INTO sf_spatial_view_history VALUES(?,?,?)",[name,result["revision"],_json(result)])
                db.commit()
                return result
            except BaseException:
                db.rollback()
                raise

    def query(self,sql,parameters=None,*,max_rows=200,expected_bindings=None):
        parameters = [] if parameters is None else parameters
        sql = self.workspace._sql(sql,parameters)
        if type(max_rows) is not int or not 1 <= max_rows <= 10000:
            raise StateError("DUCKDB_SPATIAL_PREVIEW_LIMIT_INVALID")
        with self.workspace._guard(),self._connection(bind=True) as db:
            bindings = self._bindings(db)
            if expected_bindings is not None and bindings != expected_bindings:
                raise StateError("DUCKDB_SPATIAL_QUERY_BINDINGS_CHANGED")
            result = db.execute(sql,parameters)
            columns = [{"name":c[0],"type":str(c[1])} for c in result.description]
            rows = result.fetchmany(max_rows+1)
            return {"columns":columns,"rows":_wire(rows[:max_rows]),"truncated":len(rows)>max_rows,"bindings":bindings}

    def preview(self,layer_id,*,max_rows=100):
        layer_id = _hex(layer_id)
        if type(max_rows) is not int or not 1 <= max_rows <= 1000:
            raise StateError("DUCKDB_SPATIAL_PREVIEW_LIMIT_INVALID")
        with self.workspace._guard(),self._connection(bind=True) as db:
            layer = self.workspace._record(db,"sf_spatial_layers",layer_id)
            geometry = _qid(layer["geometry_name"])
            result = db.execute("SELECT "+",".join(map(_qid,layer["keys"]))+",ST_AsGeoJSON("+geometry+") FROM "
                                +_qid(layer["table"])+" ORDER BY sf_row LIMIT ?",[max_rows+1]).fetchall()
            return {"layer":layer,"crs":layer["crs"],"extent":layer["extent"],"truncated":len(result)>max_rows,
                    "features":[{"key":_wire(row[:-1]),"geometry":parse(row[-1].encode()) if row[-1] else None}
                                for row in result[:max_rows]]}

    def save_query(self,name,sql,parameters=None,*,expected_revision=0):
        name = _name(name)
        parameters = [] if parameters is None else parameters
        sql = self.workspace._sql(sql,parameters)
        _json(parameters)
        if type(expected_revision) is not int or expected_revision < 0:
            raise StateError("DUCKDB_SPATIAL_QUERY_REVISION_REQUIRED")
        identity = digest((SCHEMA+":"+name.casefold()).encode())
        with self.workspace._guard(),self.workspace._connection(writeable=True) as db:
            current = db.execute("SELECT revision,record FROM sf_spatial_queries WHERE id=?",[identity]).fetchone()
            if (current[0] if current else 0) != expected_revision:
                raise StateError("DUCKDB_SPATIAL_SAVED_QUERY_CHANGED")
            previous = parse(current[1].encode()) if current else None
            if previous and previous["sql"] == sql and previous["parameters"] == parameters:
                return previous
            record = {"query_id":identity,"name":previous["name"] if previous else name,"revision":expected_revision+1,
                      "sql":sql,"parameters":parameters,"saved_at":_now(),"kind":"gis-query"}
            db.execute("BEGIN")
            try:
                db.execute("INSERT INTO sf_spatial_queries VALUES(?,?,?,?) ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,record=excluded.record",
                           [identity,record["name"],record["revision"],_json(record)])
                db.execute("INSERT INTO sf_spatial_query_history VALUES(?,?,?)",[identity,record["revision"],_json(record)])
                db.commit()
                return record
            except BaseException:
                db.rollback()
                raise

    def _register_export(self,record):
        result = dict(record,files=list(record["files"]))
        result["files"].append(_descriptor(Path(record["directory"])/"manifest.json"))
        with self.workspace._guard(),self.workspace._connection(writeable=True) as db:
            db.execute("INSERT INTO sf_exports VALUES(?,?) ON CONFLICT(id) DO UPDATE SET record=excluded.record",
                       [result["export_id"],_json(result)])
        return result

    def export_query(self,query_id,destination,*,expected_revision,
                     geometry_column="geometry",target_crs=None,expected_bindings=None):
        query_id = _hex(query_id)
        _name(geometry_column)
        if type(expected_revision) is not int or expected_revision < 1:
            raise StateError("DUCKDB_SPATIAL_QUERY_REVISION_REQUIRED")
        target = _new_destination(destination,self.directory)
        with lock(target):
            request_file = target/"request.json"
            options = {"geometry_column":geometry_column,"target_crs":target_crs}
            if request_file.exists():
                request = parse(read(request_file,_MAX_JSON))
                if (request.get("schema") != SCHEMA+".query-export" or request.get("workspace") != str(self.directory)
                    or request.get("directory") != str(target) or request.get("options") != options
                    or request.get("query",{}).get("query_id") != query_id
                    or request.get("query",{}).get("revision") != expected_revision):
                    raise StateError("DUCKDB_SPATIAL_EXPORT_DESTINATION_CONFLICT")
                if expected_bindings is not None and expected_bindings != request["bindings"]:
                    raise StateError("DUCKDB_SPATIAL_EXPORT_BINDINGS_CONFLICT")
            else:
                if any(p.name != "operation.lock" for p in target.iterdir()):
                    raise StateError("DUCKDB_SPATIAL_EXPORT_DESTINATION_NOT_EMPTY")
                with self.workspace._guard(),self.workspace._connection() as db:
                    query = self.workspace._record(db,"sf_spatial_queries",query_id)
                    bindings = self._bindings(db)
                    layers = [parse(row[0].encode()) for row in db.execute("SELECT record FROM sf_spatial_layers ORDER BY id").fetchall()]
                if query["revision"] != expected_revision:
                    raise StateError("DUCKDB_SPATIAL_SAVED_QUERY_CHANGED")
                if expected_bindings is not None and bindings != expected_bindings:
                    raise StateError("DUCKDB_SPATIAL_QUERY_BINDINGS_CHANGED")
                identity = {"schema":SCHEMA+".query-export","kind":"gis-query","workspace":str(self.directory),
                            "directory":str(target),"query":query,"bindings":bindings,"layers":layers,"options":options}
                request = {**identity,"export_id":digest(_json(identity).encode()),"created_at":_now()}
                dump(request_file,request,exclusive=True)
            complete = target/"manifest.json"
            if complete.exists():
                record = parse(read(complete,_MAX_JSON))
                if record["export_id"] != request["export_id"]:
                    raise StateError("DUCKDB_SPATIAL_EXPORT_DESTINATION_CONFLICT")
                for file in record["files"]: _verify_file(target/file["name"],file)
                return self._register_export(record)
            parquet,partial = target/"result.parquet",target/"result.parquet.partial"
            execution_file = target/"execution.json"
            execution = parse(read(execution_file,_MAX_JSON)) if execution_file.exists() else None
            if execution and execution.get("export_id") != request["export_id"]:
                raise StateError("DUCKDB_SPATIAL_EXPORT_EXECUTION_CHANGED")
            def publish(part,final,descriptor):
                _verify_file(part,descriptor)
                os.rename(part,final)
                sync_directory(target)
            if not parquet.exists():
                if execution and execution.get("parquet"):
                    publish(partial,parquet,execution["parquet"])
                else:
                    if partial.exists():
                        partial.rename(target/("interrupted-"+_descriptor(partial)["sha256"]+".parquet"))
                    with self.workspace._guard(),self._connection(allowed_paths=[partial],bind=True) as db:
                        if self._bindings(db) != request["bindings"]:
                            raise StateError("DUCKDB_SPATIAL_QUERY_BINDINGS_CHANGED")
                        query = request["query"]
                        db.execute("CREATE TEMP TABLE sf_spatial_selected AS "+query["sql"],query["parameters"])
                        selected = [{"name":c[0],"type":str(c[1])} for c in db.execute("SELECT * FROM sf_spatial_selected LIMIT 0").description]
                        geometries = [c["name"] for c in selected if c["type"].startswith("GEOMETRY")]
                        if geometries != [geometry_column]:
                            raise StateError("DUCKDB_SPATIAL_ONE_SELECTED_GEOMETRY_REQUIRED")
                        g = _qid(geometry_column)
                        source_crs = db.execute("SELECT ST_CRS("+g+") FROM sf_spatial_selected LIMIT 1").fetchone()
                        if source_crs is None:
                            source_crs = db.execute("SELECT ST_CRS(CAST(NULL AS "+next(c["type"] for c in selected if c["name"]==geometry_column)+"))").fetchone()
                        source_crs = source_crs[0] if source_crs else None
                        if not source_crs:
                            raise StateError("DUCKDB_SPATIAL_QUERY_CRS_REQUIRED")
                        crs = self._check_crs(db,target_crs or source_crs)
                        projection = []
                        for column in selected:
                            name = _qid(column["name"])
                            projection.append(("ST_Transform("+name+","+_literal(crs)+") AS "+name)
                                              if column["name"]==geometry_column and crs!=source_crs else name)
                        db.execute("CREATE TEMP TABLE sf_export_result AS SELECT "+",".join(projection)+" FROM sf_spatial_selected")
                        rows = db.execute("SELECT count(*) FROM sf_export_result").fetchone()[0]
                        projection,columns,query_columns,encodings = _parquet_result(db)
                        db.execute("COPY (SELECT "+projection+" FROM sf_export_result) TO ? "
                                   "(FORMAT PARQUET,COMPRESSION ZSTD,GEOPARQUET_VERSION 'V1')",[str(partial)])
                        _sync(partial)
                        execution = {"export_id":request["export_id"],"rows":rows,"columns":columns,
                                     "query_columns":query_columns,"column_encodings":encodings,
                                     "geometry_column":geometry_column,"source_crs":source_crs,"crs":crs,
                                     "axis_order":"XY","transformation":{"source":source_crs,"target":crs} if crs!=source_crs else None,
                                     "parquet":_descriptor(partial,"result.parquet")}
                        execution["parquet"]["path"] = str(parquet)
                        dump(execution_file,execution)
                        publish(partial,parquet,execution["parquet"])
            if not execution:
                raise StateError("DUCKDB_SPATIAL_EXPORT_EXECUTION_MISSING")
            _verify_file(parquet,execution["parquet"])
            gpkg,part = target/"result.gpkg",target/"result.partial.gpkg"
            allowed = [parquet,part]+[Path(str(part)+suffix) for suffix in ("-journal","-wal","-shm")]
            with self.workspace._guard(),self._connection(allowed_paths=allowed) as db:
                if not gpkg.exists():
                    if execution.get("gpkg"):
                        publish(part,gpkg,execution["gpkg"])
                    else:
                        if part.exists():
                            part.rename(target/("interrupted-"+_descriptor(part)["sha256"]+".gpkg"))
                        projection,gpkg_columns = [],[]
                        for column in execution["columns"]:
                            name,kind = _qid(column["name"]),column["type"]
                            native = kind.startswith("GEOMETRY") or kind in {"BOOLEAN","TINYINT","SMALLINT","INTEGER","BIGINT","FLOAT","DOUBLE","VARCHAR","DATE","TIMESTAMP"}
                            projection.append(name if native else "CAST("+name+" AS VARCHAR) AS "+name)
                            gpkg_columns.append({"name":column["name"],"type":kind if native else "VARCHAR",
                                                 "encoding":"native" if native else "exact_text"})
                        fid = "sf_gis_fid"
                        while fid.casefold() in {c["name"].casefold() for c in gpkg_columns}: fid += "_"
                        sql = ("COPY (SELECT "+",".join(projection)+" FROM read_parquet($source)) TO $target "
                               "(FORMAT GDAL,DRIVER 'GPKG',LAYER_NAME 'features',SRS "+_literal(execution["crs"])
                               +",LAYER_CREATION_OPTIONS ['FID="+fid+"','GEOMETRY_NAME="+geometry_column+"','SPATIAL_INDEX=YES'])")
                        db.execute(sql,{"source":str(parquet),"target":str(part)})
                        _sync(part)
                        execution["gpkg_columns"],execution["gpkg_fid"] = gpkg_columns,fid
                        execution["gpkg"] = _descriptor(part,"result.gpkg")
                        execution["gpkg"]["path"] = str(gpkg)
                        dump(execution_file,execution)
                        publish(part,gpkg,execution["gpkg"])
            _verify_file(gpkg,execution["gpkg"])
            receiving = self.receive_files(target,execution=execution)
            receiving_file = target/"receiving.json"
            if receiving_file.exists():
                prior = parse(read(receiving_file,_MAX_JSON))
                if prior["result_binding"] != receiving["result_binding"]:
                    raise StateError("DUCKDB_SPATIAL_RECEIVING_CHANGED")
            else:
                dump(receiving_file,receiving,exclusive=True)
            source_editions = sorted({layer["edition_id"] for layer in request["layers"]})
            sources = []
            for edition_id in source_editions:
                record = self.workspace.export_source(edition_id,target/"source"/edition_id)
                for file in record["files"]:
                    path = Path(file["path"])
                    sources.append(_descriptor(path,path.relative_to(target).as_posix()))
            guide = target/"RECEIVING.md"
            if not guide.exists():
                guide.write_text(self._receiving_guide(execution),encoding="utf-8")
                _sync(guide)
            files = [_descriptor(path) for path in (parquet,gpkg,request_file,execution_file,receiving_file,guide)]+sources
            record = {**request,**{key:execution[key] for key in ("rows","columns","query_columns","column_encodings","geometry_column","source_crs","crs","axis_order","transformation","gpkg_columns","gpkg_fid")},
                      "state":"COMPLETE","completed_at":_now(),"files":files,
                      "source_editions":source_editions,"receiving":receiving}
            dump(complete,record,exclusive=True)
            return self._register_export(record)

    @staticmethod
    def _receiving_guide(execution):
        return ("# GIS receiving\n\nOpen result.gpkg, layer features, in QGIS or another GeoPackage reader. "
                "Open result.parquet in a GeoParquet reader. Both files retain the same complete query result.\n\n"
                "CRS: "+execution["crs"]+". Coordinate axis convention: X then Y. Geometry column: "
                +execution["geometry_column"]+".\n\n"
                "Exact source editions and original delivery files are under source/. Their original geometry JSON, "
                "spatial reference and raw attributes remain unchanged. request.json binds the original saved SQL "
                "revision and layer choices. execution.json records each native and portable field type. "
                "GeoPackage stores decimal, wide integer and nested values as exact text where native field types "
                "would lose information. Use query_columns when restoring the original SQL types.\n\n"
                "receiving.json was produced by a fresh native DuckDB/GDAL connection using only the exported files. "
                "It compares every attribute, null and geometry in both directions and checks embedded CRS metadata. "
                "A receiving worker can repeat: stellar-forge-duckdb --workspace NEW spatial receive DIRECTORY.\n")

    def receive_files(self,directory,*,execution=None):
        """Fresh independent GDAL/Parquet receiver: original tables are unavailable."""
        directory = private_directory(Path(directory),create=False)
        execution = execution or parse(read(directory/"execution.json",_MAX_JSON))
        parquet,gpkg = directory/"result.parquet",directory/"result.gpkg"
        for path,key in ((parquet,"parquet"),(gpkg,"gpkg")): _verify_file(path,execution[key])
        db = self.workspace.duckdb.connect(":memory:",config={"enable_external_access":"true",
            "autoinstall_known_extensions":"false","autoload_known_extensions":"false","allow_unsigned_extensions":"false",
            "threads":"1","memory_limit":self.workspace.memory_limit})
        try:
            db.execute("LOAD "+_literal(self.extension))
            db.execute("SET geometry_always_xy=true")
            db.execute("SET allowed_paths=["+",".join(_literal(p) for p in (parquet,gpkg))+"]")
            db.execute("SET enable_external_access=false")
            db.execute("SET lock_configuration=true")
            db.execute("CREATE TEMP VIEW source_parquet AS SELECT * FROM read_parquet("+_literal(parquet)+")")
            db.execute("CREATE TEMP VIEW source_gpkg AS SELECT * FROM ST_Read("+_literal(gpkg)+",keep_wkb:=true,allowed_drivers:=['GPKG'])")
            descriptions = {}
            for table in ("source_parquet","source_gpkg"):
                result = db.execute("SELECT * FROM "+table+" LIMIT 0")
                descriptions[table] = [{"name":c[0],"type":str(c[1])} for c in result.description]
            geometry = execution["geometry_column"]
            gpkg_names = {c["name"] for c in descriptions["source_gpkg"]}
            if "wkb_geometry" not in gpkg_names:
                raise StateError("DUCKDB_SPATIAL_RECEIVER_GPKG_GEOMETRY_MISSING")
            pselect,gselect = [],[]
            original = {c["name"]:c for c in execution["query_columns"]}
            for column in execution["columns"]:
                name = column["name"]
                if name == geometry:
                    pselect.append("ST_AsWKB("+_qid(name)+") AS "+_qid(name))
                    gselect.append("CAST(wkb_geometry AS BLOB) AS "+_qid(name))
                else:
                    if name not in gpkg_names:
                        raise StateError("DUCKDB_SPATIAL_RECEIVER_ATTRIBUTE_MISSING")
                    kind = original[name]["type"]
                    pselect.append("CAST("+_qid(name)+" AS "+kind+") AS "+_qid(name))
                    gselect.append("CAST("+_qid(name)+" AS "+kind+") AS "+_qid(name))
            psql,gsql = "SELECT "+",".join(pselect)+" FROM source_parquet","SELECT "+",".join(gselect)+" FROM source_gpkg"
            forward = db.execute("SELECT count(*) FROM (("+psql+") EXCEPT ALL ("+gsql+"))").fetchone()[0]
            reverse = db.execute("SELECT count(*) FROM (("+gsql+") EXCEPT ALL ("+psql+"))").fetchone()[0]
            counts = [db.execute("SELECT count(*) FROM "+table).fetchone()[0] for table in ("source_parquet","source_gpkg")]
            if forward or reverse or counts != [execution["rows"],execution["rows"]]:
                raise StateError("DUCKDB_SPATIAL_RECEIVER_ROWS_OR_GEOMETRY_CHANGED")
            metadata = db.execute("SELECT decode(value) FROM parquet_kv_metadata(?) WHERE decode(key)='geo'",[str(parquet)]).fetchone()
            geo = parse(metadata[0].encode()) if metadata else None
            if (not isinstance(geo,dict) or geo.get("primary_column") != geometry
                or geo.get("columns",{}).get(geometry,{}).get("encoding") != "WKB"):
                raise StateError("DUCKDB_SPATIAL_GEOPARQUET_METADATA_REQUIRED")
            gpkg_meta = db.execute("SELECT layers FROM ST_Read_Meta(?)",[str(gpkg)]).fetchone()
            with sqlite3.connect("file:"+str(gpkg)+"?mode=ro",uri=True) as connection:
                gpkg_crs = connection.execute("SELECT g.column_name,g.srs_id,s.organization,s.organization_coordsys_id,s.definition "
                                             "FROM gpkg_geometry_columns g JOIN gpkg_spatial_ref_sys s ON g.srs_id=s.srs_id "
                                             "WHERE g.table_name='features'").fetchall()
            if len(gpkg_crs)!=1 or gpkg_crs[0][0]!=geometry:
                raise StateError("DUCKDB_SPATIAL_GPKG_CRS_METADATA_REQUIRED")
            expected = execution["crs"].split(":")
            if len(expected)==2 and expected[0]=="EPSG":
                if (gpkg_crs[0][2],str(gpkg_crs[0][3])) != tuple(expected):
                    raise StateError("DUCKDB_SPATIAL_GPKG_CRS_CHANGED")
                identifier = (geo["columns"][geometry].get("crs") or {}).get("id",{})
                if (identifier.get("authority"),str(identifier.get("code"))) != tuple(expected):
                    raise StateError("DUCKDB_SPATIAL_GEOPARQUET_CRS_CHANGED")
            result_binding = digest(_json({"parquet":execution["parquet"]["sha256"],"gpkg":execution["gpkg"]["sha256"],
                                          "rows":counts[0],"geometry_column":geometry,"crs":execution["crs"]}).encode())
            return {"schema":SCHEMA+".receiving","state":"COMPLETE","result_binding":result_binding,
                    "received_at":_now(),"duckdb":self.workspace.duckdb.__version__,"rows":counts[0],
                    "parquet_minus_gpkg":forward,"gpkg_minus_parquet":reverse,
                    "geometry_comparison":"all original WKB values, multiplicity and null states",
                    "crs":execution["crs"],"geoparquet":geo,"gpkg_crs":_wire(gpkg_crs),
                    "gpkg_layers":_wire(gpkg_meta[0]) if gpkg_meta else None,"file_columns":descriptions}
        finally:
            db.close()

"""Stable application errors; native stderr and signer output are never echoed."""


class BuyerError(RuntimeError):
    def __init__(self, code: str, *, operation=None):
        self.code = code
        self.operation = operation
        super().__init__(code)


class NativeError(BuyerError):
    def __init__(self, code: str, *, returncode=None, operation=None):
        self.returncode = returncode
        super().__init__(code, operation=operation)


class StateError(BuyerError):
    pass


class DeliveryError(BuyerError):
    def __init__(self, code: str, *, operation=None, record=None):
        self.record = record
        native = (record or {}).get("native") or {}
        self.partial_path = native.get("partialPath")
        self.transfer_state_path = native.get("transferState")
        self.retained_bytes = native.get("retainedBytes", 0)
        self.resumable = native.get("resumable", False)
        super().__init__(code, operation=operation)

