_HEX = re.compile(r"[a-f0-9]{64}")
_INTEGER = re.compile(r"-?(?:0|[1-9][0-9]*)")
_DECIMAL = re.compile(r"-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?")
_TIMESTAMP = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(?:\.[0-9]{1,6})?(?:Z|[+-][0-9]{2}:[0-9]{2})")
_TYPES = {"text", "boolean", "bigint", "numeric", "double precision", "date", "timestamp with time zone", "json"}


class WarehouseError(StateError):
    """A receiving error with safe structured location/provider information."""

    def __init__(self, code, *, row=None, field=None, sqlstate=None):
        super().__init__(code)
        self.code, self.row, self.field, self.sqlstate = code, row, field, sqlstate

    def report(self):
        return {key: value for key, value in {
            "error": self.code, "row": self.row, "field": self.field,
            "sqlstate": self.sqlstate,
        }.items() if value is not None}


def _json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, sort_keys=True, separators=(",", ":"))


def _identifier(value):
    if (not isinstance(value, str) or not value or len(value.encode("utf-8")) > 63
            or any(ord(char) < 32 for char in value) or "\x7f" in value):
        raise WarehouseError("DATASET_PG_IDENTIFIER_INVALID")
    return '"' + value.replace('"', '""') + '"'


def _public_name(value):
    quoted = _identifier(value)
    if value.lower().startswith(("_sf_", "pg_")) or value == "information_schema":
        raise WarehouseError("DATASET_PG_RESERVED_IDENTIFIER")
    return quoted


def _version_id(value):
    if not isinstance(value, str) or not _HEX.fullmatch(value):
        raise WarehouseError("DATASET_PG_VERSION_ID_INVALID")
    return value


def _page(before, limit):
    if ((before is not None and (type(before) is not int or before < 1))
            or type(limit) is not int or not 1 <= limit <= 1000):
        raise WarehouseError("DATASET_PG_PAGE_INVALID")


def _driver():
    try:
        import psycopg
        from psycopg.pq import TransactionStatus
        from psycopg.rows import tuple_row
    except ImportError:
        raise WarehouseError("DATASET_PG_PSYCOPG3_REQUIRED") from None
    return psycopg, TransactionStatus, tuple_row


@dataclass(frozen=True)
class Column:
    source: str
    column: str
    type: str
    nullable: bool = True

    def __post_init__(self):
        if not isinstance(self.source, str) or not self.source:
            raise WarehouseError("DATASET_PG_SOURCE_FIELD_INVALID")
        _public_name(self.column)
        if self.type not in _TYPES or type(self.nullable) is not bool:
            raise WarehouseError("DATASET_PG_COLUMN_DECLARATION_INVALID", field=self.source)

    def record(self):
        return {"source": self.source, "column": self.column,
                "type": self.type, "nullable": self.nullable}


@dataclass(frozen=True)
class DatasetMapping:
    """An explicit mapping of every delivered field; keys use source names."""
    columns: tuple[Column, ...]
    keys: tuple[str, ...] = ()

    def __post_init__(self):
        object.__setattr__(self, "columns", tuple(self.columns))
        object.__setattr__(self, "keys", tuple(self.keys))
        if not self.columns or len(self.columns) > 1024 or not all(isinstance(c, Column) for c in self.columns):
            raise WarehouseError("DATASET_PG_COLUMNS_REQUIRED")
        sources, names = [c.source for c in self.columns], [c.column for c in self.columns]
        if len(set(sources)) != len(sources) or len(set(names)) != len(names):
            raise WarehouseError("DATASET_PG_COLUMN_MAPPING_COLLISION")
        if (not all(isinstance(key, str) for key in self.keys)
                or len(self.keys) > 32 or len(set(self.keys)) != len(self.keys) or set(self.keys) - set(sources)):
            raise WarehouseError("DATASET_PG_KEY_FIELDS_INVALID")
        for column in self.columns:
            if column.source in self.keys and (column.nullable or column.type == "json"):
                raise WarehouseError("DATASET_PG_KEYS_REQUIRE_NONNULL_COMPARABLE_COLUMNS", field=column.source)

    @classmethod
    def from_record(cls, record):
        if (not isinstance(record, dict) or record.get("schema") != MAPPING_SCHEMA
                or set(record) - {"schema", "columns", "keys"}
                or not isinstance(record.get("columns"), list)
                or not isinstance(record.get("keys", []), list)):
            raise WarehouseError("DATASET_PG_MAPPING_INVALID")
        try:
            return cls(tuple(Column(**column) for column in record["columns"]), tuple(record.get("keys", [])))
        except (TypeError, ValueError):
            raise WarehouseError("DATASET_PG_MAPPING_INVALID") from None

    def record(self):
        return {"schema": MAPPING_SCHEMA, "columns": [c.record() for c in self.columns], "keys": list(self.keys)}

    @property
    def signature(self):
        return [(c.column, c.type) for c in self.columns]


def _kind(value):
    if value is None:
        return "null"
    if type(value) is bool:
        return "boolean"
    if type(value) is int:
        return "integer"
    if isinstance(value, Decimal):
        return "number"
    if isinstance(value, str):
        return "string"
    raise WarehouseError("DATASET_PG_NATIVE_SCALAR_REQUIRED")


def _value(column, value):
    if value is None:
        if not column.nullable:
            raise WarehouseError("DATASET_PG_NULL_NOT_ALLOWED", field=column.source)
        return None
    kind = _kind(value)
    if column.type == "text":
        if kind != "string" or "\x00" in value:
            raise WarehouseError("DATASET_PG_TEXT_REQUIRED", field=column.source)
        return value
    if column.type == "boolean":
        if kind != "boolean":
            raise WarehouseError("DATASET_PG_BOOLEAN_REQUIRED", field=column.source)
        return value
    if column.type == "bigint":
        if kind == "integer":
            number = value
        elif kind == "string" and _INTEGER.fullmatch(value):
            number = int(value)
        else:
            raise WarehouseError("DATASET_PG_EXACT_INTEGER_REQUIRED", field=column.source)
        if not -(2**63) <= number < 2**63:
            raise WarehouseError("DATASET_PG_BIGINT_RANGE", field=column.source)
        return number
    if column.type == "numeric":
        if kind not in {"integer", "number", "string"} or not _DECIMAL.fullmatch(str(value)):
            raise WarehouseError("DATASET_PG_EXACT_DECIMAL_REQUIRED", field=column.source)
        try:
            number = Decimal(value)
        except (InvalidOperation, ValueError):
            raise WarehouseError("DATASET_PG_EXACT_DECIMAL_REQUIRED", field=column.source) from None
        if not number.is_finite() or number.adjusted() > 131071 or number.as_tuple().exponent < -16383:
            raise WarehouseError("DATASET_PG_NUMERIC_RANGE", field=column.source)
        return number
    if column.type == "double precision":
        if kind not in {"integer", "number"} or kind == "integer" and abs(value) > 2**53:
            raise WarehouseError("DATASET_PG_FINITE_NUMBER_REQUIRED_USE_NUMERIC_FOR_EXACT_VALUES", field=column.source)
        number = float(value)
        if not math.isfinite(number) or number == 0 and value != 0:
            raise WarehouseError("DATASET_PG_DOUBLE_RANGE", field=column.source)
        return number
    if column.type == "date":
        if kind != "string" or not re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", value):
            raise WarehouseError("DATASET_PG_ISO_DATE_REQUIRED", field=column.source)
        try:
            return date.fromisoformat(value)
        except ValueError:
            raise WarehouseError("DATASET_PG_ISO_DATE_REQUIRED", field=column.source) from None
    if column.type == "timestamp with time zone":
        if kind != "string" or not _TIMESTAMP.fullmatch(value):
            raise WarehouseError("DATASET_PG_ISO_TIMESTAMP_WITH_OFFSET_REQUIRED", field=column.source)
        try:
            return datetime.fromisoformat(value.replace("Z", "+00:00")).astimezone(timezone.utc)
        except (ValueError, OverflowError):
            raise WarehouseError("DATASET_PG_ISO_TIMESTAMP_WITH_OFFSET_REQUIRED", field=column.source) from None
    # Explicit PostgreSQL JSON column retains the native scalar's JSON type.
    if kind == "number":
        return str(value)
    return _json(value)


@dataclass(frozen=True)
class _Input:
    delivery: DatasetDelivery
    manifest_bytes: bytes
    manifest: dict
    mapping: DatasetMapping
    identity: dict
    version_id: str
    row_source: dict
    semantic_source: dict | None
    semantic_descriptor: dict | None

    @property
    def row_count(self):
        return self.manifest["dataset"]["rows"]

    def record(self):
        return {**self.identity, "version_id": self.version_id,
                "dataset": self.manifest["dataset"], "row_count": self.row_count,
                "source_pages": len(self.manifest["sourcePages"]),
                "originalPaymentStatus": self.manifest["paymentStatus"],
                "jsonl": {k: self.row_source[k] for k in ("bytes", "sha256")},
                "row_order_column": _ORDINAL, "original_row_column": _ORIGINAL,
                "semantics": self.semantic_descriptor,
                "semantics_status": "AVAILABLE" if self.semantic_source is not None else "NONE"}


def _input(delivery, mapping):
    from .postgres_central import CentralAcceptedDelivery
    if isinstance(delivery, CentralAcceptedDelivery):
        return delivery.receiving_input(mapping)
    if not isinstance(delivery, DatasetDelivery) or not isinstance(mapping, DatasetMapping):
        raise WarehouseError("DATASET_PG_ORIGINAL_DELIVERY_AND_MAPPING_REQUIRED")
    native = delivery.native
    if not isinstance(native, dict) or not isinstance(native.get("nativeStatus"), dict) or not isinstance(native.get("outputs"), dict):
        raise WarehouseError("DATASET_PG_ORIGINAL_DELIVERY_REPORT_REQUIRED")
    status, binding = native["nativeStatus"], native.get("sourceBindingSha256")
    if (native.get("schema") not in {"stellar-forge.sf88.dataset-delivery.v1", "stellar-forge.sf100.dataset-delivery.v1"}
            or native.get("schema") == "stellar-forge.sf100.dataset-delivery.v1" and native.get("sourceFormat") != "SF100_SCAN"
            or not isinstance(binding, str) or not _HEX.fullmatch(binding)
            or status.get("complete") is not True or status.get("finalized") is not True):
        raise WarehouseError("DATASET_PG_COMPLETE_NATIVE_DELIVERY_REQUIRED")
    manifest_bytes = delivery.file("manifest.json").read_bytes(limit=4 * 1024 * 1024)
    manifest_sha = digest(manifest_bytes)
    manifest = parse(manifest_bytes)
    if not isinstance(manifest, dict) or not isinstance(manifest.get("dataset"), dict):
        raise WarehouseError("DATASET_PG_MANIFEST_BINDING_INVALID")
    dataset = manifest["dataset"]
    fields, rows, pages = dataset.get("projectedFields"), dataset.get("rows"), manifest.get("sourcePages")
    if (manifest.get("schema") != "stellar-forge.buyer-delivery-manifest.v1"
            or not isinstance(fields, list) or not fields or len(fields) > 1024
            or not all(isinstance(field, str) for field in fields) or len(set(fields)) != len(fields)
            or type(rows) is not int or not 0 <= rows <= 1_000_000
            or status.get("rows") != rows or status.get("snapshot") != dataset.get("snapshot")
            or not isinstance(pages, list) or status.get("pages") != len(pages)
            or manifest.get("paymentStatus") != native.get("paymentStatus")
            or manifest_sha != native["outputs"]["manifest.json"]["sha256"]):
        raise WarehouseError("DATASET_PG_MANIFEST_BINDING_INVALID")
    if set(fields) != {c.source for c in mapping.columns}:
        raise WarehouseError("DATASET_PG_MAP_EVERY_DELIVERED_FIELD")
    source = native["outputs"]["dataset.jsonl"]
    if manifest.get("outputs", {}).get("dataset.jsonl") != {k: source[k] for k in ("bytes", "sha256")}:
        raise WarehouseError("DATASET_PG_ROW_BINDING_INVALID")
    identity = {"schema": SCHEMA, "manifestSha256": manifest_sha,
                "sourceBindingSha256": binding, "mapping": mapping.record()}
    meanings = read_delivery_semantics(delivery, manifest=manifest)
    descriptor = _semantic_descriptor(meanings, mapping) if meanings is not None else None
    if meanings is not None:
        sql_context(meanings["bytes"], descriptor, digest(_json(identity).encode()),
                    case_sensitive_targets=True)
    return _Input(delivery, manifest_bytes, manifest, mapping, identity,
                  digest(_json(identity).encode()), source, meanings, descriptor)


def _semantic_descriptor(receiving, mapping, *, enforced=False):
    descriptor = sql_descriptor(receiving, [c.source for c in mapping.columns],
                                [c.column for c in mapping.columns])
    primary = descriptor["primary_key"]
    # An independently selected receiving key is not evidence that the
    # dictionary's source primary key was enforced by PostgreSQL.
    primary["enforced"] = bool(enforced and primary["complete"] and primary["source"]
                               and set(primary["source"]) == set(mapping.keys))
    return descriptor


def _bound_semantics(raw, descriptor, manifest, mapping, version_id):
    context = sql_context(raw, descriptor, version_id, case_sensitive_targets=True)
    document = context["document"]
    binding = semantic_identity(document)
    declared = manifest.get("semantics")
    selected = manifest.get("dataset", {}).get("projectedFields")
    exact = {"bytes": len(raw), "sha256": digest(raw)}
    if (not isinstance(declared, dict) or declared.get("file") != "semantics.json"
            or declared.get("typedRowsFile") != "dataset.jsonl"
            or declared.get("scope") != "PUBLISHED_DATASET"
            or not same_json(declared.get("selectedFields"), selected)
            or not isinstance(selected, list)
            or set(selected) != {c.source for c in mapping.columns}
            or not all(declared.get(key) == value for key, value in binding.items())
            or not same_json(manifest.get("outputs", {}).get("semantics.json"), exact)):
        raise WarehouseError("DATASET_PG_SEMANTIC_MANIFEST_CHANGED")
    expected = _semantic_descriptor({"identity": binding, "document": document,
        "file": {"name": "semantics.json", **exact}}, mapping, enforced=True)
    if not same_json(descriptor, expected):
        raise WarehouseError("DATASET_PG_SEMANTIC_MAPPING_CHANGED")
    return context


def _rows(source, stream):
    checksum, count, size = hashlib.sha256(), 0, 0
    fields = {column.source for column in source.mapping.columns}
    while raw := stream.readline(2_097_153):
        count += 1
        size += len(raw)
        if len(raw) > 2_097_152 or not raw.endswith(b"\n") or count > source.row_count or size > source.row_source["bytes"]:
            raise WarehouseError("DATASET_PG_ROW_FORMAT_OR_COUNT_INVALID", row=count)
        checksum.update(raw)
        # Preserve the delivered JSON number lexeme through Decimal. The original
        # reader verifies the file before this same descriptor is consumed.
        try:
            row = json.loads(raw.decode("utf-8"), object_pairs_hook=unique_object,
                             parse_float=Decimal,
                             parse_constant=lambda _: (_ for _ in ()).throw(ValueError()))
        except (ValueError, UnicodeError, StateError):
            raise WarehouseError("DATASET_PG_INVALID_JSON_ROW", row=count) from None
        if not isinstance(row, dict) or set(row) != fields:
            raise WarehouseError("DATASET_PG_ROW_FIELDS_MISMATCH", row=count)
        try:
            values = tuple(_value(column, row[column.source]) for column in source.mapping.columns)
            kinds = tuple(_kind(row[column.source]) for column in source.mapping.columns)
        except WarehouseError as error:
            raise WarehouseError(error.code, row=count, field=error.field) from None
        yield count, raw[:-1].decode("utf-8"), values, kinds
    if count != source.row_count or size != source.row_source["bytes"] or checksum.hexdigest() != source.row_source["sha256"]:
        raise WarehouseError("DATASET_PG_ROWS_CHANGED")


def review_delivery(delivery: DatasetDelivery, mapping: DatasetMapping):
    """Review complete original rows offline; PostgreSQL later enforces keys."""
    source = _input(delivery, mapping)
    observed = [set() for _ in mapping.columns]
    nulls = [0 for _ in mapping.columns]
    with delivery.file("dataset.jsonl").open() as stream:
        for _, _, _, kinds in _rows(source, stream):
            for index, kind in enumerate(kinds):
                observed[index].add(kind)
                nulls[index] += kind == "null"
    return {**source.record(), "schema": REVIEW_SCHEMA, "status": "READY",
            "columns": [{**column.record(), "json_types": sorted(observed[index]), "nulls": nulls[index]}
                        for index, column in enumerate(mapping.columns)],
            "key_validation": "POSTGRESQL_TRANSACTION" if mapping.keys else "ROW_ORDINAL_ONLY",
            "semantic_dictionary": source.semantic_source["document"] if source.semantic_source else None}



def load_delivery_report(report_path):
    """Open an unchanged SF88 report or the original finalized SF100 scan."""
    path = Path(os.path.abspath(Path(report_path).expanduser()))
    record = parse(read(path, 8 * 1024 * 1024))
    if isinstance(record, dict) and record.get("schema") == "stellar-forge.postgres-central-delivery.v1":
        from .postgres_central import CentralAcceptedDelivery
        return CentralAcceptedDelivery(path)
    if isinstance(record, dict) and isinstance(record.get("report"), dict):
        record = record["report"]
    if (isinstance(record, dict) and isinstance(record.get("session"), dict)
            and record["session"].get("schema") == "stellar-forge.buyer-delivery.v1"):
        return DatasetDelivery.from_finalized_scan(record)
    if isinstance(record, dict) and record.get("schema") == "stellar-forge.sf100.dataset-delivery.v1":
        delivery = DatasetDelivery.from_finalized_scan(record.get("originalNativeScan"))
        if delivery.native != record:
            raise WarehouseError("DATASET_PG_REVIEWED_INPUT_CHANGED")
        return delivery
    if (not isinstance(record, dict) or record.get("schema") != "stellar-forge.sf88.dataset-delivery.v1"
            or not isinstance(record.get("directory"), str)):
        raise WarehouseError("DATASET_PG_ORIGINAL_DELIVERY_REPORT_REQUIRED")
    directory = Path(record["directory"])
    if (not directory.is_absolute() or str(directory) != record["directory"]
            or private_directory(directory, create=False) != directory):
        raise WarehouseError("DATASET_PG_ORIGINAL_DELIVERY_DIRECTORY_INVALID")
    return DatasetDelivery(native=record, directory=directory)


class PostgresWarehouse:
    """One dedicated PostgreSQL schema, with fresh caller-owned connections.

    The connection factory returns a new idle Psycopg 3 connection for each
    operation. This class closes those connections and owns each complete
    transaction. Customer application relations outside this schema are never
    changed. Importing an edition leaves named application views unchanged.
    """

    def __init__(self, connection_factory, *, schema="sf_received", create=True,
                 expected_warehouse=None, statement_timeout_ms=300000, lock_timeout_ms=30000):
        if not callable(connection_factory):
            raise WarehouseError("DATASET_PG_CONNECTION_FACTORY_REQUIRED")
        _public_name(schema)
        if (type(create) is not bool or type(statement_timeout_ms) is not int
                or not 1 <= statement_timeout_ms <= 3600000 or type(lock_timeout_ms) is not int
                or not 1 <= lock_timeout_ms <= statement_timeout_ms):
            raise WarehouseError("DATASET_PG_OPTIONS_INVALID")
        self.connection_factory, self.schema = connection_factory, schema
        self.statement_timeout_ms, self.lock_timeout_ms = statement_timeout_ms, lock_timeout_ms
        self.warehouse_id = expected_warehouse
        self._initialize(create=create)

    @classmethod
    def from_environment(cls, connection_env="SF_BUYER_POSTGRES_DSN", *, environment=None, **options):
        if not isinstance(connection_env, str) or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", connection_env):
            raise WarehouseError("DATASET_PG_CONNECTION_ENV_INVALID")
        environment = os.environ if environment is None else environment

        def connect():
            psycopg, _, _ = _driver()
            value = environment.get(connection_env)
            if not isinstance(value, str) or not value:
                raise WarehouseError("DATASET_PG_CONNECTION_ENV_MISSING")
            return psycopg.connect(value, autocommit=True, connect_timeout=10)

        return cls(connect, **options)

    def _table(self, name):
        return f"{_identifier(self.schema)}.{_identifier(name)}"

    @contextmanager
    def _transaction(self, *, readonly=False, check=True):
        psycopg, status, tuple_row = _driver()
        connection = None
        owned = False
        try:
            connection = self.connection_factory()
            if not isinstance(connection, psycopg.Connection) or connection.info.transaction_status != status.IDLE:
                raise WarehouseError("DATASET_PG_NEW_IDLE_CONNECTION_REQUIRED")
            owned = True
            connection.autocommit = True
            with connection.transaction():
                with connection.cursor(row_factory=tuple_row) as cursor:
                    cursor.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY" if readonly
                                   else "SET TRANSACTION ISOLATION LEVEL READ COMMITTED, READ WRITE")
                    cursor.execute("SET LOCAL search_path TO pg_catalog")
                    cursor.execute("SET LOCAL timezone TO 'UTC'")
                    cursor.execute("SET LOCAL datestyle TO 'ISO, YMD'")
                    cursor.execute("SELECT set_config('statement_timeout', %s, true), set_config('lock_timeout', %s, true)",
                                   (str(self.statement_timeout_ms), str(self.lock_timeout_ms)))
                    if check:
                        cursor.execute(f"SELECT format, warehouse_id FROM {self._table(_FORMAT)} WHERE singleton=true")
                        row = cursor.fetchone()
                        if not row or row[0] != SCHEMA or row[1] != self.warehouse_id:
                            raise WarehouseError("DATASET_PG_WAREHOUSE_IDENTITY_CHANGED")
                    yield cursor
        except psycopg.Error as error:
            codes = {"23505": "DATASET_PG_DUPLICATE_KEY", "23502": "DATASET_PG_NULL_NOT_ALLOWED",
                     "42501": "DATASET_PG_DATABASE_PERMISSION_DENIED", "57014": "DATASET_PG_OPERATION_CANCELLED",
                     "55P03": "DATASET_PG_DATABASE_BUSY", "22003": "DATASET_PG_NUMERIC_RANGE",
                     "22P02": "DATASET_PG_VALUE_NOT_REPRESENTABLE"}
            raise WarehouseError(codes.get(error.sqlstate, "DATASET_PG_DATABASE_OPERATION_FAILED"), sqlstate=error.sqlstate) from None
        finally:
            if owned:
                connection.close()

    def _lock(self, cursor, kind, value=""):
        key = int.from_bytes(hashlib.sha256(f"{SCHEMA}\0{self.schema}\0{kind}\0{value}".encode()).digest()[:8], "big", signed=True)
        cursor.execute("SELECT pg_advisory_xact_lock(%s)", (key,))

    def _initialize(self, *, create):
        with self._transaction(readonly=not create, check=False) as cursor:
            if create:
                self._lock(cursor, "initialize")
                cursor.execute(f"CREATE SCHEMA IF NOT EXISTS {_identifier(self.schema)}")
            cursor.execute("SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=%s", (self.schema,))
            relations = {row[0] for row in cursor.fetchall()}
            if _FORMAT not in relations:
                if not create or relations:
                    raise WarehouseError("DATASET_PG_EMPTY_DEDICATED_SCHEMA_REQUIRED")
                identifier = str(uuid.uuid4())
                if self.warehouse_id is not None:
                    raise WarehouseError("DATASET_PG_EXPECTED_WAREHOUSE_NOT_FOUND")
                cursor.execute(f"CREATE TABLE {self._table(_FORMAT)}(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), format text NOT NULL, warehouse_id text NOT NULL)")
                cursor.execute(f"CREATE TABLE {self._table(_VERSIONS)}(sequence bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, version_id text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT transaction_timestamp(), record text NOT NULL, manifest bytea NOT NULL)")
                cursor.execute(f"CREATE TABLE {self._table(_VIEWS)}(name text PRIMARY KEY, version_id text NOT NULL REFERENCES {self._table(_VERSIONS)}(version_id), revision bigint NOT NULL CHECK(revision>0))")
                cursor.execute(f"CREATE TABLE {self._table(_HISTORY)}(sequence bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL, version_id text NOT NULL REFERENCES {self._table(_VERSIONS)}(version_id), previous_version text, revision bigint NOT NULL, activated_at timestamptz NOT NULL DEFAULT transaction_timestamp(), UNIQUE(name,revision))")
                cursor.execute(f"INSERT INTO {self._table(_FORMAT)}(format,warehouse_id) VALUES(%s,%s)", (SCHEMA, identifier))
            cursor.execute(f"SELECT format, warehouse_id FROM {self._table(_FORMAT)} WHERE singleton=true")
            row = cursor.fetchone()
            if not row or row[0] != SCHEMA or self.warehouse_id is not None and row[1] != self.warehouse_id:
                raise WarehouseError("DATASET_PG_WAREHOUSE_IDENTITY_CHANGED")
            self.warehouse_id = row[1]
            self._semantics_ready = _SEMANTICS in relations

    def _version(self, cursor, version_id, *, include_semantics=False):
        _version_id(version_id)
        cursor.execute(f"SELECT sequence, record FROM {self._table(_VERSIONS)} WHERE version_id=%s", (version_id,))
        row = cursor.fetchone()
        if row is None:
            raise WarehouseError("DATASET_PG_VERSION_NOT_FOUND")
        record = parse(row[1].encode())
        identity = {key: record.get(key) for key in ("schema", "manifestSha256", "sourceBindingSha256", "mapping")}
        if (record.get("version_id") != version_id or record.get("schema") != SCHEMA
                or record.get("warehouse_id") != self.warehouse_id or record.get("warehouse_schema") != self.schema
                or record.get("table") != "_sf_data_" + version_id[:48]
                or digest(_json(identity).encode()) != version_id):
            raise WarehouseError("DATASET_PG_EDITION_METADATA_CHANGED")
        version = {**record, "sequence": row[0]}
        return self._edition_semantics(cursor, version) if include_semantics else version

    def _retained_manifest(self, cursor, version):
        cursor.execute(f"SELECT manifest FROM {self._table(_VERSIONS)} WHERE version_id=%s",
                       (version["version_id"],))
        row = cursor.fetchone()
        if row is None:
            raise WarehouseError("DATASET_PG_VERSION_NOT_FOUND")
        raw = bytes(row[0])
        if digest(raw) != version["manifestSha256"]:
            raise WarehouseError("DATASET_PG_MANIFEST_CHANGED")
        return raw

    def _edition_semantics(self, cursor, version):
        manifest = parse(self._retained_manifest(cursor, version))
        declared = manifest.get("semantics")
        output = manifest.get("outputs", {}).get("semantics.json")
        if declared is None:
            if output is not None or version.get("semantics") is not None:
                raise WarehouseError("DATASET_PG_SEMANTIC_MANIFEST_CHANGED")
            return {**version, "semantics": None, "semantic_dictionary": None,
                    "semantics_status": "NONE"}
        if not isinstance(declared, dict) or not isinstance(output, dict):
            raise WarehouseError("DATASET_PG_SEMANTIC_MANIFEST_CHANGED")
        cursor.execute("SELECT to_regclass(%s)", (self._table(_SEMANTICS),))
        row = None
        if cursor.fetchone()[0] is not None:
            cursor.execute(f"SELECT record,document FROM {self._table(_SEMANTICS)} WHERE version_id=%s",
                           (version["version_id"],))
            row = cursor.fetchone()
        if row is None:
            # Earlier receivers retained the bound manifest without this optional
            # output. Reimporting its original reviewed delivery attaches it to
            # the SAME edition; existing rows/views remain available meanwhile.
            return {**version, "semantics": None, "semantic_dictionary": None,
                    "semantics_status": "SOURCE_REQUIRED",
                    "semantic_source": {"definition": declared, "file": output}}
        descriptor, raw = parse(row[0].encode()), bytes(row[1])
        context = _bound_semantics(raw, descriptor, manifest,
                                  DatasetMapping.from_record(version["mapping"]), version["version_id"])
        return {**version, "semantics": descriptor,
                "semantic_dictionary": context["document"], "semantics_status": "RETAINED"}

    def _prepare_semantics(self):
        if self._semantics_ready:
            return
        # The FK's initial DDL needs a referenced-table lock. Prepare it before
        # any import writes an edition, so different imports cannot form a
        # version-INSERT/advisory-lock cycle. COPY remains concurrent.
        with self._transaction() as cursor:
            self._lock(cursor, "semantics")
            cursor.execute(f"CREATE TABLE IF NOT EXISTS {self._table(_SEMANTICS)}"
                           f"(version_id text PRIMARY KEY REFERENCES {self._table(_VERSIONS)}(version_id), "
                           "record text NOT NULL, document bytea NOT NULL)")
        self._semantics_ready = True

    def _retain_semantics(self, cursor, source):
        if source.semantic_source is None:
            return False
        cursor.execute(f"SELECT record,document FROM {self._table(_SEMANTICS)} WHERE version_id=%s",
                       (source.version_id,))
        row = cursor.fetchone()
        raw = source.semantic_source["bytes"]
        descriptor = _semantic_descriptor(source.semantic_source, source.mapping, enforced=True)
        _bound_semantics(raw, descriptor, source.manifest, source.mapping, source.version_id)
        if row is not None:
            if bytes(row[1]) != raw or not same_json(parse(row[0].encode()), descriptor):
                raise WarehouseError("DATASET_PG_RETAINED_SEMANTICS_CHANGED")
            return False
        cursor.execute(f"INSERT INTO {self._table(_SEMANTICS)}(version_id,record,document) VALUES(%s,%s,%s)",
                       (source.version_id, _json(descriptor), raw))
        return True

    def import_delivery(self, delivery: DatasetDelivery, mapping: DatasetMapping, *, expected_version=None):
        """Load every verified row and all source metadata in one transaction."""
        source = _input(delivery, mapping)
        if expected_version is not None and source.version_id != expected_version:
            raise WarehouseError("DATASET_PG_REVIEWED_INPUT_CHANGED")
        if source.semantic_source is not None:
            self._prepare_semantics()
        table = "_sf_data_" + source.version_id[:48]
        observed = [set() for _ in mapping.columns]
        with delivery.file("dataset.jsonl").open() as stream, self._transaction() as cursor:
            self._lock(cursor, "edition", source.version_id)
            cursor.execute(f"SELECT version_id FROM {self._table(_VERSIONS)} WHERE version_id=%s", (source.version_id,))
            if cursor.fetchone():
                received = self._retain_semantics(cursor, source)
                return {**self._version(cursor, source.version_id, include_semantics=True),
                        "import_status": "UNCHANGED", "semantics_received": received}
            columns = [f"{_identifier(_ORDINAL)} bigint NOT NULL UNIQUE", f"{_identifier(_ORIGINAL)} json NOT NULL"]
            columns += [f"{_identifier(c.column)} {c.type}" + (' COLLATE pg_catalog."C"' if c.type == "text" else "") + (" NOT NULL" if not c.nullable else "") for c in mapping.columns]
            keys = [c.column for c in mapping.columns if c.source in mapping.keys] or [_ORDINAL]
            columns.append("PRIMARY KEY (" + ",".join(_identifier(key) for key in keys) + ")")
            cursor.execute(f"CREATE TABLE {self._table(table)}(" + ",".join(columns) + ")")
            copy_columns = [_ORDINAL, _ORIGINAL, *(c.column for c in mapping.columns)]
            with cursor.copy(f"COPY {self._table(table)}(" + ",".join(_identifier(c) for c in copy_columns) + ") FROM STDIN") as copy:
                for ordinal, raw, values, kinds in _rows(source, stream):
                    copy.write_row((ordinal, raw, *values))
                    for index, kind in enumerate(kinds):
                        observed[index].add(kind)
            cursor.execute("SELECT transaction_timestamp()")
            created = cursor.fetchone()[0].isoformat()
            record = {**source.record(),
                      "semantics": _semantic_descriptor(source.semantic_source, mapping, enforced=True)
                                   if source.semantic_source is not None else None,
                      "semantics_status": "RETAINED" if source.semantic_source is not None else "NONE",
                      "warehouse_id": self.warehouse_id, "warehouse_schema": self.schema,
                      "table": table, "qualified_table": self._table(table), "created_at": created,
                      "column_types": [{**c.record(), "json_types": sorted(observed[i])} for i, c in enumerate(mapping.columns)]}
            cursor.execute(f"INSERT INTO {self._table(_VERSIONS)}(version_id,record,manifest) VALUES(%s,%s,%s)",
                           (source.version_id, _json(record), source.manifest_bytes))
            self._retain_semantics(cursor, source)
            record = self._version(cursor, source.version_id, include_semantics=True)
        return {**record, "import_status": "IMPORTED",
                "semantics_received": source.semantic_source is not None}

    def status(self):
        with self._transaction(readonly=True) as cursor:
            cursor.execute(f"SELECT count(*) FROM {self._table(_VERSIONS)}")
            editions = cursor.fetchone()[0]
            cursor.execute(f"SELECT name,version_id,revision FROM {self._table(_VIEWS)} ORDER BY name")
            views = [{"name": row[0], "version_id": row[1], "revision": row[2]} for row in cursor.fetchall()]
            cursor.execute("SHOW server_version")
            return {"schema": SCHEMA, "warehouse_id": self.warehouse_id, "warehouse_schema": self.schema,
                    "editions": editions, "views": views, "postgresql_version": cursor.fetchone()[0]}

    def version(self, version_id):
        with self._transaction(readonly=True) as cursor:
            return self._version(cursor, version_id, include_semantics=True)

    def manifest_bytes(self, version_id):
        _version_id(version_id)
        with self._transaction(readonly=True) as cursor:
            version = self._version(cursor, version_id)
            return self._retained_manifest(cursor, version)

    def semantics(self, version_id):
        """Open original source meanings and their reviewed SQL aliases."""
        with self._transaction(readonly=True) as cursor:
            version = self._version(cursor, version_id, include_semantics=True)
            if version["semantics_status"] == "SOURCE_REQUIRED":
                raise WarehouseError("DATASET_PG_REIMPORT_ORIGINAL_DICTIONARY_REQUIRED")
            if version["semantics"] is None:
                return None
            return {**version["semantics"], "version_id": version_id,
                    "document": version["semantic_dictionary"]}

    def semantics_bytes(self, version_id):
        """Export the exact original dictionary; None denotes a legacy edition."""
        with self._transaction(readonly=True) as cursor:
            version = self._version(cursor, version_id, include_semantics=True)
            if version["semantics_status"] == "SOURCE_REQUIRED":
                raise WarehouseError("DATASET_PG_REIMPORT_ORIGINAL_DICTIONARY_REQUIRED")
            if version["semantics"] is None:
                return None
            cursor.execute(f"SELECT document FROM {self._table(_SEMANTICS)} WHERE version_id=%s",
                           (version_id,))
            return bytes(cursor.fetchone()[0])

    def compare_semantics(self, before_id, after_id):
        """Compare dictionary definitions, capture and aliases independently of rows."""
        with self._transaction(readonly=True) as cursor:
            before = self._version(cursor, before_id, include_semantics=True)
            after = self._version(cursor, after_id, include_semantics=True)
            if any(v["semantics_status"] == "SOURCE_REQUIRED" for v in (before, after)):
                raise WarehouseError("DATASET_PG_REIMPORT_ORIGINAL_DICTIONARY_REQUIRED")
        first, second = before.get("semantics"), after.get("semantics")

        def columns(version):
            document = version.get("semantic_dictionary") or {}
            meanings = {column["name"]: column for column in document.get("columns", [])}
            keys = set(version["mapping"]["keys"])
            return {column["source"]: {"sql_column": column["column"],
                     "sql_type": column["type"], "nullable": column["nullable"],
                     "receiving_key": column["source"] in keys,
                     "meaning": meanings.get(column["source"])}
                    for column in version["mapping"]["columns"]}

        left, right = columns(before), columns(after)
        changes = [{"source": name, "before": left.get(name), "after": right.get(name)}
                   for name in sorted(set(left) | set(right))
                   if not same_json(left.get(name), right.get(name))]
        return {"schema": "stellar-forge.python-semantic-comparison.v1",
                "before_version": before_id, "after_version": after_id,
                "before": first, "after": second,
                "definition_changed": (first or {}).get("definition_sha256") != (second or {}).get("definition_sha256"),
                "capture_changed": (first or {}).get("capture_manifest_sha256") != (second or {}).get("capture_manifest_sha256"),
                "mapping_changed": not same_json(before["mapping"], after["mapping"]),
                "before_mapping": before["mapping"], "after_mapping": after["mapping"],
                "columns": changes, "before_document": before.get("semantic_dictionary"),
                "after_document": after.get("semantic_dictionary")}

    def versions(self, *, before=None, limit=100):
        _page(before, limit)
        with self._transaction(readonly=True) as cursor:
            where = "WHERE sequence < %s" if before is not None else ""
            cursor.execute(f"SELECT sequence,record FROM {self._table(_VERSIONS)} {where} ORDER BY sequence DESC LIMIT %s",
                           ((before,) if before is not None else ()) + (limit + 1,))
            rows = cursor.fetchall()
            return {"versions": [{**parse(row[1].encode()), "sequence": row[0]} for row in rows[:limit]],
                    "next_before": rows[limit - 1][0] if len(rows) > limit else None}

    def current(self, name):
        _public_name(name)
        with self._transaction(readonly=True) as cursor:
            cursor.execute(f"SELECT version_id,revision FROM {self._table(_VIEWS)} WHERE name=%s", (name,))
            row = cursor.fetchone()
            return {"name": name, "qualified_view": self._table(name), "revision": row[1] if row else 0,
                    "version": self._version(cursor, row[0], include_semantics=True) if row else None}

    def activate(self, name, version_id, *, expected_revision):
        """Atomically select a version while retaining grants/dependent views."""
        _public_name(name)
        if type(expected_revision) is not int or expected_revision < 0:
            raise WarehouseError("DATASET_PG_VIEW_REVISION_INVALID")
        with self._transaction() as cursor:
            self._lock(cursor, "view", name)
            version = self._version(cursor, version_id, include_semantics=True)
            cursor.execute(f"SELECT version_id,revision FROM {self._table(_VIEWS)} WHERE name=%s FOR UPDATE", (name,))
            current = cursor.fetchone()
            revision = current[1] if current else 0
            if expected_revision != revision:
                raise WarehouseError("DATASET_PG_VIEW_CHANGED")
            if current and current[0] == version_id:
                return {"status": "UNCHANGED", "name": name, "qualified_view": self._table(name), "revision": revision, "version": version}
            mapping = DatasetMapping.from_record(version["mapping"])
            if current:
                previous = self._version(cursor, current[0])
                if DatasetMapping.from_record(previous["mapping"]).signature != mapping.signature:
                    raise WarehouseError("DATASET_PG_VIEW_SCHEMA_CHANGED_USE_NEW_VIEW")
            else:
                cursor.execute("SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=%s AND c.relname=%s", (self.schema, name))
                if cursor.fetchone():
                    raise WarehouseError("DATASET_PG_UNMANAGED_RELATION_EXISTS")
            projection = ",".join(_identifier(c.column) for c in mapping.columns) + "," + _identifier(_ORDINAL)
            command = "CREATE OR REPLACE VIEW" if current else "CREATE VIEW"
            cursor.execute(f"{command} {self._table(name)} AS SELECT {projection} FROM {self._table(version['table'])}")
            revision += 1
            cursor.execute(f"INSERT INTO {self._table(_VIEWS)}(name,version_id,revision) VALUES(%s,%s,%s) ON CONFLICT(name) DO UPDATE SET version_id=EXCLUDED.version_id,revision=EXCLUDED.revision", (name, version_id, revision))
            cursor.execute(f"INSERT INTO {self._table(_HISTORY)}(name,version_id,previous_version,revision) VALUES(%s,%s,%s,%s)", (name, version_id, current[0] if current else None, revision))
        return {"status": "ACTIVATED", "name": name, "qualified_view": self._table(name), "revision": revision, "version": version}

    def history(self, name, *, before=None, limit=100):
        _public_name(name)
        _page(before, limit)
        with self._transaction(readonly=True) as cursor:
            where = " AND sequence < %s" if before is not None else ""
            cursor.execute(f"SELECT sequence,version_id,previous_version,revision,activated_at FROM {self._table(_HISTORY)} WHERE name=%s {where} ORDER BY sequence DESC LIMIT %s",
                           (name,) + ((before,) if before is not None else ()) + (limit + 1,))
            rows = cursor.fetchall()
            return {"name": name, "history": [{"sequence": r[0], "version_id": r[1], "previous_version": r[2], "revision": r[3], "activated_at": r[4].isoformat()} for r in rows[:limit]],
                    "next_before": rows[limit - 1][0] if len(rows) > limit else None}

    def rows(self, version_id, *, after=0, limit=100, include_original=False):
        if type(after) is not int or after < 0 or type(include_original) is not bool:
            raise WarehouseError("DATASET_PG_ROW_PAGE_INVALID")
        _page(None, limit)
        with self._transaction(readonly=True) as cursor:
            version = self._version(cursor, version_id)
            mapping = DatasetMapping.from_record(version["mapping"])
            projection = [_identifier(_ORDINAL), *(_identifier(c.column) + ("::text" if c.type == "json" else "") for c in mapping.columns)]
            if include_original:
                projection.append(_identifier(_ORIGINAL) + "::text")
            cursor.execute(f"SELECT {','.join(projection)} FROM {self._table(version['table'])} WHERE {_identifier(_ORDINAL)}>%s ORDER BY {_identifier(_ORDINAL)} LIMIT %s", (after, limit + 1))
            rows = cursor.fetchall()
            output = []
            for row in rows[:limit]:
                item = {"row_number": row[0], "values": {c.column: _returned_value(c, row[i + 1]) for i, c in enumerate(mapping.columns)}}
                if include_original:
                    item["original_json"] = row[-1]
                output.append(item)
            return {"version_id": version_id, "rows": output, "next_after": rows[limit - 1][0] if len(rows) > limit else None}

    def compare(self, previous_id, current_id, *, offset=0, limit=100):
        """Compare all mapped values in PostgreSQL using declared source keys."""
        if type(offset) is not int or offset < 0:
            raise WarehouseError("DATASET_PG_COMPARE_OFFSET_INVALID")
        _page(None, limit)
        with self._transaction(readonly=True) as cursor:
            previous, current = self._version(cursor, previous_id), self._version(cursor, current_id)
            mapping, following = DatasetMapping.from_record(previous["mapping"]), DatasetMapping.from_record(current["mapping"])
            if mapping.record() != following.record() or not mapping.keys:
                raise WarehouseError("DATASET_PG_COMPARE_REQUIRES_SAME_MAPPING_AND_KEYS")
            keys = [c for c in mapping.columns if c.source in mapping.keys]
            join = " AND ".join(f"a.{_identifier(c.column)}=b.{_identifier(c.column)}" for c in keys)
            different = " OR ".join(f"a.{_identifier(c.column)}" + ("::text" if c.type == "json" else "") + f" IS DISTINCT FROM b.{_identifier(c.column)}" + ("::text" if c.type == "json" else "") for c in mapping.columns)
            old, new = f"a.{_identifier(_ORDINAL)}", f"b.{_identifier(_ORDINAL)}"
            change = f"CASE WHEN {old} IS NULL THEN 'ADDED' WHEN {new} IS NULL THEN 'REMOVED' WHEN ({different}) THEN 'CHANGED' ELSE 'UNCHANGED' END"
            joined = f"FROM {self._table(previous['table'])} a FULL OUTER JOIN {self._table(current['table'])} b ON {join}"
            cursor.execute(f"SELECT {change} AS kind,count(*) {joined} GROUP BY kind")
            totals = {"ADDED": 0, "REMOVED": 0, "CHANGED": 0, "UNCHANGED": 0}
            totals.update({r[0]: r[1] for r in cursor.fetchall()})
            # Composite-to-JSON text keeps an entire wide source below PostgreSQL's
            # target-list column limit. Python parses its numeric text as Decimal.
            projection = [change, old, new, "row_to_json(a)::text", "row_to_json(b)::text"]
            order = ",".join(f"COALESCE(a.{_identifier(c.column)},b.{_identifier(c.column)})" for c in keys)
            cursor.execute(f"SELECT {','.join(projection)} {joined} WHERE {old} IS NULL OR {new} IS NULL OR ({different}) ORDER BY {order} OFFSET %s LIMIT %s", (offset, limit + 1))
            rows = cursor.fetchall()
            changes = []
            for row in rows[:limit]:
                before = _database_row(row[3], mapping) if row[1] is not None else None
                after = _database_row(row[4], mapping) if row[2] is not None else None
                changes.append({"kind": row[0], "before_row": row[1], "after_row": row[2], "before": before, "after": after})
            return {"previous_version": previous_id, "current_version": current_id, "totals": totals,
                    "changes": changes, "next_offset": offset + limit if len(rows) > limit else None}


def _returned_value(column, value):
    if column.type == "json" and value is not None:
        return json.loads(value, parse_float=Decimal, object_pairs_hook=unique_object,
                          parse_constant=lambda _: (_ for _ in ()).throw(ValueError()))
    return value


def _database_row(raw, mapping):
    values = json.loads(raw, parse_float=Decimal, object_pairs_hook=unique_object,
                        parse_constant=lambda _: (_ for _ in ()).throw(ValueError()))
    result = {}
    for column in mapping.columns:
        value = values[column.column]
        if value is not None:
            if column.type == "numeric":
                value = Decimal(value)
            elif column.type == "double precision":
                value = float(value)
            elif column.type == "date":
                value = date.fromisoformat(value)
            elif column.type == "timestamp with time zone":
                value = datetime.fromisoformat(value)
        result[column.column] = value
    return result

"""Private browser receiving for the original PostgreSQL warehouse."""
from __future__ import annotations

from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import os
import re
import secrets
from urllib.parse import parse_qs, unquote, urlsplit

from . import _postgres_ui
from .errors import BuyerError
from .postgres_delivery import WarehouseError
from .postgres_operator import PostgresOperator, fields, integer, wire
from .storage import digest, dump, parse

_MAX_BODY = 2 * 1024 * 1024


def serve(warehouse, directory, *, port=0):
    """Open an owned IPv4 loopback listener and retain its private launch URL."""
    integer(port, maximum=65535)
    operator = PostgresOperator(warehouse, directory)
    token = secrets.token_urlsafe(32)

    class Handler(BaseHTTPRequestHandler):
        server_version = "StellarForgePostgres"
        sys_version = ""

        def setup(self):
            super().setup()
            self.connection.settimeout(30)

        def log_message(self, *args):
            pass

        def _reply(self, status, body, mime="application/json;charset=utf-8", filename=None):
            payload = body if isinstance(body, bytes) else json.dumps(
                wire(body), ensure_ascii=False, allow_nan=False, separators=(",", ":")).encode()
            self.send_response(status)
            self.send_header("Content-Type", mime)
            self.send_header("Content-Length", str(len(payload)))
            self.send_header("Cache-Control", "no-store")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.send_header("Referrer-Policy", "no-referrer")
            self.send_header("Content-Security-Policy",
                             "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; "
                             "base-uri 'none'; frame-ancestors 'none'; form-action 'none'")
            if filename:
                safe = re.sub(r"[^A-Za-z0-9_.-]", "_", filename)
                self.send_header("Content-Disposition", 'attachment; filename="' + safe + '"')
                self.send_header("X-Content-SHA256", digest(payload))
            self.end_headers()
            if self.command != "HEAD":
                self.wfile.write(payload)

        def _report(self, request_id):
            with operator.report_stream(request_id) as opened:
                stream, artifact = opened
                self.send_response(200)
                self.send_header("Content-Type", "application/zip")
                self.send_header("Content-Length", str(artifact["bytes"]))
                self.send_header("Content-Disposition", 'attachment; filename="' + artifact["filename"] + '"')
                self.send_header("X-Content-SHA256", artifact["sha256"])
                self.send_header("Cache-Control", "no-store")
                self.send_header("X-Content-Type-Options", "nosniff")
                self.send_header("Referrer-Policy", "no-referrer")
                self.send_header("Content-Security-Policy", "default-src 'none'; frame-ancestors 'none'")
                self.end_headers()
                if self.command != "HEAD":
                    while chunk := stream.read(1024 * 1024):
                        self.wfile.write(chunk)

        def _dispatch(self):
            origin = "http://127.0.0.1:" + str(self.server.server_port)
            if (self.headers.get_all("Host") != [origin[7:]]
                    or self.headers.get("Origin", origin) != origin
                    or self.headers.get("Sec-Fetch-Site", "none") not in {"none", "same-origin"}):
                return self._reply(403, {"error": "DATASET_PG_OPERATOR_LOCAL_ORIGIN_REQUIRED"})
            url = urlsplit(self.path)
            if url.scheme or url.netloc or url.fragment:
                return self._reply(400, {"error": "DATASET_PG_OPERATOR_ROUTE_INVALID"})
            assets = {"/": (_postgres_ui.HTML, "text/html;charset=utf-8"),
                      "/app.js": (_postgres_ui.JS, "text/javascript;charset=utf-8"),
                      "/style.css": (_postgres_ui.CSS, "text/css;charset=utf-8")}
            if self.command in {"GET", "HEAD"} and url.path in assets and not url.query:
                value, mime = assets[url.path]
                return self._reply(200, value.encode(), mime)
            capabilities = self.headers.get_all("X-Postgres-Capability", [])
            if len(capabilities) != 1 or not secrets.compare_digest(capabilities[0], token):
                return self._reply(403, {"error": "DATASET_PG_OPERATOR_CAPABILITY_REQUIRED"})
            parameters = parse_qs(url.query, strict_parsing=True)
            if any(len(values) != 1 for values in parameters.values()):
                raise WarehouseError("DATASET_PG_OPERATOR_PARAMETERS_INVALID")
            values = {key: items[0] for key, items in parameters.items()}
            parts = [unquote(part) for part in url.path.strip("/").split("/")]
            if self.command in {"GET", "HEAD"}:
                with operator.mutex:
                    if url.path == "/api/state" and not values:
                        return self._reply(200, operator.state())
                    if url.path == "/api/versions":
                        fields(values, optional=("before", "limit"))
                        return self._reply(200, warehouse.versions(
                            before=int(values["before"]) if "before" in values else None,
                            limit=integer(int(values.get("limit", "50")), minimum=1)))
                    if url.path in {"/api/reviews", "/api/requests"}:
                        fields(values, optional=("before", "limit"))
                        return self._reply(200, operator.records(parts[-1], before=values.get("before"),
                            limit=integer(int(values.get("limit", "50")), minimum=1, maximum=100)))
                    if len(parts) == 3 and parts[:2] == ["api", "versions"] and not values:
                        return self._reply(200, warehouse.version(parts[2]))
                    if len(parts) == 3 and parts[:2] == ["api", "reviews"] and not values:
                        return self._reply(200, operator.review_record(parts[2]))
                    if len(parts) == 3 and parts[:2] == ["api", "requests"] and not values:
                        return self._reply(200, operator.request_record(parts[2]))
                    if len(parts) == 4 and parts[:2] == ["api", "period-reports"] and parts[3] == "archive" and not values:
                        return self._report(parts[2])
                    if url.path == "/api/current":
                        fields(values, ("name",))
                        return self._reply(200, warehouse.current(values["name"]))
                    if url.path == "/api/history":
                        fields(values, ("name",), ("before", "limit"))
                        return self._reply(200, warehouse.history(values["name"],
                            before=int(values["before"]) if "before" in values else None,
                            limit=integer(int(values.get("limit", "50")), minimum=1)))
                    if url.path == "/api/rows":
                        fields(values, ("version_id",), ("after", "limit", "include_original"))
                        if values.get("include_original", "true") not in {"true", "false"}:
                            raise WarehouseError("DATASET_PG_OPERATOR_PARAMETERS_INVALID")
                        return self._reply(200, warehouse.rows(values["version_id"],
                            after=integer(int(values.get("after", "0")), maximum=1000000),
                            limit=integer(int(values.get("limit", "50")), minimum=1),
                            include_original=values.get("include_original", "true") == "true"))
                    if url.path == "/api/compare":
                        fields(values, ("previous", "current"), ("offset", "limit"))
                        return self._reply(200, warehouse.compare(values["previous"], values["current"],
                            offset=integer(int(values.get("offset", "0")), maximum=2000000),
                            limit=integer(int(values.get("limit", "50")), minimum=1)))
                    if url.path in {"/api/semantics", "/api/semantics-file"}:
                        fields(values, ("version_id",))
                        version_id = values["version_id"]
                        if url.path == "/api/semantics":
                            return self._reply(200, warehouse.semantics(version_id))
                        raw = warehouse.semantics_bytes(version_id)
                        if raw is None:
                            return self._reply(404, {"error": "DATASET_PG_LEGACY_EDITION_HAS_NO_DICTIONARY"})
                        return self._reply(200, raw, "application/json",
                                           "semantics-" + version_id + ".json")
                    if url.path == "/api/semantic-compare":
                        fields(values, ("previous", "current"))
                        comparison = warehouse.compare_semantics(values["previous"], values["current"])
                        return self._reply(200, comparison)
                    if url.path == "/api/manifest":
                        fields(values, ("version_id",))
                        return self._reply(200, warehouse.manifest_bytes(values["version_id"]),
                            "application/json", "manifest-" + values["version_id"] + ".json")
                    if url.path == "/api/mapping":
                        fields(values, ("version_id",))
                        mapping = warehouse.version(values["version_id"])["mapping"]
                        return self._reply(200, mapping, filename="postgres-mapping-" + values["version_id"] + ".json")
                    if url.path == "/api/edition":
                        fields(values, ("version_id",))
                        return self._reply(200, warehouse.version(values["version_id"]),
                            filename="postgres-edition-" + values["version_id"] + ".json")
            elif self.command == "POST" and not url.query:
                if self.headers.get("Transfer-Encoding") or self.headers.get_content_type() != "application/json":
                    return self._reply(415, {"error": "DATASET_PG_OPERATOR_JSON_REQUIRED"})
                sizes = self.headers.get_all("Content-Length", [])
                if len(sizes) != 1 or not sizes[0].isascii() or not sizes[0].isdigit():
                    return self._reply(411, {"error": "DATASET_PG_OPERATOR_LENGTH_REQUIRED"})
                size = int(sizes[0])
                if not 0 < size <= _MAX_BODY:
                    return self._reply(413, {"error": "DATASET_PG_OPERATOR_REQUEST_SIZE_INVALID"})
                raw = self.rfile.read(size)
                if len(raw) != size:
                    raise WarehouseError("DATASET_PG_OPERATOR_REQUEST_INCOMPLETE")
                body = parse(raw)
                if len(parts) == 4 and parts[:2] == ["api", "requests"] and parts[3] == "resume":
                    fields(body)
                    return self._reply(200, operator.resume(parts[2]))
                return self._reply(200, operator.perform(url.path, body))
            return self._reply(404, {"error": "DATASET_PG_OPERATOR_NOT_FOUND"})

        def _handle(self):
            try:
                self._dispatch()
            except (BrokenPipeError, ConnectionResetError, TimeoutError):
                self.close_connection = True
            except WarehouseError as error:
                status = 409 if any(part in error.code for part in
                    ("CHANGED", "BUSY", "EXISTS", "ALREADY", "INTERRUPTED")) else 400
                self._reply(status, error.report())
            except BuyerError as error:
                self._reply(400, {"error": error.code})
            except (ValueError, TypeError, KeyError, OverflowError):
                self._reply(400, {"error": "DATASET_PG_OPERATOR_REQUEST_INVALID"})
            except OSError:
                self._reply(409, {"error": "DATASET_PG_OPERATOR_LOCAL_FILE_UNAVAILABLE"})
            except Exception:
                self._reply(500, {"error": "DATASET_PG_OPERATOR_OPERATION_FAILED"})

        do_GET = do_POST = do_HEAD = _handle

    class Server(ThreadingHTTPServer):
        daemon_threads = False

        def server_close(self):
            try:
                super().server_close()
            finally:
                operator.close()

    try:
        server = Server(("127.0.0.1", port), Handler)
        server.operator = operator
        url = "http://127.0.0.1:" + str(server.server_port) + "/#" + token
        control = operator.directory / "postgres-launch.json"
        dump(control, {"schema": "stellar-forge.postgres-operator-launch.v1",
                       "directory": str(operator.directory), "pid": os.getpid(), "url": url,
                       "operator_id": operator.identity["operator_id"],
                       "warehouse_id": warehouse.warehouse_id, "warehouse_schema": warehouse.schema})
        return server, control, url
    except BaseException:
        if "server" in locals():
            server.server_close()
        else:
            operator.close()
        raise

"""Reviewed PostgreSQL receiving over the original warehouse and delivery."""
from __future__ import annotations

from datetime import date, datetime, timezone
from decimal import Decimal
import fcntl
import json
import os
from pathlib import Path
import re
import secrets
import stat
import threading

from .errors import BuyerError
from .postgres_delivery import (
    Column, DatasetMapping, PostgresWarehouse, WarehouseError,
    load_delivery_report, review_delivery,
)
from .storage import digest, dump, parse, private_directory, read, unique_object, write

SCHEMA = "stellar-forge.postgres-operator.v1"
_ID = re.compile(r"[a-f0-9]{32}")
_MAX_REPORT = 8 * 1024 * 1024
_MAX_RECORD = 8 * 1024 * 1024  # Reviewed dictionaries plus original edition/request metadata.


def wire(value):
    """Keep exact database numbers and dates intact in browser JSON."""
    if isinstance(value, Decimal):
        return str(value)
    if type(value) is int and abs(value) > 9007199254740991:
        return str(value)
    if isinstance(value, (date, datetime)):
        return value.isoformat()
    if isinstance(value, (tuple, list)):
        return [wire(item) for item in value]
    if isinstance(value, dict):
        return {key: wire(item) for key, item in value.items()}
    return value


def fields(value, required=(), optional=()):
    if (not isinstance(value, dict) or set(value) - set(required) - set(optional)
            or any(key not in value for key in required)):
        raise WarehouseError("DATASET_PG_OPERATOR_FIELDS_INVALID")
    return value


def integer(value, *, minimum=0, maximum=1000):
    if type(value) is not int or not minimum <= value <= maximum:
        raise WarehouseError("DATASET_PG_OPERATOR_PAGE_INVALID")
    return value


def _id(value):
    if not isinstance(value, str) or not _ID.fullmatch(value):
        raise WarehouseError("DATASET_PG_OPERATOR_ID_REQUIRED")
    return value


def _text(value, maximum, *, required=False):
    if (not isinstance(value, str) or len(value.encode()) > maximum
            or "\x00" in value or required and not value.strip()):
        raise WarehouseError("DATASET_PG_OPERATOR_TEXT_INVALID")
    return value


def _now():
    return datetime.now(timezone.utc).isoformat()


def _source(path):
    path = Path(os.path.abspath(Path(_text(path, 8192, required=True)).expanduser()))
    raw = read(path, _MAX_REPORT)
    delivery = load_delivery_report(path)
    if read(path, _MAX_REPORT) != raw:
        raise WarehouseError("DATASET_PG_REVIEWED_INPUT_CHANGED")
    return path, raw, delivery


class PostgresOperator:
    """One private operator directory bound to the actual PostgreSQL identity."""

    def __init__(self, warehouse: PostgresWarehouse, directory):
        self.warehouse = warehouse
        self.directory = private_directory(Path(directory))
        self.mutex = threading.RLock()
        self._owner = os.open(self.directory / "postgres-http.lock",
                              os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW, 0o600)
        try:
            info = os.fstat(self._owner)
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_mode & 0o077:
                raise WarehouseError("DATASET_PG_OPERATOR_PRIVATE_LOCK_REQUIRED")
            fcntl.flock(self._owner, fcntl.LOCK_EX | fcntl.LOCK_NB)
            self.reviews = private_directory(self.directory / "reviews")
            self.requests = private_directory(self.directory / "requests")
            self.sources = private_directory(self.directory / "reviewed-sources")
            self.reports = private_directory(self.directory / "period-reports")
            path = self.directory / "postgres-workspace.json"
            if path.exists():
                identity = parse(read(path, 65536))
                if (identity.get("schema") != SCHEMA
                        or identity.get("warehouse_id") != warehouse.warehouse_id
                        or identity.get("warehouse_schema") != warehouse.schema):
                    raise WarehouseError("DATASET_PG_OPERATOR_WAREHOUSE_CHANGED")
                _id(identity.get("operator_id"))
            else:
                identity = {"schema": SCHEMA, "operator_id": secrets.token_hex(16),
                            "warehouse_id": warehouse.warehouse_id,
                            "warehouse_schema": warehouse.schema, "created_at": _now()}
                dump(path, identity, exclusive=True)
            self.identity = identity
        except BlockingIOError:
            self.close()
            raise WarehouseError("DATASET_PG_OPERATOR_ALREADY_OPEN") from None
        except BaseException:
            self.close()
            raise

    def close(self):
        if self._owner is not None:
            os.close(self._owner)
            self._owner = None

    def _record(self, directory, record_id):
        record_id = _id(record_id)
        record = parse(read(directory / (record_id + ".json"), _MAX_RECORD))
        if (not isinstance(record, dict) or record.get("operator_id") != self.identity["operator_id"]
                or record.get("warehouse_id") != self.warehouse.warehouse_id
                or record.get("record_id") != record_id):
            raise WarehouseError("DATASET_PG_OPERATOR_RECORD_CHANGED")
        return record

    def records(self, kind, *, before=None, limit=50):
        if kind not in {"reviews", "requests"}:
            raise WarehouseError("DATASET_PG_OPERATOR_RECORD_KIND_INVALID")
        integer(limit, minimum=1, maximum=100)
        if before is not None:
            _text(before, 128, required=True)
        directory = self.reviews if kind == "reviews" else self.requests
        rows = []
        for path in directory.glob("*.json"):
            record = self._record(directory, path.stem)
            cursor = record["created_at"] + "/" + record["record_id"]
            if before is not None and cursor >= before:
                continue
            summary = {key: record[key] for key in (
                "record_id", "created_at", "state", "route", "source_path", "version_id",
                "reviewer", "note", "row_count", "updated_at", "error"
            ) if key in record}
            if kind == "requests":
                summary["body"] = record["body"]
            summary["cursor"] = cursor
            rows.append(summary)
        rows.sort(key=lambda row: row["cursor"], reverse=True)
        return {kind: rows[:limit],
                "next_before": rows[limit - 1]["cursor"] if len(rows) > limit else None}

    def state(self):
        with self.mutex:
            return {"identity": self.identity, "directory": str(self.directory),
                    "warehouse": self.warehouse.status(),
                    "versions": self.warehouse.versions(limit=50),
                    "reviews": self.records("reviews"),
                    "requests": self.records("requests")}

    def inspect_delivery(self, report_path):
        with self.mutex:
            path, raw, delivery = _source(report_path)
            manifest = parse(delivery.file("manifest.json").read_bytes(limit=4 * 1024 * 1024))
            dataset = manifest.get("dataset", {})
            names, count = dataset.get("projectedFields"), dataset.get("rows")
            if (not isinstance(names, list) or not names or len(names) > 1024
                    or any(not isinstance(name, str) or not name for name in names)
                    or len(set(names)) != len(names) or type(count) is not int or count < 0):
                raise WarehouseError("DATASET_PG_MANIFEST_BINDING_INVALID")
            observed = {name: set() for name in names}
            nulls = {name: 0 for name in names}
            overflow, preview, rows = set(), [], 0
            with delivery.file("dataset.jsonl").open() as stream:
                while line := stream.readline(2097153):
                    rows += 1
                    if len(line) > 2097152 or not line.endswith(b"\n") or rows > count:
                        raise WarehouseError("DATASET_PG_ROW_FORMAT_OR_COUNT_INVALID", row=rows)
                    try:
                        row = json.loads(line.decode(), object_pairs_hook=unique_object,
                                         parse_float=Decimal,
                                         parse_constant=lambda _: (_ for _ in ()).throw(ValueError()))
                    except (ValueError, UnicodeError):
                        raise WarehouseError("DATASET_PG_INVALID_JSON_ROW", row=rows) from None
                    if not isinstance(row, dict) or set(row) != set(names):
                        raise WarehouseError("DATASET_PG_ROW_FIELDS_MISMATCH", row=rows)
                    if len(preview) < 5:
                        preview.append(wire(row))
                    for name, value in row.items():
                        kind = ("null" if value is None else "boolean" if type(value) is bool
                                else "integer" if type(value) is int else "number" if isinstance(value, Decimal)
                                else "string" if isinstance(value, str) else None)
                        if kind is None:
                            raise WarehouseError("DATASET_PG_NATIVE_SCALAR_REQUIRED", row=rows, field=name)
                        observed[name].add(kind)
                        nulls[name] += value is None
                        if type(value) is int and not -(2**63) <= value < 2**63:
                            overflow.add(name)
            if rows != count:
                raise WarehouseError("DATASET_PG_ROW_FORMAT_OR_COUNT_INVALID")
            columns, used = [], set()
            for index, name in enumerate(names):
                kinds = observed[name] - {"null"}
                kind = ("text" if not kinds else "numeric" if kinds <= {"integer", "number"} and
                        ("number" in kinds or name in overflow) else
                        {"string": "text", "integer": "bigint", "boolean": "boolean"}.get(next(iter(kinds)), "json")
                        if len(kinds) == 1 else "json")
                sql_name = name
                try:
                    Column(name, sql_name, kind)
                except WarehouseError:
                    sql_name = "field_" + str(index + 1)
                while sql_name in used:
                    sql_name += "_"
                used.add(sql_name)
                columns.append(Column(name, sql_name, kind, nulls[name] > 0 or not kinds))
            mapping = DatasetMapping(tuple(columns))
            from .postgres_central import CentralAcceptedDelivery
            if isinstance(delivery, CentralAcceptedDelivery):
                mapping = delivery.suggested_mapping(nulls)
            native = review_delivery(delivery, mapping)
            return {"source_path": str(path), "source_sha256": digest(raw),
                    "dataset": native["dataset"], "row_count": native["row_count"],
                    "source_pages": native["source_pages"],
                    "payment_status": native.get("originalPaymentStatus"),
                    "source_kind": native.get("source_kind", "SF100_DELIVERY"),
                    "mapping": mapping.record(), "columns": native["columns"], "preview": preview,
                    "semantics": native["semantics"], "semantics_status": native["semantics_status"],
                    "semantic_dictionary": native["semantic_dictionary"]}

    def review(self, body):
        fields(body, ("report_path", "mapping", "reviewer", "note", "expected_report_sha256"),
               ("review_id",))
        _text(body["reviewer"], 160, required=True)
        _text(body["note"], 4000)
        if not isinstance(body["expected_report_sha256"], str) or not re.fullmatch(
                r"[a-f0-9]{64}", body["expected_report_sha256"]):
            raise WarehouseError("DATASET_PG_OPERATOR_SOURCE_REVIEW_REQUIRED")
        path, raw, delivery = _source(body["report_path"])
        if digest(raw) != body["expected_report_sha256"]:
            raise WarehouseError("DATASET_PG_REVIEWED_INPUT_CHANGED")
        mapping = DatasetMapping.from_record(body["mapping"])
        native = review_delivery(delivery, mapping)
        record_id = _id(body["review_id"]) if "review_id" in body else secrets.token_hex(16)
        source = self.sources / (record_id + ".json")
        target = self.reviews / (record_id + ".json")
        intent_path = self.reviews / (record_id + ".intent")
        # Preserve the caller's complete intent before either durable review
        # member. The input bytes identify the source independently of where
        # the same private operator directory is restored.
        intent = {"source_sha256": digest(raw), "mapping": mapping.record(),
                  "reviewer": body["reviewer"], "note": body["note"]}
        if intent_path.exists():
            if parse(read(intent_path, _MAX_RECORD)) != intent:
                raise WarehouseError("DATASET_PG_REVIEW_ID_REUSED")
        elif target.exists():
            previous = self._record(self.reviews, record_id)
            if (previous.get("source_sha256") != intent["source_sha256"]
                    or previous.get("mapping") != intent["mapping"]
                    or previous.get("reviewer") != body["reviewer"].strip()
                    or previous.get("note") != body["note"]):
                raise WarehouseError("DATASET_PG_REVIEW_ID_REUSED")
            dump(intent_path, intent, exclusive=True)
        else:
            dump(intent_path, intent, exclusive=True)
        if source.exists():
            if read(source, _MAX_REPORT) != raw:
                raise WarehouseError("DATASET_PG_OPERATOR_REVIEW_CHANGED")
        else:
            write(source, raw, exclusive=True)
        if target.exists():
            previous = self._record(self.reviews, record_id)
            if (previous.get("state") != "REVIEWED" or previous.get("version_id") != native["version_id"]
                    or previous.get("source_sha256") != intent["source_sha256"]
                    or previous.get("mapping") != intent["mapping"]
                    or previous.get("reviewer") != body["reviewer"].strip()
                    or previous.get("note") != body["note"]
                    or previous.get("review") != native):
                raise WarehouseError("DATASET_PG_OPERATOR_REVIEW_CHANGED")
            return previous
        record = {**self.identity, "record_id": record_id, "created_at": _now(),
                  "state": "REVIEWED", "source_path": str(path),
                  "source_sha256": digest(raw), "reviewer": body["reviewer"].strip(),
                  "note": body["note"], "mapping": mapping.record(),
                  "version_id": native["version_id"], "row_count": native["row_count"], "review": native}
        dump(target, record, exclusive=True)
        return record

    def _review_delivery(self, review):
        path = self.sources / (review["record_id"] + ".json")
        raw = read(path, _MAX_REPORT)
        if digest(raw) != review["source_sha256"]:
            raise WarehouseError("DATASET_PG_OPERATOR_REVIEW_CHANGED")
        from .postgres_central import SCHEMA as CENTRAL_SCHEMA
        retained = parse(raw)
        if retained.get("schema") == CENTRAL_SCHEMA:
            approval = retained.get("sourceBindingSha256")
            if not isinstance(approval, str) or not re.fullmatch(r"[a-f0-9]{64}", approval):
                raise WarehouseError("DATASET_PG_OPERATOR_REVIEW_CHANGED")
            # Central's approved CSV projection and original dictionary live
            # beside its managed manifest, inside this same operator archive.
            path = self.sources / "central" / approval / "manifest.json"
            if read(path, _MAX_REPORT) != raw:
                raise WarehouseError("DATASET_PG_OPERATOR_REVIEW_CHANGED")
        return load_delivery_report(path)

    def _import(self, request):
        review = self._record(self.reviews, request["body"]["review_id"])
        try:
            version = self.warehouse.version(review["version_id"])
        except WarehouseError as error:
            if error.code != "DATASET_PG_VERSION_NOT_FOUND":
                raise
        else:
            if version["semantics_status"] != "SOURCE_REQUIRED":
                return {**version, "import_status": "UNCHANGED", "recovered_existing_version": True}
            # A warehouse created before dictionary receiving may already have
            # this exact edition. Attach its original meaning file through the
            # same import transaction, without copying rows or moving a view.
        return self.warehouse.import_delivery(
            self._review_delivery(review), DatasetMapping.from_record(review["mapping"]),
            expected_version=review["version_id"])

    def _activate(self, request):
        body, baseline = request["body"], request["baseline"]
        expected = body["expected_revision"]
        current = self.warehouse.current(body["name"])
        if current["revision"] == expected:
            return self.warehouse.activate(body["name"], body["version_id"], expected_revision=expected)
        # A committed selection may precede later legitimate selections. Recover
        # its original history entry; never replay it against the later revision.
        before = None
        while current["revision"] > expected:
            page = self.warehouse.history(body["name"], before=before, limit=100)
            for row in page["history"]:
                if row["revision"] == expected + 1:
                    old_version = baseline["version"]["version_id"] if baseline.get("version") else None
                    if row["version_id"] != body["version_id"] or row["previous_version"] != old_version:
                        raise WarehouseError("DATASET_PG_VIEW_CHANGED")
                    return {"status": "RECOVERED", "name": body["name"],
                            "qualified_view": baseline["qualified_view"], "revision": row["revision"],
                            "version": self.warehouse.version(body["version_id"]),
                            "activation": row, "observed_current": current}
                if row["revision"] <= expected:
                    raise WarehouseError("DATASET_PG_VIEW_CHANGED")
            before = page["next_before"]
            if before is None:
                break
        raise WarehouseError("DATASET_PG_VIEW_CHANGED")

    def _action(self, route, body):
        if route == "/api/import":
            fields(body, ("review_id", "request_id"))
            _id(body["review_id"])
        elif route == "/api/activate":
            fields(body, ("name", "version_id", "expected_revision", "request_id"))
            _text(body["name"], 63, required=True)
            integer(body["expected_revision"], maximum=9007199254740991)
        elif route == "/api/period-reports":
            fields(body, ("selection", "request_id"))
            from .postgres_reports import selection
            selection(body["selection"])
        else:
            raise WarehouseError("DATASET_PG_OPERATOR_ROUTE_NOT_FOUND")
        request_id = _id(body["request_id"])
        path = self.requests / (request_id + ".json")
        if path.exists():
            request = self._record(self.requests, request_id)
            if request.get("route") != route or request.get("body") != body:
                raise WarehouseError("DATASET_PG_OPERATOR_ORIGINAL_REQUEST_CHANGED")
        else:
            request = {**self.identity, "record_id": request_id, "created_at": _now(),
                       "state": "PREPARED", "route": route, "body": body}
            if route == "/api/import":
                self._record(self.reviews, body["review_id"])
            elif route == "/api/period-reports":
                self.warehouse.version(body["selection"]["previous_version"])
                self.warehouse.version(body["selection"]["current_version"])
            else:
                self.warehouse.version(body["version_id"])
                baseline = self.warehouse.current(body["name"])
                if baseline["revision"] != body["expected_revision"]:
                    raise WarehouseError("DATASET_PG_VIEW_CHANGED")
                request["baseline"] = baseline
            dump(path, request, exclusive=True)
        if request["state"] == "COMPLETE":
            if route == "/api/period-reports":
                from .postgres_reports import build_report
                reopened = build_report(self.warehouse, self.reports, request_id, body["selection"])
                prior = request.get("result") or {}
                artifact = dict(prior.get("artifact") or {})
                artifact["path"] = reopened["artifact"]["path"]
                if {**prior, "artifact": artifact} != wire(reopened):
                    raise WarehouseError("DATASET_PG_REPORT_RECORD_CHANGED")
                if prior != wire(reopened):
                    request["result"] = wire(reopened)
                    request["updated_at"] = _now()
                    dump(path, request)
            return request
        request.update(state="RUNNING", updated_at=_now())
        request.pop("error", None)
        dump(path, request)
        try:
            if route == "/api/period-reports":
                from .postgres_reports import build_report
                result = build_report(self.warehouse, self.reports, request_id, body["selection"])
            else:
                result = self._import(request) if route == "/api/import" else self._activate(request)
            request.update(state="COMPLETE", result=wire(result), updated_at=_now())
            dump(path, request)
            return request
        except Exception as error:
            request.update(state="INTERRUPTED", updated_at=_now(),
                           error=error.report() if isinstance(error, WarehouseError)
                           else {"error": error.code if isinstance(error, BuyerError)
                                 else "DATASET_PG_OPERATOR_OPERATION_INTERRUPTED"})
            try:
                dump(path, request)
            except (OSError, BuyerError):
                pass
            raise

    def report_stream(self, request_id):
        from .postgres_reports import open_report
        request = self._record(self.requests, request_id)
        if request.get("route") != "/api/period-reports" or request.get("state") != "COMPLETE":
            raise WarehouseError("DATASET_PG_REPORT_COMPLETE_REQUEST_REQUIRED")
        return open_report(self.reports, request_id, request["result"]["artifact"])

    def central_source(self, approval_path, expected_approval_sha256, source_workspace):
        from .postgres_central import prepare_central
        return prepare_central(approval_path, expected_approval_sha256, source_workspace,
                               self.sources / "central")

    def perform(self, route, body):
        with self.mutex:
            if route == "/api/inspect-delivery":
                fields(body, ("report_path",))
                return self.inspect_delivery(body["report_path"])
            if route == "/api/reviews":
                return self.review(body)
            return self._action(route, body)

    def resume(self, request_id):
        with self.mutex:
            original = self._record(self.requests, request_id)
            return self._action(original["route"], original["body"])

    def review_record(self, review_id):
        with self.mutex:
            return self._record(self.reviews, review_id)

    def request_record(self, request_id):
        with self.mutex:
            return self._record(self.requests, request_id)

"""Run one Linux command with ownership of all of its descendants.

Each command has a separate child subreaper. Detached browser processes are
adopted there when their parent exits. The supervisor signals and reaps only
its own children, including later generations, before reporting completion.
"""
from __future__ import annotations

from contextlib import contextmanager
import ctypes
import json
import locale
import math
import os
import re
from pathlib import Path
import select
import signal
import subprocess
import sys
import threading
import time


@contextmanager
def cancellation():
    """Make default termination unwind Python contexts on the main thread."""
    previous = {}

    def interrupted(number, _frame):
        raise SystemExit(128 + number)

    if threading.current_thread() is threading.main_thread():
        for number in (signal.SIGTERM, signal.SIGHUP):
            handler = signal.getsignal(number)
            if handler == signal.SIG_DFL:
                previous[number] = handler
                signal.signal(number, interrupted)
    try:
        yield
    finally:
        for number, handler in previous.items():
            signal.signal(number, handler)


def _close(descriptor):
    if descriptor is not None:
        os.close(descriptor)


@contextmanager
def _defer_cancellation(*, replay=True):
    """Keep Python signal exceptions outside assignment and cleanup windows."""
    previous = {}
    pending = []

    def defer(number, frame):
        if not pending:
            pending.append((number, frame))

    if threading.current_thread() is threading.main_thread():
        for number in (signal.SIGTERM, signal.SIGINT, signal.SIGHUP):
            handler = signal.getsignal(number)
            if callable(handler) or handler == signal.SIG_DFL:
                previous[number] = handler
                signal.signal(number, defer)
    try:
        yield
    finally:
        for number, handler in previous.items():
            signal.signal(number, handler)
        if pending and replay:
            number, frame = pending[0]
            handler = previous[number]
            if callable(handler):
                handler(number, frame)
            elif number == signal.SIGINT:
                raise KeyboardInterrupt
            else:
                raise SystemExit(128 + number)


def run_owned(argv, *, timeout=120, env=None, cwd=None, text=True):
    """Return CompletedProcess after the command's complete process tree exits.

    The command has the supplied environment and inherited stdin. Its original
    stdout/stderr and return code are preserved. TimeoutExpired is raised only
    after owned descendants have been terminated and reaped. A caller that
    exits abruptly closes its lifetime pipe and starts the same cleanup.
    """
    if sys.platform != "linux":
        raise RuntimeError("Owned receiving commands require Linux.")
    if timeout is not None and (not math.isfinite(timeout) or timeout <= 0):
        raise ValueError("Command timeout must be a finite positive duration.")
    argv = [os.fsdecode(value) for value in argv]
    if not argv:
        raise ValueError("Provide the original command.")
    status_read = status_write = life_read = life_write = None
    process = None
    try:
        with cancellation():
            try:
                # Defer Python exceptions, not the OS signal mask. The spawned
                # command must inherit an ordinary unblocked signal mask.
                with _defer_cancellation():
                    status_read, status_write = os.pipe()
                    life_read, life_write = os.pipe()
                    process = subprocess.Popen(
                        [sys.executable, "-B", str(Path(__file__).resolve()), "--supervise",
                         str(status_write), str(life_read),
                         "none" if timeout is None else str(timeout), *argv],
                        env=env, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                        pass_fds=(status_write, life_read), start_new_session=True)
                    _close(status_write)
                    status_write = None
                    _close(life_read)
                    life_read = None
                stdout, stderr = process.communicate()
                raw = bytearray()
                while chunk := os.read(status_read, 4096):
                    raw.extend(chunk)
                    if len(raw) > 65536:
                        raise RuntimeError("Owned command status exceeded its size limit.")
                try:
                    status = json.loads(raw)
                except (UnicodeDecodeError, ValueError) as error:
                    raise RuntimeError("Owned command supervisor did not return its status.") from error
                if process.returncode != 0 or not status.get("cleanup_complete"):
                    raise RuntimeError("Owned command cleanup did not complete: " + str(status.get("error", status)))
                if status["reason"] == "TIMEOUT":
                    error = subprocess.TimeoutExpired(argv, timeout, output=stdout, stderr=stderr)
                    error.owned_processes = status
                    raise error
                if status["reason"] != "EXITED":
                    raise RuntimeError("Owned command stopped: " + str(status.get("error", status["reason"])))
                if text:
                    encoding = locale.getpreferredencoding(False)
                    stdout, stderr = stdout.decode(encoding), stderr.decode(encoding)
                result = subprocess.CompletedProcess(argv, status["returncode"], stdout, stderr)
                result.owned_processes = status
                return result
            except BaseException:
                if process is not None:
                    # Every post-launch failure, including signal delivery during
                    # fd closure or status parsing, joins cleanup before returning.
                    with _defer_cancellation(replay=False):
                        _close(life_write)
                        life_write = None
                        process.communicate()
                raise
    finally:
        for descriptor in (status_read, status_write, life_read, life_write):
            _close(descriptor)


# Adapted from the maintained LocalDeviceAgent tools/cloud_build_runtime.py
# OwnedChildren implementation (source c4b3b0f8294dd10b1a1f51f30fdc9ed8127ea02a).
class OwnedChildren:
    """Adopt this command's detached descendants and bind signals to their identity."""
    def __init__(self):
        self.depth = len(self._namespace_pids(Path('/proc/self/status'))) - 1
        self.host_pid = int(Path('/proc/self/stat').read_text().split(' ', 1)[0])
        if self.children():
            raise OSError('run the receiving supervisor as its own process before starting a command')
        self.handles = {}
        self.sent = {}
        self.leader_reaped = False
        self.closed = False
        # Check pidfd support before launching native work. Descriptors bind a
        # signal to one process even when a PID namespace or PID reuse is involved.
        os.close(os.pidfd_open(os.getpid()))
        self.libc = ctypes.CDLL(None, use_errno=True)
        previous = ctypes.c_int()
        if self.libc.prctl(37, ctypes.byref(previous), 0, 0, 0) != 0:  # PR_GET_CHILD_SUBREAPER
            raise OSError(ctypes.get_errno(), 'cannot read Linux child adoption setting')
        self.previous = previous.value
        if self.libc.prctl(36, 1, 0, 0, 0) != 0:  # PR_SET_CHILD_SUBREAPER
            raise OSError(ctypes.get_errno(), 'cannot adopt receiving command descendants')

    @staticmethod
    def _namespace_pids(status):
        match = re.search(r'(?m)^NSpid:\s*([0-9 \t]+)$', status.read_text())
        if not match:
            raise OSError('Linux process namespace mapping is unavailable')
        return [int(value) for value in match[1].split()]

    def children(self):
        result = set()
        child_list = Path(f'/proc/self/task/{self.host_pid}/children')
        if child_list.is_file():
            host_children = child_list.read_text().split()
        else:
            # Some cloud kernels omit the optional per-thread children file.
            # Read numeric ancestry only, never other commands or environments.
            host_children = []
            for directory in Path('/proc').iterdir():
                if directory.name.isdecimal():
                    try:
                        fields = (directory / 'stat').read_text().rsplit(')', 1)[1].split()
                        if int(fields[1]) == self.host_pid:
                            host_children.append(directory.name)
                    except (OSError, IndexError, ValueError):
                        continue
        # /proc may be mounted in an ancestor PID namespace. Translate ONLY
        # our direct children's IDs instead of treating host IDs as local PIDs.
        for host_pid in host_children:
            try:
                ids = self._namespace_pids(Path('/proc') / host_pid / 'status')
                if len(ids) <= self.depth:
                    raise OSError('child process namespace mapping is unavailable')
                result.add(ids[self.depth])
            except FileNotFoundError:
                continue
        return result

    def collect(self, root_pid):
        for pid in self.children() - {root_pid}:
            if pid not in self.handles:
                try:
                    self.handles[pid] = os.pidfd_open(pid)
                except ProcessLookupError:
                    continue
        for pid, handle in list(self.handles.items()):
            if select.select([handle], [], [], 0)[0]:
                try:
                    os.waitpid(pid, os.WNOHANG)
                except ChildProcessError:
                    pass
                os.close(handle)
                del self.handles[pid]
                self.sent.pop(pid, None)

    def leader_exited(self, process):
        """Observe our child without releasing its PID or process-group identity."""
        if self.leader_reaped:
            return True
        if process.returncode is not None:
            raise OSError('receiving command leader was reaped before owned cleanup')
        try:
            status = os.waitid(os.P_PID, process.pid,
                               os.WEXITED | os.WNOHANG | os.WNOWAIT)
        except ChildProcessError:
            raise OSError('receiving command leader is no longer a retained child') from None
        return status is not None

    def stop(self, process):
        if self.leader_reaped:
            self.close()
            return
        for signum in (signal.SIGTERM, signal.SIGKILL):
            # Keep the leader waitable through the last group signal. Reaping it
            # first would allow an unrelated process group to reuse this number.
            self.leader_exited(process)
            try:
                os.killpg(process.pid, signum)
            except ProcessLookupError:
                pass
            deadline = time.monotonic() + 5
            while time.monotonic() < deadline:
                leader_exited = self.leader_exited(process)
                self.collect(process.pid)
                for pid, handle in self.handles.items():
                    if self.sent.get(pid) != signum:
                        try:
                            signal.pidfd_send_signal(handle, signum)
                        except ProcessLookupError:
                            pass
                        self.sent[pid] = signum
                # A retained zombie leader still belongs to its group. Use the
                # child tree for completion, including descendants adopted while
                # collect() was reaping an exited parent in a detached session.
                if (leader_exited and not self.handles
                        and not (self.children() - {process.pid})):
                    process.wait()
                    self.leader_reaped = True
                    self.close()
                    return
                time.sleep(0.1)
        raise subprocess.TimeoutExpired('owned receiving command processes', 10)

    def close(self):
        if self.closed:
            return
        if self.libc.prctl(36, self.previous, 0, 0, 0) != 0:
            raise OSError(ctypes.get_errno(), 'cannot restore Linux child adoption setting')
        self.closed = True



def _supervise(status_fd, life_fd, timeout, argv):
    result = {"reason": "RUNNING", "returncode": None, "cleanup_complete": False,
              "subreaper": True}
    process = None
    scope = None
    stop_signal = None

    def request_stop(number, _frame):
        nonlocal stop_signal
        stop_signal = number

    for number in (signal.SIGTERM, signal.SIGINT, signal.SIGHUP):
        signal.signal(number, request_stop)
    # Adopted descendants must remain waitable if the caller ignored SIGCHLD.
    signal.signal(signal.SIGCHLD, signal.SIG_DFL)
    os.set_blocking(life_fd, False)

    def parent_exited():
        try:
            return os.read(life_fd, 1) == b""
        except BlockingIOError:
            return False

    try:
        scope = OwnedChildren()
        if parent_exited():
            result["reason"] = "PARENT_EXITED"
        else:
            process = subprocess.Popen(argv, start_new_session=True)
            deadline = None if timeout is None else time.monotonic() + timeout
            while True:
                scope.collect(process.pid)
                if scope.leader_exited(process):
                    result["reason"] = "EXITED"
                    break
                if stop_signal is not None:
                    result["reason"] = "INTERRUPTED"
                    result["signal"] = stop_signal
                    break
                if parent_exited():
                    result["reason"] = "PARENT_EXITED"
                    break
                if deadline is not None and time.monotonic() >= deadline:
                    result["reason"] = "TIMEOUT"
                    break
                select.select([life_fd], [], [], 0.05)
    except BaseException as error:
        result["reason"] = "SUPERVISOR_ERROR"
        result["error"] = str(error)[:512]
    finally:
        try:
            if scope is not None:
                if process is not None:
                    # Keep adoption active until the complete tree has exited.
                    # A kernel task awaiting I/O may take longer to accept KILL.
                    while True:
                        try:
                            scope.stop(process)
                            break
                        except subprocess.TimeoutExpired:
                            continue
                    result["returncode"] = process.returncode
                else:
                    scope.close()
            result["cleanup_complete"] = True
        except BaseException as error:
            result["error"] = str(error)[:512]
        raw = (json.dumps(result, ensure_ascii=False, separators=(",", ":")) + "\n").encode()
        # The caller drains command stdout/stderr before this status pipe. Keep
        # the complete status within one atomic pipe write, including errors.
        limit = os.fpathconf(status_fd, "PC_PIPE_BUF")
        if len(raw) > limit:
            result["error"] = "Supervisor error detail exceeded the status channel capacity."
            raw = (json.dumps(result, ensure_ascii=False, separators=(",", ":")) + "\n").encode()
        if len(raw) > limit:
            raise RuntimeError("Owned command status channel is too small.")
        try:
            while raw:
                written = os.write(status_fd, raw)
                if written == 0:
                    raise OSError("Owned command status pipe closed.")
                raw = raw[written:]
        except BrokenPipeError:
            pass
        finally:
            os.close(status_fd)
            os.close(life_fd)
    return 0 if result["cleanup_complete"] else 1


if __name__ == "__main__":
    if len(sys.argv) < 6 or sys.argv[1] != "--supervise":
        raise SystemExit("Use run_owned() with the original command.")
    duration = None if sys.argv[4] == "none" else float(sys.argv[4])
    raise SystemExit(_supervise(int(sys.argv[2]), int(sys.argv[3]), duration, sys.argv[5:]))

"""Customer data profiles over the original local analysis workspace.

Use --launch with an already running browser workspace, or --workspace to own
its existing process lease for the duration of this command. Offline documents
need neither. The CLI never starts a separate HTTP server or payment runtime.
"""
from __future__ import annotations

import argparse
from contextlib import contextmanager
import http.client
import json
from pathlib import Path
import sys
import time
from urllib.parse import urlencode, urlsplit
import uuid

from .dataset_profiles import ProfileDocument, _json, _MAX_DOCUMENT
from .errors import BuyerError, StateError
from .storage import digest, parse, read, write


class _Remote:
    def __init__(self, launch):
        record = parse(read(Path(launch), 1024 * 1024))
        url = urlsplit(record.get("url", ""))
        if url.scheme != "http" or url.hostname != "127.0.0.1" or not url.port or url.username or url.password or url.query or url.path not in {"/", ""} or not url.fragment:
            raise StateError("DATA_PROFILE_ORIGINAL_LOOPBACK_LAUNCH_REQUIRED")
        self.port, self.capability = url.port, url.fragment

    def request(self, path, body=None, *, raw=False):
        connection = http.client.HTTPConnection("127.0.0.1", self.port, timeout=60)
        try:
            headers = {"X-Analysis-Capability": self.capability, "Content-Type": "application/json"}
            connection.request("GET" if body is None else "POST", path, None if body is None else _json(body).encode(), headers)
            response = connection.getresponse()
            data = response.read(_MAX_DOCUMENT + 1)
            if len(data) > _MAX_DOCUMENT:
                raise StateError("DATA_PROFILE_RESPONSE_TOO_LARGE")
            if response.status >= 400:
                result = parse(data)
                raise StateError(str(result.get("error", "DATA_PROFILE_HTTP_FAILED"))[:256])
            return data if raw else parse(data)
        finally:
            connection.close()

    def versions(self, before=None):
        return self.request("/api/versions" + ("?" + urlencode({"before": before}) if before else ""))

    def history(self, before=None):
        return self.request("/api/profiles" + ("?" + urlencode({"before": before}) if before else ""))

    def start(self, spec):
        return self.request("/api/start/profile", spec)

    def job(self, job_id):
        return self.request("/api/jobs/" + job_id)

    def document(self, job_id):
        return ProfileDocument(self.request("/api/profiles/" + job_id))

    def cancel(self, job_id):
        return self.request("/api/profiles/" + job_id + "/cancel", {})

    def compare(self, before, after):
        return self.request("/api/profile-compare?" + urlencode({"before": before, "after": after}))

    def review(self, job_id, spec):
        return self.request("/api/profiles/" + job_id + "/review", spec)

    def frequency(self, job_id, column):
        return self.request("/api/profiles/" + job_id + "/frequency?" + urlencode({"column": column}))


class _Local:
    def __init__(self, workspace):
        self.workspace = workspace

    def versions(self, before=None):
        return self.workspace.database.versions(before=before, limit=25)

    def history(self, before=None):
        return self.workspace.profiles.history(before=before)

    def start(self, spec):
        return self.workspace.start("profile", spec)

    def job(self, job_id):
        return self.workspace.job(job_id)

    def document(self, job_id):
        return self.workspace.profiles.document(job_id)

    def cancel(self, job_id):
        return self.workspace.profiles.cancel(job_id)

    def compare(self, before, after):
        return self.workspace.profiles.compare(before, after)

    def review(self, job_id, spec):
        return self.workspace.profiles.save_review(job_id, spec)

    def frequency(self, job_id, column):
        return self.workspace.profiles.frequency_query(job_id, column)


@contextmanager
def _client(args):
    if args.launch:
        yield _Remote(args.launch)
        return
    if not args.workspace:
        raise StateError("DATA_PROFILE_WORKSPACE_OR_LAUNCH_REQUIRED")
    from .analysis_workspace import AnalysisWorkspace
    workspace = AnalysisWorkspace(args.workspace)
    try:
        yield _Local(workspace)
    finally:
        workspace.close()


def _emit(value, destination=None):
    raw = (_json(value) + "\n").encode()
    if destination:
        write(Path(destination), raw, exclusive=True)
        print(_json({"path": str(destination), "bytes": len(raw), "sha256": digest(raw)}))
    else:
        print(raw.decode(), end="")


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    owner = parser.add_mutually_exclusive_group()
    owner.add_argument("--launch", help="Existing private analysis-launch.json; use the live original server")
    owner.add_argument("--workspace", help="Existing customer database directory; own its original process lease")
    sub = parser.add_subparsers(dest="command", required=True)
    for name in ("versions", "history"):
        p = sub.add_parser(name);p.add_argument("--before", type=int)
    p = sub.add_parser("run", help="Profile all rows of an exact imported version")
    p.add_argument("--version", required=True);p.add_argument("--id", default=None)
    p.add_argument("--column", action="append");p.add_argument("--top-values", type=int, default=12)
    p.add_argument("--timeout", type=int, default=3600)
    p.add_argument("--no-wait", action="store_true", help="Only with --launch; retain the original job ID for later inspection")
    for name in ("show", "cancel"):
        p = sub.add_parser(name);p.add_argument("--id", required=True)
    p = sub.add_parser("export");p.add_argument("--id", required=True)
    p.add_argument("--format", choices=("json", "html"), default="json");p.add_argument("--out", required=True)
    p = sub.add_parser("review");p.add_argument("--id", required=True)
    p.add_argument("--request", required=True, help="JSON: id, profile_sha256, expected_revision, decision, note, column_notes")
    p = sub.add_parser("frequency");p.add_argument("--id", required=True);p.add_argument("--column", required=True)
    p = sub.add_parser("compare");p.add_argument("--before", required=True);p.add_argument("--after", required=True);p.add_argument("--out")
    p = sub.add_parser("inspect-file");p.add_argument("--file", required=True)
    p = sub.add_parser("compare-files");p.add_argument("--before", required=True);p.add_argument("--after", required=True);p.add_argument("--out")
    args = parser.parse_args(argv)
    try:
        if args.command == "inspect-file":
            _emit(ProfileDocument.open(args.file).record);return 0
        if args.command == "compare-files":
            _emit(ProfileDocument.open(args.before).compare(ProfileDocument.open(args.after)), args.out);return 0
        if args.command == "run" and args.no_wait and not args.launch:
            raise StateError("DATA_PROFILE_NO_WAIT_REQUIRES_RUNNING_WORKSPACE")
        with _client(args) as client:
            if args.command == "versions":
                _emit(client.versions(args.before))
            elif args.command == "history":
                _emit(client.history(args.before))
            elif args.command == "show":
                _emit(client.job(args.id))
            elif args.command == "cancel":
                _emit(client.cancel(args.id))
            elif args.command == "review":
                _emit(client.review(args.id, parse(read(Path(args.request), 128 * 1024))))
            elif args.command == "frequency":
                _emit(client.frequency(args.id, args.column))
            elif args.command == "compare":
                _emit(client.compare(args.before, args.after), args.out)
            elif args.command == "export":
                _emit(client.document(args.id).write(args.out, format=args.format))
            elif args.command == "run":
                job = client.start({"id": args.id or uuid.uuid4().hex, "version_id": args.version,
                    "columns": args.column, "top_values": args.top_values, "timeout": args.timeout})
                if args.no_wait:
                    _emit(job);return 0
                try:
                    while job["status"] == "RUNNING":
                        time.sleep(.2)
                        job = client.job(job["id"])
                except KeyboardInterrupt:
                    client.cancel(job["id"])
                    _emit({"id": job["id"], "cancellation_requested": True})
                    return 130
                _emit(job)
                return 0 if job["status"] == "COMPLETE" else 1
        return 0
    except (BuyerError, OSError, http.client.HTTPException, ValueError) as exc:
        _emit({"error": getattr(exc, "code", type(exc).__name__)})
        return 1


if __name__ == "__main__":
    sys.exit(main())

"""Complete, portable query results from the original customer DatasetDatabase.

Run ``python -m stellar_forge_buyer.query_export --help`` for the offline CLI.
"""
from __future__ import annotations

import argparse
import base64
from contextlib import ExitStack, contextmanager
from copy import deepcopy
from datetime import datetime, timezone
import csv
import hashlib
import io
import json
import math
